"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7692],{7692:function(e,n,a){a.d(n,{w:function(){return t}});let t=[{id:"grammar-1-1",hsk_level:1,pattern:"S + 是 + O",title:'判断句"是"字句',explanation_zh:'用"是"表示判断，说明主语是什么、属于什么类别。',explanation_en:'Use "shi" to indicate identity or classification.',example_zh:"我是学生。\n这是书。\n他是我爸爸。",example_pinyin:"Wǒ sh\xec xu\xe9shēng.\nZh\xe8 sh\xec shū.\nTā sh\xec wǒ b\xe0ba.",example_en:"I am a student.\nThis is a book.\nHe is my father.",usage_notes:"否定形式：S + 不是 + O",category:"句型"},{id:"grammar-1-2",hsk_level:1,pattern:"S + 的 + O",title:'"的"字结构（所属）',explanation_zh:'表示所属关系，"的"连接修饰语和中心词。',explanation_en:"Indicates possession or attribution.",example_zh:"这是我的书。\n你叫什么名字？\n他的手机很漂亮。",example_pinyin:"Zh\xe8 sh\xec wǒ de shū.\nNǐ ji\xe0o sh\xe9nme m\xedngzi?\nTā de shǒujī hěn pi\xe0oliang.",example_en:"This is my book.\nWhat is your name?\nHis mobile phone is very beautiful.",usage_notes:"人称代词+的+名词，表示所属关系",category:"助词"},{id:"grammar-1-3",hsk_level:1,pattern:"S + 很 + Adj",title:"形容词谓语句",explanation_zh:'形容词直接作谓语，前面常用"很"等程度副词修饰。',explanation_en:'Adjectives function directly as predicates, often modified by degree adverbs like "hen".',example_zh:"我妈妈很好。\n今天天气很热。\n这个菜很好吃。",example_pinyin:"Wǒ māma hěn hǎo.\nJīntiān tiānq\xec hěn r\xe8.\nZh\xe8ge c\xe0i hěn hǎochī.",example_en:"My mother is very well.\nToday the weather is very hot.\nThis dish is very delicious.",usage_notes:'"很"在这里不一定表示程度高，只是句子结构的需要',category:"句型"},{id:"grammar-1-4",hsk_level:1,pattern:"S + V + O",title:"动词谓语句（基本句）",explanation_zh:"主语+动词+宾语，最基本的汉语句子结构。",explanation_en:"Subject + verb + object, the most basic Chinese sentence structure.",example_zh:"我吃饭。\n他看书。\n我们学习汉语。",example_pinyin:"Wǒ chī f\xe0n.\nTā k\xe0n shū.\nWǒmen xu\xe9x\xed h\xe0nyǔ.",example_en:"I eat rice.\nHe reads a book.\nWe study Chinese.",usage_notes:"动词后面可以带宾语，宾语一般在动词后面",category:"句型"},{id:"grammar-1-5",hsk_level:1,pattern:"S + 有 + O",title:'"有"字句（领有）',explanation_zh:"表示领有、具有，主语一般是人或物。",explanation_en:"Indicates possession or ownership, subject is usually a person or thing.",example_zh:"我有一个妹妹。\n他有很多钱。\n学校有一个图书馆。",example_pinyin:"Wǒ yǒu y\xed g\xe8 m\xe8imei.\nTā yǒu hěn duō qi\xe1n.\nXu\xe9xi\xe0o yǒu y\xed g\xe8 t\xfashūguǎn.",example_en:"I have a younger sister.\nHe has a lot of money.\nThe school has a library.",usage_notes:"否定形式：没有；疑问形式：有没有",category:"句型"},{id:"grammar-1-6",hsk_level:1,pattern:"处所 + 有 + N",title:'"有"字句（存在）',explanation_zh:"表示某处存在某人或某物。",explanation_en:"Indicates existence of someone or something in a place.",example_zh:"教室里有很多学生。\n桌子上有一本书。\n我家有三口人。",example_pinyin:"Ji\xe0osh\xec lǐ yǒu hěn duō xu\xe9shēng.\nZhuōzi sh\xe0ng yǒu y\xec běn shū.\nWǒ jiā yǒu sān kǒu r\xe9n.",example_en:"There are many students in the classroom.\nThere is a book on the table.\nThere are three people in my family.",usage_notes:"处所词放在句首作主语",category:"句型"},{id:"grammar-1-7",hsk_level:1,pattern:"数词 + 量词 + 名词",title:"数量短语",explanation_zh:"数词和名词之间必须用量词，不同的名词用不同的量词。",explanation_en:"A measure word must be used between a number and a noun, different nouns use different measure words.",example_zh:"三个人\n两本书\n一杯茶",example_pinyin:"sān g\xe8 r\xe9n\nliǎng běn shū\ny\xec bēi ch\xe1",example_en:"three people\ntwo books\na cup of tea",usage_notes:'"个"是最常用的量词，很多名词都可以用"个"',category:"量词"},{id:"grammar-1-8",hsk_level:1,pattern:"这/那 + (量词) + 名词",title:'指示代词"这/那"',explanation_zh:'"这"指近处的人或事物，"那"指远处的人或事物。',explanation_en:'"Zhe" refers to people or things nearby, "na" refers to people or things far away.',example_zh:"这是我的书。\n那个人是谁？\n这些苹果很好吃。",example_pinyin:"Zh\xe8 sh\xec wǒ de shū.\nN\xe0 ge r\xe9n sh\xec shu\xed?\nZh\xe8xiē p\xedngguǒ hěn hǎochī.",example_en:"This is my book.\nWho is that person?\nThese apples are very delicious.",usage_notes:"复数形式：这些/那些",category:"代词"},{id:"grammar-1-9",hsk_level:1,pattern:"谁/什么/哪/几/多少",title:"疑问代词",explanation_zh:"用来构成特指疑问句，放在句子中相应的位置。",explanation_en:"Used to form specific questions, placed in the corresponding position in the sentence.",example_zh:"你是谁？\n这是什么？\n你有几本书？",example_pinyin:"Nǐ sh\xec shu\xed?\nZh\xe8 sh\xec sh\xe9nme?\nNǐ yǒu jǐ běn shū?",example_en:"Who are you?\nWhat is this?\nHow many books do you have?",usage_notes:"疑问代词不用放在句首，放在它所代表的成分的位置上",category:"代词"},{id:"grammar-1-10",hsk_level:1,pattern:"S + 不 + V/Adj",title:'否定副词"不"',explanation_zh:'用"不"否定动词或形容词，表示否定。',explanation_en:'Use "bu" to negate verbs or adjectives, expressing negation.',example_zh:"我不是学生。\n他不喜欢喝咖啡。\n这个菜不辣。",example_pinyin:"Wǒ b\xfa sh\xec xu\xe9shēng.\nTā b\xf9 xǐhuan hē kāfēi.\nZh\xe8ge c\xe0i b\xf9 l\xe0.",example_en:"I am not a student.\nHe does not like to drink coffee.\nThis dish is not spicy.",usage_notes:'"不"在四声字前读第二声，如"不是"读作b\xfa sh\xec',category:"副词"},{id:"grammar-1-11",hsk_level:1,pattern:"S + 也 + V/Adj",title:'副词"也"',explanation_zh:"表示同样、相同，放在动词或形容词前面。",explanation_en:"Indicates similarity or sameness, placed before the verb or adjective.",example_zh:"我也是学生。\n他也喜欢汉语。\n今天也很热。",example_pinyin:"Wǒ yě sh\xec xu\xe9shēng.\nTā yě xǐhuan h\xe0nyǔ.\nJīntiān yě hěn r\xe8.",example_en:"I am also a student.\nHe also likes Chinese.\nToday is also very hot.",usage_notes:'"也"放在主语后，动词前',category:"副词"},{id:"grammar-1-12",hsk_level:1,pattern:"S + 都 + V/Adj",title:'副词"都"',explanation_zh:"表示总括全部，主语一般是复数。",explanation_en:"Indicates all or entirely, the subject is usually plural.",example_zh:"我们都是学生。\n他们都去。\n这些书都很好。",example_pinyin:"Wǒmen dōu sh\xec xu\xe9shēng.\nTāmen dōu q\xf9.\nZh\xe8xiē shū dōu hěn hǎo.",example_en:"We are all students.\nThey are all going.\nThese books are all very good.",usage_notes:'"都"放在主语后，动词前；如果有"也"，"也"在"都"前',category:"副词"},{id:"grammar-1-13",hsk_level:1,pattern:"很/太/非常 + Adj",title:"程度副词",explanation_zh:"用来表示程度，放在形容词前面。",explanation_en:"Used to indicate degree, placed before adjectives.",example_zh:"她很漂亮。\n今天太热了。\n我非常喜欢汉语。",example_pinyin:"Tā hěn pi\xe0oliang.\nJīntiān t\xe0i r\xe8 le.\nWǒ fēich\xe1ng xǐhuan h\xe0nyǔ.",example_en:"She is very beautiful.\nToday is too hot.\nI extremely like Chinese.",usage_notes:'"很"程度一般，"太"程度高且常含感叹语气，"非常"程度很高',category:"副词"},{id:"grammar-1-14",hsk_level:1,pattern:"S + 在 + 处所",title:'"在"表示位置',explanation_zh:"表示人或事物所在的位置。",explanation_en:"Indicates the location of a person or thing.",example_zh:"我在学校。\n书在桌子上。\n爸爸在公司。",example_pinyin:"Wǒ z\xe0i xu\xe9xi\xe0o.\nShū z\xe0i zhuōzi sh\xe0ng.\nB\xe0ba z\xe0i gōngsī.",example_en:"I am at school.\nThe book is on the table.\nFather is at the company.",usage_notes:'"在"是动词，否定形式用"不在"',category:"介词"},{id:"grammar-1-15",hsk_level:1,pattern:"S + 在 + V",title:'"在"表示动作正在进行',explanation_zh:"表示动作正在进行或状态正在持续。",explanation_en:"Indicates an action in progress or an ongoing state.",example_zh:"我在吃饭。\n他在看书。\n妈妈在做饭。",example_pinyin:"Wǒ z\xe0i chī f\xe0n.\nTā z\xe0i k\xe0n shū.\nMāma z\xe0i zu\xf2 f\xe0n.",example_en:"I am eating.\nHe is reading a book.\nMother is cooking.",usage_notes:"否定形式：S + 没(有) + 在 + V",category:"副词"},{id:"grammar-1-16",hsk_level:1,pattern:"时间词 + S + V + O",title:"时间词语的位置",explanation_zh:"时间词语一般放在主语前面或主语后面、动词前面。",explanation_en:"Time expressions are usually placed before the subject or after the subject and before the verb.",example_zh:"今天我去学校。\n我明天去北京。\n晚上我们看电视。",example_pinyin:"Jīntiān wǒ q\xf9 xu\xe9xi\xe0o.\nWǒ m\xedngtiān q\xf9 běijīng.\nWǎnshang wǒmen k\xe0n di\xe0nsh\xec.",example_en:"Today I go to school.\nI will go to Beijing tomorrow.\nWe watch TV in the evening.",usage_notes:"时间词可以放在句首，也可以放在主语后动词前",category:"句型"},{id:"grammar-1-17",hsk_level:1,pattern:"S + V + 吗？",title:'"吗"疑问句',explanation_zh:'在陈述句末尾加"吗"，构成一般疑问句。',explanation_en:'Add "ma" at the end of a declarative sentence to form a yes-no question.',example_zh:"你是学生吗？\n他喜欢汉语吗？\n今天热吗？",example_pinyin:"Nǐ sh\xec xu\xe9shēng ma?\nTā xǐhuan h\xe0nyǔ ma?\nJīntiān r\xe8 ma?",example_en:"Are you a student?\nDoes he like Chinese?\nIs it hot today?",usage_notes:'回答用"是/对"或"不是/不对"，或用动词的肯定/否定形式回答',category:"句型"},{id:"grammar-1-18",hsk_level:1,pattern:"S + V 不 V？",title:"正反疑问句",explanation_zh:"用动词的肯定和否定形式并列提问，回答选择其一。",explanation_en:"Ask a question by juxtaposing the affirmative and negative forms of a verb, answer by choosing one.",example_zh:"你是不是学生？\n他去不去？\n这个菜辣不辣？",example_pinyin:"Nǐ sh\xec bu sh\xec xu\xe9shēng?\nTā q\xf9 bu q\xf9?\nZh\xe8ge c\xe0i l\xe0 bu l\xe0?",example_en:"Are you a student or not?\nIs he going or not?\nIs this dish spicy or not?",usage_notes:"形容词也可以用这种形式提问",category:"句型"},{id:"grammar-1-19",hsk_level:1,pattern:"N + 呢？",title:'语气助词"呢"',explanation_zh:'用于承接上文的疑问，表示"……呢？"的简略问法。',explanation_en:'Used to follow up on a previous question, forming a brief question like "what about...?"',example_zh:"我是学生，你呢？\n这本书是我的，那本呢？\n他去北京，你呢？",example_pinyin:"Wǒ sh\xec xu\xe9shēng, nǐ ne?\nZh\xe8 běn shū sh\xec wǒ de, n\xe0 běn ne?\nTā q\xf9 běijīng, nǐ ne?",example_en:"I am a student, what about you?\nThis book is mine, what about that one?\nHe is going to Beijing, what about you?",usage_notes:'"呢"还可以用在陈述句末，表示持续的状态',category:"助词"},{id:"grammar-1-20",hsk_level:1,pattern:"V + 了",title:'动态助词"了"（动作完成）',explanation_zh:"表示动作已经完成或实现。",explanation_en:"Indicates that an action has been completed or realized.",example_zh:"我吃了饭了。\n他买了一本书。\n我看了那个电影。",example_pinyin:"Wǒ chī le f\xe0n le.\nTā mǎi le y\xec běn shū.\nWǒ k\xe0n le n\xe0 ge di\xe0nyǐng.",example_en:"I have eaten.\nHe bought a book.\nI watched that movie.",usage_notes:'否定形式用"没(有)……"，不用"了"',category:"助词"},{id:"grammar-1-21",hsk_level:1,pattern:"V + 着",title:'动态助词"着"',explanation_zh:"表示动作正在进行或状态正在持续。",explanation_en:"Indicates an action in progress or an ongoing state.",example_zh:"他看着书。\n门口站着一个人。\n墙上挂着一幅画。",example_pinyin:"Tā k\xe0nzhe shū.\nM\xe9nkǒu zh\xe0nzhe y\xed ge r\xe9n.\nQi\xe1ng sh\xe0ng gu\xe0zhe y\xec f\xfa hu\xe0.",example_en:"He is reading a book.\nA person is standing at the door.\nA painting is hanging on the wall.",usage_notes:"否定形式：S + 没(有) + V + 着",category:"助词"},{id:"grammar-1-22",hsk_level:1,pattern:"S + V1 + O1 + V2 + O2",title:"连动句",explanation_zh:"一个主语后面有两个或两个以上的动词或动词短语。",explanation_en:"A subject is followed by two or more verbs or verb phrases.",example_zh:"我去学校上课。\n他来中国旅游。\n我们坐飞机去北京。",example_pinyin:"Wǒ q\xf9 xu\xe9xi\xe0o sh\xe0ng k\xe8.\nTā l\xe1i zhōnggu\xf3 lǚy\xf3u.\nWǒmen zu\xf2 fēijī q\xf9 běijīng.",example_en:"I go to school to attend class.\nHe comes to China to travel.\nWe go to Beijing by plane.",usage_notes:"连动句中动词的顺序不能随意改变，有先后或方式目的关系",category:"句型"},{id:"grammar-1-23",hsk_level:1,pattern:"AA / V一V",title:"动词重叠",explanation_zh:"单音节动词重叠表示动作时间短、尝试、轻松等语气。",explanation_en:"Reduplication of monosyllabic verbs indicates short duration, attempt, or casual tone.",example_zh:"你看看这本书。\n我想想再告诉你。\n你尝尝这个菜。",example_pinyin:"Nǐ k\xe0nkan zh\xe8 běn shū.\nWǒ xiǎngxiang z\xe0i g\xe0osu nǐ.\nNǐ ch\xe1ngchang zh\xe8ge c\xe0i.",example_en:"You take a look at this book.\nLet me think and then tell you.\nYou taste this dish.",usage_notes:"重叠形式：AA式（看看）或V一V式（看一看）",category:"动词"},{id:"grammar-1-24",hsk_level:1,pattern:"AA的 / 很AA",title:"单音节形容词重叠",explanation_zh:"单音节形容词重叠表示程度加深。",explanation_en:"Reduplication of monosyllabic adjectives indicates intensified degree.",example_zh:"她的眼睛大大的。\n今天的菜红红的。\n他高高的个子。",example_pinyin:"Tā de yǎnjing d\xe0d\xe0 de.\nJīntiān de c\xe0i h\xf3ngh\xf3ng de.\nTā gāogāo de g\xe8zi.",example_en:"Her eyes are big.\nToday's dish is red.\nHe is tall in stature.",usage_notes:'重叠后加"的"，程度比原来的形容词高',category:"形容词"},{id:"grammar-1-25",hsk_level:1,pattern:"处所 + V + 着 + N",title:"存现句",explanation_zh:"表示什么地方存在、出现或消失了什么人或物。",explanation_en:"Indicates that someone or something exists, appears, or disappears in a certain place.",example_zh:"桌子上放着一本书。\n墙上挂着一幅画。\n前面来了一个人。",example_pinyin:"Zhuōzi sh\xe0ng f\xe0ngzhe y\xec běn shū.\nQi\xe1ng sh\xe0ng gu\xe0zhe y\xec f\xfa hu\xe0.\nQi\xe1nmian l\xe1i le y\xed ge r\xe9n.",example_en:"A book is placed on the table.\nA painting is hanging on the wall.\nA person is coming from the front.",usage_notes:"句首是处所词，宾语是存现的人或物",category:"句型"},{id:"grammar-1-26",hsk_level:1,pattern:"N + 是 + N + 的",title:"名词谓语句",explanation_zh:"说明日期、天气、籍贯、职业等，谓语是名词性词语。",explanation_en:"Explains date, weather, hometown, occupation, etc., with a nominal predicate.",example_zh:"今天星期一。\n他上海人。\n明天晴天。",example_pinyin:"Jīntiān xīngqīyī.\nTā sh\xe0nghǎi r\xe9n.\nM\xedngtiān q\xedngtiān.",example_en:"Today is Monday.\nHe is from Shanghai.\nTomorrow will be sunny.",usage_notes:'口语中常用，书面语中常加"是"',category:"句型"},{id:"grammar-1-27",hsk_level:1,pattern:"S + 给 + O + V",title:'介词"给"',explanation_zh:"引出动作的接受者或对象。",explanation_en:"Introduces the recipient or object of an action.",example_zh:"我给妈妈打电话。\n他给我一本书。\n请给我一杯水。",example_pinyin:"Wǒ gěi māma dǎ di\xe0nhu\xe0.\nTā gěi wǒ y\xec běn shū.\nQǐng gěi wǒ y\xec bēi shuǐ.",example_en:"I call my mother.\nHe gives me a book.\nPlease give me a glass of water.",usage_notes:'"给"的宾语是动作的接受者',category:"介词"},{id:"grammar-1-28",hsk_level:1,pattern:"S + 跟 / 和 + O + 一起 + V",title:'介词"跟/和"',explanation_zh:"表示共同、一起，引出动作的同伴。",explanation_en:"Indicates togetherness, introduces the companion of an action.",example_zh:"我跟朋友一起去。\n他和家人住在一起。\n我们跟老师学习汉语。",example_pinyin:"Wǒ gēn p\xe9ngyou y\xecqǐ q\xf9.\nTā h\xe9 jiār\xe9n zh\xf9 z\xe0i y\xecqǐ.\nWǒmen gēn lǎoshī xu\xe9x\xed h\xe0nyǔ.",example_en:"I go with friends.\nHe lives with his family.\nWe study Chinese with the teacher.",usage_notes:'"跟"和"和"在这里意思差不多，"跟"更口语化',category:"介词"},{id:"grammar-1-29",hsk_level:1,pattern:"S + V + 得 + Adj",title:"程度补语（简单）",explanation_zh:'在动词后用"得"连接形容词，表示动作的程度或结果。',explanation_en:'Use "de" to connect an adjective after a verb, indicating the degree or result of the action.',example_zh:"他汉语说得很好。\n她跑得很快。\n这个菜做得很好吃。",example_pinyin:"Tā h\xe0nyǔ shuō de hěn hǎo.\nTā pǎo de hěn ku\xe0i.\nZh\xe8ge c\xe0i zu\xf2 de hěn hǎochī.",example_en:"He speaks Chinese very well.\nShe runs very fast.\nThis dish is cooked very deliciously.",usage_notes:"否定形式：V + 得 + 不 + Adj",category:"补语"},{id:"grammar-1-30",hsk_level:1,pattern:"S + 想 / 要 + V",title:'能愿动词"想/要"',explanation_zh:"表示愿望、打算、意图。",explanation_en:"Expresses wish, intention, or plan.",example_zh:"我想去中国。\n他要学汉语。\n你想喝什么？",example_pinyin:"Wǒ xiǎng q\xf9 zhōnggu\xf3.\nTā y\xe0o xu\xe9 h\xe0nyǔ.\nNǐ xiǎng hē sh\xe9nme?",example_en:"I want to go to China.\nHe wants to study Chinese.\nWhat do you want to drink?",usage_notes:'"想"偏重于想法，"要"偏重于决定、打算',category:"动词"},{id:"grammar-2-1",hsk_level:2,pattern:"S + V + 过 + O",title:'动态助词"过"',explanation_zh:"表示过去曾经发生过的动作或经历，强调经验。",explanation_en:"Indicates an action or experience that happened in the past, emphasizing experience.",example_zh:"我去过北京。\n他吃过中国菜。\n你看过这个电影吗？",example_pinyin:"Wǒ q\xf9gu\xf2 běijīng.\nTā chīgu\xf2 zhōnggu\xf3 c\xe0i.\nNǐ k\xe0ngu\xf2 zh\xe8ge di\xe0nyǐng ma?",example_en:"I have been to Beijing.\nHe has eaten Chinese food.\nHave you seen this movie?",usage_notes:'否定形式：没(有) + V + 过；不能和"了"同时用在一个动词后',category:"助词"},{id:"grammar-2-2",hsk_level:2,pattern:"S + V1 + O + V2",title:"兼语句",explanation_zh:"第一个动词的宾语兼作第二个动词的主语。",explanation_en:"The object of the first verb also serves as the subject of the second verb.",example_zh:"老师让我们做作业。\n妈妈叫我吃饭。\n他请我去他家。",example_pinyin:"Lǎoshī r\xe0ng wǒmen zu\xf2 zu\xf2y\xe8.\nMāma ji\xe0o wǒ chī f\xe0n.\nTā qǐng wǒ q\xf9 tā jiā.",example_en:"The teacher asks us to do homework.\nMother tells me to eat.\nHe invites me to his home.",usage_notes:"常见的动词有：让、叫、请、派、选等",category:"句型"},{id:"grammar-2-3",hsk_level:2,pattern:"S + 把 + O + V + 补语",title:'"把"字句（基础）',explanation_zh:'用"把"将动词的宾语提前，表示对宾语的处置或影响。',explanation_en:'Use "ba" to move the object of the verb forward, indicating disposal or influence on the object.',example_zh:"我把书放在桌子上了。\n请把窗户打开。\n他把作业做完了。",example_pinyin:"Wǒ bǎ shū f\xe0ng z\xe0i zhuōzi sh\xe0ng le.\nQǐng bǎ chuāngh\xf9 dǎkāi.\nTā bǎ zu\xf2y\xe8 zu\xf2w\xe1n le.",example_en:"I put the book on the table.\nPlease open the window.\nHe finished the homework.",usage_notes:'"把"的宾语一般是确定的事物；动词后要有其他成分（补语、了、着等）',category:"把字句"},{id:"grammar-2-4",hsk_level:2,pattern:"S + 被 + O + V + 了",title:'"被"字句（基础）',explanation_zh:'主语是动作的受事，"被"引出动作的施事。',explanation_en:'The subject is the recipient of the action, "bei" introduces the agent of the action.',example_zh:"杯子被他打破了。\n我的书被朋友借走了。\n饭被我吃完了。",example_pinyin:"Bēizi b\xe8i tā dǎp\xf2 le.\nWǒ de shū b\xe8i p\xe9ngyou ji\xe8zǒu le.\nF\xe0n b\xe8i wǒ chīw\xe1n le.",example_en:"The cup was broken by him.\nMy book was borrowed by a friend.\nThe rice was eaten up by me.",usage_notes:'口语中常用"叫/让"代替"被"；施事有时可以省略',category:"被动"},{id:"grammar-2-5",hsk_level:2,pattern:"A + 比 + B + Adj",title:'比较句"比"（基础）',explanation_zh:"用于比较两个人或事物的性质、状态的程度差别。",explanation_en:"Used to compare the degree difference in nature or state between two people or things.",example_zh:"我比他高。\n今天比昨天热。\n汉语比英语难吗？",example_pinyin:"Wǒ bǐ tā gāo.\nJīntiān bǐ zu\xf3tiān r\xe8.\nH\xe0nyǔ bǐ yīngyǔ n\xe1n ma?",example_en:"I am taller than him.\nToday is hotter than yesterday.\nIs Chinese harder than English?",usage_notes:'形容词前一般不加"很/非常"等程度副词',category:"比较"},{id:"grammar-2-6",hsk_level:2,pattern:"S + 从 + 处所 + V + (到 + 处所)",title:'介词"从"',explanation_zh:"表示动作起点、来源。",explanation_en:"Indicates the starting point or source of an action.",example_zh:"我从中国来。\n他从家里去学校。\n从这里到学校有多远？",example_pinyin:"Wǒ c\xf3ng zhōnggu\xf3 l\xe1i.\nTā c\xf3ng jiā lǐ q\xf9 xu\xe9xi\xe0o.\nC\xf3ng zh\xe8lǐ d\xe0o xu\xe9xi\xe0o yǒu duō yuǎn?",example_en:"I come from China.\nHe goes from home to school.\nHow far is it from here to school?",usage_notes:'常和"到"搭配使用，表示从起点到终点',category:"介词"},{id:"grammar-2-7",hsk_level:2,pattern:"S + 对 + O + Adj/V",title:'介词"对"',explanation_zh:"表示动作的对象或目标。",explanation_en:"Indicates the object or target of an action.",example_zh:"他对我很好。\n我对汉语很感兴趣。\n老师对学生很严格。",example_pinyin:"Tā du\xec wǒ hěn hǎo.\nWǒ du\xec h\xe0nyǔ hěn gǎn x\xecngq\xf9.\nLǎoshī du\xec xu\xe9shēng hěn y\xe1ng\xe9.",example_en:"He is very good to me.\nI am very interested in Chinese.\nThe teacher is very strict with students.",usage_notes:'"对"还可以表示"对于"，引出动作涉及的对象',category:"介词"},{id:"grammar-2-8",hsk_level:2,pattern:"S + 再 / 又 + V",title:'副词"再/又"',explanation_zh:'表示动作重复或继续。"再"指未发生的重复，"又"指已发生的重复。',explanation_en:'Indicates repetition or continuation of an action. "Zai" refers to future repetition, "you" refers to past repetition.',example_zh:"请再说一遍。\n他昨天又来了。\n我再想想。",example_pinyin:"Qǐng z\xe0i shuō y\xed bi\xe0n.\nTā zu\xf3tiān y\xf2u l\xe1i le.\nWǒ z\xe0i xiǎngxiang.",example_en:"Please say it again.\nHe came again yesterday.\nLet me think again.",usage_notes:"再：还没发生的重复；又：已经发生的重复",category:"副词"},{id:"grammar-2-9",hsk_level:2,pattern:"S + 就 / 才 + V",title:'副词"就/才"',explanation_zh:'"就"表示时间早、快，"才"表示时间晚、慢。',explanation_en:'"Jiu" indicates early or fast, "cai" indicates late or slow.',example_zh:"他八点就来了。\n他十点才来。\n我两天就学会了。",example_pinyin:"Tā bā diǎn ji\xf9 l\xe1i le.\nTā sh\xed diǎn c\xe1i l\xe1i.\nWǒ liǎng tiān ji\xf9 xu\xe9hu\xec le.",example_en:"He came as early as eight o'clock.\nHe came as late as ten o'clock.\nI learned it in just two days.",usage_notes:"就：早、快、容易；才：晚、慢、不容易",category:"副词"},{id:"grammar-2-10",hsk_level:2,pattern:"S + 正在 + V + (呢)",title:'"正在"表示动作进行',explanation_zh:"强调动作正在进行中。",explanation_en:"Emphasizes that an action is in progress.",example_zh:"我正在吃饭呢。\n他正在看书。\n妈妈正在做饭。",example_pinyin:"Wǒ zh\xe8ngz\xe0i chī f\xe0n ne.\nTā zh\xe8ngz\xe0i k\xe0n shū.\nMāma zh\xe8ngz\xe0i zu\xf2 f\xe0n.",example_en:"I am eating right now.\nHe is reading a book.\nMother is cooking.",usage_notes:'句末常加"呢"，语气更强调',category:"副词"},{id:"grammar-2-11",hsk_level:2,pattern:"S + 已经 + V + 了",title:'副词"已经"',explanation_zh:"表示动作、变化完成或达到某种程度。",explanation_en:"Indicates completion of an action or change, or reaching a certain degree.",example_zh:"我已经吃完了。\n他已经来了。\n现在已经十点了。",example_pinyin:"Wǒ yǐjīng chīw\xe1n le.\nTā yǐjīng l\xe1i le.\nXi\xe0nz\xe0i yǐjīng sh\xed diǎn le.",example_en:"I have already finished eating.\nHe has already come.\nIt is already ten o'clock now.",usage_notes:'常和"了"配合使用',category:"副词"},{id:"grammar-2-12",hsk_level:2,pattern:"S + 还 + V/Adj",title:'副词"还"',explanation_zh:"表示现象继续存在或动作继续进行；还可以表示程度上过得去。",explanation_en:"Indicates that a phenomenon continues to exist or an action continues; can also indicate passable degree.",example_zh:"他还没来。\n你还学习吗？\n这个菜还可以。",example_pinyin:"Tā h\xe1i m\xe9i l\xe1i.\nNǐ h\xe1i xu\xe9x\xed ma?\nZh\xe8ge c\xe0i h\xe1i kěyǐ.",example_en:"He has not come yet.\nAre you still studying?\nThis dish is okay.",usage_notes:"还：表示持续、仍然；表示程度上勉强满意",category:"副词"},{id:"grammar-2-13",hsk_level:2,pattern:"S + 能 / 会 / 可以 + V",title:'能愿动词"能/会/可以"',explanation_zh:"表示具备某种能力或可能性。",explanation_en:"Indicates possession of a certain ability or possibility.",example_zh:"我会说汉语。\n他能跑很快。\n你可以进来吗？",example_pinyin:"Wǒ hu\xec shuō h\xe0nyǔ.\nTā n\xe9ng pǎo hěn ku\xe0i.\nNǐ kěyǐ j\xecnl\xe1i ma?",example_en:"I can speak Chinese.\nHe can run very fast.\nCan you come in?",usage_notes:"会：表示懂得怎么做、有能力；能：表示能力、可能性；可以：表示许可、可能",category:"动词"},{id:"grammar-2-14",hsk_level:2,pattern:"越来越 + Adj/V",title:'"越来越……"',explanation_zh:"表示程度随时间的推移而加深。",explanation_en:"Indicates that the degree intensifies as time passes.",example_zh:"天气越来越热了。\n汉语越来越难了。\n他越来越高了。",example_pinyin:"Tiānq\xec yu\xe8l\xe1iyu\xe8 r\xe8 le.\nH\xe0nyǔ yu\xe8l\xe1iyu\xe8 n\xe1n le.\nTā yu\xe8l\xe1iyu\xe8 gāo le.",example_en:"The weather is getting hotter and hotter.\nChinese is getting more and more difficult.\nHe is getting taller and taller.",usage_notes:"表示程度随时间发展而变化",category:"比较"},{id:"grammar-2-15",hsk_level:2,pattern:"A 跟 B 一样 + Adj",title:'"跟……一样"',explanation_zh:"表示比较的两方在某方面相同或相似。",explanation_en:"Indicates that two compared parties are the same or similar in some aspect.",example_zh:"我跟他一样高。\n这个跟那个一样贵。\n汉语跟英语不一样。",example_pinyin:"Wǒ gēn tā y\xedy\xe0ng gāo.\nZh\xe8ge gēn n\xe0ge y\xedy\xe0ng gu\xec.\nH\xe0nyǔ gēn yīngyǔ b\xf9 y\xedy\xe0ng.",example_en:"I am as tall as him.\nThis is as expensive as that.\nChinese is not the same as English.",usage_notes:"否定形式：A 跟 B 不一样",category:"比较"},{id:"grammar-2-16",hsk_level:2,pattern:"一……就……",title:'关联词"一……就……"',explanation_zh:"表示两个动作紧接着发生，前一动作是后一动作的条件或时机。",explanation_en:"Indicates that two actions happen in quick succession, the first action is the condition or timing for the second.",example_zh:"我一到就给你打电话。\n他一听就明白了。\n我一下课就回家。",example_pinyin:"Wǒ y\xed d\xe0o ji\xf9 gěi nǐ dǎ di\xe0nhu\xe0.\nTā y\xec tīng ji\xf9 m\xedngbai le.\nWǒ y\xed xi\xe0 k\xe8 ji\xf9 hu\xed jiā.",example_en:"I will call you as soon as I arrive.\nHe understood as soon as he heard it.\nI go home as soon as class is over.",usage_notes:"两个动作连续发生，时间上很紧凑",category:"连词"},{id:"grammar-2-17",hsk_level:2,pattern:"因为……，所以……",title:'因果复句"因为……所以……"',explanation_zh:"表示原因和结果的关系。",explanation_en:"Indicates the relationship between cause and effect.",example_zh:"因为今天下雨，所以我不去了。\n因为他很努力，所以成绩很好。\n因为太晚了，所以我要回家了。",example_pinyin:"Yīnw\xe8i jīntiān xi\xe0 yǔ, suǒyǐ wǒ b\xfa q\xf9 le.\nYīnw\xe8i tā hěn nǔl\xec, suǒyǐ ch\xe9ngj\xec hěn hǎo.\nYīnw\xe8i t\xe0i wǎn le, suǒyǐ wǒ y\xe0o hu\xed jiā le.",example_en:"Because it is raining today, I am not going.\nBecause he works very hard, his grades are very good.\nBecause it is too late, I am going home.",usage_notes:'也可以先说结果后说原因："之所以……是因为……"',category:"连词"},{id:"grammar-2-18",hsk_level:2,pattern:"虽然……，但是……",title:'转折复句"虽然……但是……"',explanation_zh:"前后分句意思相反或相对，表示转折关系。",explanation_en:"The two clauses have opposite or contrasting meanings, indicating a转折 relationship.",example_zh:"虽然他很累，但是他还在工作。\n虽然汉语很难，但是我很喜欢。\n虽然下雨了，但是我们还是去了。",example_pinyin:"Suīr\xe1n tā hěn l\xe8i, d\xe0nsh\xec tā h\xe1i z\xe0i gōngzu\xf2.\nSuīr\xe1n h\xe0nyǔ hěn n\xe1n, d\xe0nsh\xec wǒ hěn xǐhuan.\nSuīr\xe1n xi\xe0 yǔ le, d\xe0nsh\xec wǒmen h\xe1i sh\xec q\xf9 le.",example_en:"Although he is very tired, he is still working.\nAlthough Chinese is very difficult, I like it very much.\nAlthough it was raining, we still went.",usage_notes:'"但是"可以单用，"虽然"一般和"但是/可是"搭配',category:"连词"},{id:"grammar-2-19",hsk_level:2,pattern:"如果……，就……",title:'假设复句"如果……就……"',explanation_zh:"前一分句提出假设，后一分句说明假设实现后的结果。",explanation_en:"The first clause presents a hypothesis, the second clause explains the result if the hypothesis is realized.",example_zh:"如果明天下雨，我们就不去了。\n如果你有空，请来我家玩。\n如果有问题，可以问老师。",example_pinyin:"R\xfaguǒ m\xedngtiān xi\xe0 yǔ, wǒmen ji\xf9 b\xfa q\xf9 le.\nR\xfaguǒ nǐ yǒu k\xf2ng, qǐng l\xe1i wǒ jiā w\xe1n.\nR\xfaguǒ yǒu w\xe8nt\xed, kěyǐ w\xe8n lǎoshī.",example_en:"If it rains tomorrow, we will not go.\nIf you have time, please come to my place.\nIf you have questions, you can ask the teacher.",usage_notes:'口语中"要是"也可以表示假设',category:"连词"},{id:"grammar-2-20",hsk_level:2,pattern:"S + V + 完 + O",title:'结果补语"完"',explanation_zh:"表示动作完成、结束。",explanation_en:"Indicates completion or conclusion of an action.",example_zh:"我吃完饭了。\n作业做完了吗？\n这本书看完了。",example_pinyin:"Wǒ chīw\xe1n f\xe0n le.\nZu\xf2y\xe8 zu\xf2w\xe1n le ma?\nZh\xe8 běn shū k\xe0nw\xe1n le.",example_en:"I have finished eating.\nHave you finished the homework?\nThis book is finished reading.",usage_notes:"否定形式：没 + V + 完",category:"补语"},{id:"grammar-2-21",hsk_level:2,pattern:"S + V + 到/见 + O",title:'结果补语"到/见"',explanation_zh:"表示动作达到目的或有了结果。",explanation_en:"Indicates that an action achieves its purpose or has a result.",example_zh:"我找到了我的书。\n我昨天见到他了。\n你收到我的信了吗？",example_pinyin:"Wǒ zhǎod\xe0o le wǒ de shū.\nWǒ zu\xf3tiān ji\xe0nd\xe0o tā le.\nNǐ shōud\xe0o wǒ de x\xecn le ma?",example_en:"I found my book.\nI saw him yesterday.\nHave you received my letter?",usage_notes:'"到"强调达到，"见"强调视觉接触',category:"补语"},{id:"grammar-2-22",hsk_level:2,pattern:"S + V + 好 + O",title:'结果补语"好"',explanation_zh:"表示动作完成并达到令人满意的结果。",explanation_en:"Indicates that an action is completed with a satisfactory result.",example_zh:"饭做好了。\n作业写好了。\n衣服买好了。",example_pinyin:"F\xe0n zu\xf2hǎo le.\nZu\xf2y\xe8 xiěhǎo le.\nYīfu mǎihǎo le.",example_en:"The meal is ready.\nThe homework is done.\nThe clothes are bought.",usage_notes:'"好"表示动作完成并且结果好、完善',category:"补语"},{id:"grammar-2-23",hsk_level:2,pattern:"S + 是……的",title:'"是……的"句（强调）',explanation_zh:"强调已经发生的动作的时间、地点、方式等。",explanation_en:"Emphasizes the time, place, manner, etc. of an already occurred action.",example_zh:"我是昨天来的。\n他是坐飞机来的。\n这本书是我在北京买的。",example_pinyin:"Wǒ sh\xec zu\xf3tiān l\xe1i de.\nTā sh\xec zu\xf2 fēijī l\xe1i de.\nZh\xe8 běn shū sh\xec wǒ z\xe0i běijīng mǎi de.",example_en:"I came yesterday.\nHe came by plane.\nI bought this book in Beijing.",usage_notes:'强调的重点放在"是"和"的"之间；动词后一般不能加"了"',category:"句型"},{id:"grammar-2-24",hsk_level:2,pattern:"不但……，而且……",title:'递进复句"不但……而且……"',explanation_zh:"后一分句的意思比前一分句更进一层。",explanation_en:"The meaning of the second clause goes a step further than the first clause.",example_zh:"他不但聪明，而且努力。\n汉语不但有用，而且有意思。\n她不但会唱歌，而且会跳舞。",example_pinyin:"Tā b\xf9d\xe0n cōngm\xedng, \xe9rqiě nǔl\xec.\nH\xe0nyǔ b\xf9d\xe0n yǒuy\xf2ng, \xe9rqiě yǒu y\xecsi.\nTā b\xf9d\xe0n hu\xec ch\xe0ng gē, \xe9rqiě hu\xec ti\xe0o wǔ.",example_en:"He is not only smart, but also hardworking.\nChinese is not only useful, but also interesting.\nShe can not only sing, but also dance.",usage_notes:"表示程度或范围的加深、扩大",category:"连词"},{id:"grammar-2-25",hsk_level:2,pattern:"或者……，或者……",title:'选择复句"或者……或者……"',explanation_zh:"表示从几种情况中选择一种。",explanation_en:"Indicates choosing one from several situations.",example_zh:"你或者去，或者不去。\n明天或者下雨，或者晴天。\n我们或者喝茶，或者喝咖啡。",example_pinyin:"Nǐ hu\xf2zhě q\xf9, hu\xf2zhě b\xfa q\xf9.\nM\xedngtiān hu\xf2zhě xi\xe0 yǔ, hu\xf2zhě q\xedngtiān.\nWǒmen hu\xf2zhě hē ch\xe1, hu\xf2zhě hē kāfēi.",example_en:"You either go or don't go.\nTomorrow it will either rain or be sunny.\nWe either drink tea or coffee.",usage_notes:"表示两种或多种可能性中选一个",category:"连词"},{id:"grammar-2-26",hsk_level:2,pattern:"先……，再/然后……",title:'承接复句"先……再……"',explanation_zh:"表示动作的先后顺序。",explanation_en:"Indicates the sequential order of actions.",example_zh:"我先吃饭，再做作业。\n先买票，然后上车。\n你先请，我随后就来。",example_pinyin:"Wǒ xiān chī f\xe0n, z\xe0i zu\xf2 zu\xf2y\xe8.\nXiān mǎi pi\xe0o, r\xe1nh\xf2u sh\xe0ng chē.\nNǐ xiān qǐng, wǒ su\xedh\xf2u ji\xf9 l\xe1i.",example_en:"I eat first, then do homework.\nFirst buy a ticket, then get on the bus.\nYou go first, I will come right after.",usage_notes:"表示动作的先后承接关系",category:"连词"},{id:"grammar-2-27",hsk_level:2,pattern:"V + 来 / V + 去",title:'趋向补语"来/去"',explanation_zh:'表示动作的方向，朝向说话人用"来"，背离说话人用"去"。',explanation_en:'Indicates direction of action. "Lai" means toward the speaker, "qu" means away from the speaker.',example_zh:"他进来了。\n你快回去吧。\n朋友到我家来了。",example_pinyin:"Tā j\xecnl\xe1i le.\nNǐ ku\xe0i hu\xedq\xf9 ba.\nP\xe9ngyou d\xe0o wǒ jiā l\xe1i le.",example_en:"He came in.\nYou go back quickly.\nA friend came to my house.",usage_notes:"来：朝向说话人所在地；去：背离说话人所在地",category:"补语"},{id:"grammar-2-28",hsk_level:2,pattern:"V + 上 / V + 下",title:'趋向补语"上/下"',explanation_zh:"表示动作方向向上或向下，也可表示动作达到目的。",explanation_en:"Indicates upward or downward direction, can also indicate achieving a goal.",example_zh:"他爬上了山。\n请把窗户关上。\n他脱下了衣服。",example_pinyin:"Tā p\xe1sh\xe0ng le shān.\nQǐng bǎ chuāngh\xf9 guānsh\xe0ng.\nTā tuōxi\xe0 le yīfu.",example_en:"He climbed up the mountain.\nPlease close the window.\nHe took off his clothes.",usage_notes:"上：合拢、达到目的；下：取下、完成",category:"补语"},{id:"grammar-2-29",hsk_level:2,pattern:"V + 出(来/去)",title:'趋向补语"出"',explanation_zh:"表示从里向外的动作，也可表示结果的出现。",explanation_en:"Indicates action from inside to outside, can also indicate appearance of a result.",example_zh:"他从房间里出来了。\n你想出办法了吗？\n太阳出来了。",example_pinyin:"Tā c\xf3ng f\xe1ngjiān lǐ chūl\xe1i le.\nNǐ xiǎngchū b\xe0nfǎ le ma?\nT\xe0iy\xe1ng chūl\xe1i le.",example_en:"He came out of the room.\nHave you thought of a solution?\nThe sun came out.",usage_notes:"出：从里到外；引申为产生、出现",category:"补语"},{id:"grammar-2-30",hsk_level:2,pattern:"V + 回(来/去)",title:'趋向补语"回"',explanation_zh:"表示返回原来的地方。",explanation_en:"Indicates returning to the original place.",example_zh:"我晚上就回家去。\n他明天回来。\n请把书拿回去。",example_pinyin:"Wǒ wǎnshang ji\xf9 hu\xed jiā q\xf9.\nTā m\xedngtiān hu\xedl\xe1i.\nQǐng bǎ shū n\xe1 hu\xedq\xf9.",example_en:"I will go home this evening.\nHe will come back tomorrow.\nPlease take the book back.",usage_notes:'回：返回原处；加"来/去"表示方向',category:"补语"},{id:"grammar-2-31",hsk_level:2,pattern:"V + 起(来)",title:'趋向补语"起"',explanation_zh:"表示动作向上或开始，也可表示连接、结合。",explanation_en:"Indicates upward action or beginning, can also indicate connection or combination.",example_zh:"请站起来。\n他唱起歌来了。\n这两件事联系不起来。",example_pinyin:"Qǐng zh\xe0nqǐl\xe1i.\nTā ch\xe0ng qǐ gē l\xe1i le.\nZh\xe8 liǎng ji\xe0n sh\xec li\xe1nx\xec bu qǐl\xe1i.",example_en:"Please stand up.\nHe started to sing.\nThese two things cannot be connected.",usage_notes:"起：向上、开始、集合",category:"补语"},{id:"grammar-2-32",hsk_level:2,pattern:"V + 过(来/去)",title:'趋向补语"过"',explanation_zh:"表示从一边到另一边，或表示度过、超过。",explanation_en:"Indicates moving from one side to another, or passing through, exceeding.",example_zh:"他走过来了。\n飞机飞过去了。\n考试已经过去了。",example_pinyin:"Tā zǒu gu\xf2l\xe1i le.\nFēijī fēi gu\xf2q\xf9 le.\nKǎosh\xec yǐjīng gu\xf2q\xf9 le.",example_en:"He walked over.\nThe plane flew past.\nThe exam is already over.",usage_notes:"过：从一端到另一端；度过；超过",category:"补语"},{id:"grammar-2-33",hsk_level:2,pattern:"S + V + 给 + O",title:"双宾语句（给）",explanation_zh:"动词后面带两个宾语，一个指人，一个指物。",explanation_en:"A verb is followed by two objects, one referring to a person and one to a thing.",example_zh:"他给我一本书。\n妈妈送给我一个礼物。\n老师教我们汉语。",example_pinyin:"Tā gěi wǒ y\xec běn shū.\nMāma s\xf2ng gěi wǒ y\xed ge lǐw\xf9.\nLǎoshī jiāo wǒmen h\xe0nyǔ.",example_en:"He gives me a book.\nMother gives me a gift.\nThe teacher teaches us Chinese.",usage_notes:"近宾指人，远宾指物；常见动词：给、送、教、借、还等",category:"句型"},{id:"grammar-2-34",hsk_level:2,pattern:"S + 越 V 越 Adj",title:"越……越……",explanation_zh:"表示程度随动作的发展而加深。",explanation_en:"Indicates that degree intensifies as the action develops.",example_zh:"我越学越喜欢汉语。\n他越跑越快。\n这本书越看越有意思。",example_pinyin:"Wǒ yu\xe8 xu\xe9 yu\xe8 xǐhuan h\xe0nyǔ.\nTā yu\xe8 pǎo yu\xe8 ku\xe0i.\nZh\xe8 běn shū yu\xe8 k\xe0n yu\xe8 yǒu y\xecsi.",example_en:"The more I study, the more I like Chinese.\nThe more he runs, the faster he gets.\nThe more I read this book, the more interesting it becomes.",usage_notes:'两个"越"分别修饰两个动词或形容词',category:"比较"},{id:"grammar-2-35",hsk_level:2,pattern:"为了……，……",title:'介词"为了"',explanation_zh:"表示目的。",explanation_en:"Indicates purpose.",example_zh:"为了学习汉语，我来到中国。\n为了健康，他每天运动。\n为了将来，我们要努力。",example_pinyin:"W\xe8ile xu\xe9x\xed h\xe0nyǔ, wǒ l\xe1i d\xe0o zhōnggu\xf3.\nW\xe8ile ji\xe0nkāng, tā měitiān y\xf9nd\xf2ng.\nW\xe8ile jiāngl\xe1i, wǒmen y\xe0o nǔl\xec.",example_en:"In order to study Chinese, I came to China.\nFor health, he exercises every day.\nFor the future, we must work hard.",usage_notes:'"为了"表示目的，可在句首也可在主语后',category:"介词"},{id:"grammar-2-36",hsk_level:2,pattern:"除了……，还/也……",title:'介词"除了"',explanation_zh:"表示排除、不计算在内，或表示包括在内还有其他。",explanation_en:"Indicates exclusion, not counting, or indicates inclusion with other things additionally.",example_zh:"除了汉语，我还学英语。\n除了我，大家都去了。\n除了唱歌，她也会跳舞。",example_pinyin:"Ch\xfale h\xe0nyǔ, wǒ h\xe1i xu\xe9 yīngyǔ.\nCh\xfale wǒ, d\xe0jiā dōu q\xf9 le.\nCh\xfale ch\xe0ng gē, tā yě hu\xec ti\xe0o wǔ.",example_en:"Besides Chinese, I also study English.\nExcept for me, everyone went.\nBesides singing, she can also dance.",usage_notes:"除了……还……：表示追加补充；除了……都……：表示排除",category:"介词"},{id:"grammar-2-37",hsk_level:2,pattern:"一边……，一边……",title:'并列复句"一边……一边……"',explanation_zh:"表示两个动作同时进行。",explanation_en:"Indicates two actions happening simultaneously.",example_zh:"我一边吃饭一边看电视。\n他一边唱歌一边跳舞。\n妈妈一边做饭一边听音乐。",example_pinyin:"Wǒ y\xecbiān chī f\xe0n y\xecbiān k\xe0n di\xe0nsh\xec.\nTā y\xecbiān ch\xe0ng gē y\xecbiān ti\xe0o wǔ.\nMāma y\xecbiān zu\xf2 f\xe0n y\xecbiān tīng yīnyu\xe8.",example_en:"I eat while watching TV.\nHe sings while dancing.\nMother cooks while listening to music.",usage_notes:"两个动作同时发生，主语一般相同",category:"连词"},{id:"grammar-2-38",hsk_level:2,pattern:"既……，又……",title:'并列复句"既……又……"',explanation_zh:"表示两个方面同时存在或两种性质同时具备。",explanation_en:"Indicates that two aspects exist simultaneously or two qualities are both possessed.",example_zh:"她既聪明又漂亮。\n这个办法既简单又有效。\n他既会说英语又会说法语。",example_pinyin:"Tā j\xec cōngm\xedng y\xf2u pi\xe0oliang.\nZh\xe8ge b\xe0nfǎ j\xec jiǎndān y\xf2u yǒuxi\xe0o.\nTā j\xec hu\xec shuō yīngyǔ y\xf2u hu\xec shuō fǎyǔ.",example_en:"She is both smart and beautiful.\nThis method is both simple and effective.\nHe can speak both English and French.",usage_notes:"强调两个方面同时具备，不分主次",category:"连词"},{id:"grammar-2-39",hsk_level:2,pattern:"S + 才 + 数量/时间",title:'"才"表示数量少/时间晚',explanation_zh:'"才"表示数量少、程度低、时间晚等，带有说话人的主观评价。',explanation_en:'"Cai" indicates small quantity, low degree, late time, etc., with the speaker\'s subjective evaluation.',example_zh:"他才二十岁。\n我才学了三个月汉语。\n他才来，还不了解情况。",example_pinyin:"Tā c\xe1i \xe8rsh\xed su\xec.\nWǒ c\xe1i xu\xe9 le sān g\xe8 yu\xe8 h\xe0nyǔ.\nTā c\xe1i l\xe1i, h\xe1i b\xf9 liǎojiě q\xedngku\xe0ng.",example_en:"He is only twenty years old.\nI have only studied Chinese for three months.\nHe just came and does not understand the situation yet.",usage_notes:"才：表示少、晚、慢、难等主观评价",category:"副词"},{id:"grammar-2-40",hsk_level:2,pattern:"S + 就 + 数量/时间",title:'"就"表示数量多/时间早',explanation_zh:'"就"表示数量多、时间早、快等，带有说话人的主观评价。',explanation_en:'"Jiu" indicates large quantity, early time, fast, etc., with the speaker\'s subjective evaluation.',example_zh:"他十五岁就上大学了。\n我学了一年就学会了。\n他吃了三碗饭就饱了。",example_pinyin:"Tā sh\xedwǔ su\xec ji\xf9 sh\xe0ng d\xe0xu\xe9 le.\nWǒ xu\xe9 le y\xec ni\xe1n ji\xf9 xu\xe9hu\xec le.\nTā chī le sān wǎn f\xe0n ji\xf9 bǎo le.",example_en:"He started university at only fifteen.\nI learned it in just one year.\nHe was full after eating three bowls of rice.",usage_notes:"就：表示早、快、多、容易等主观评价",category:"副词"},{id:"grammar-3-1",hsk_level:3,pattern:"A + 比 + B + Adj + 数量",title:"比较句（带数量补语）",explanation_zh:"在比较句中，用数量词表示具体的差别程度。",explanation_en:"In a comparative sentence, use a measure word to indicate the specific degree of difference.",example_zh:"我比他高五厘米。\n今天比昨天热三度。\n他比我大两岁。",example_pinyin:"Wǒ bǐ tā gāo wǔ l\xedmǐ.\nJīntiān bǐ zu\xf3tiān r\xe8 sān d\xf9.\nTā bǐ wǒ d\xe0 liǎng su\xec.",example_en:"I am five centimeters taller than him.\nToday is three degrees hotter than yesterday.\nHe is two years older than me.",usage_notes:"数量词放在形容词后面，表示具体的差别",category:"比较"},{id:"grammar-3-2",hsk_level:3,pattern:"A + 比 + B + 多了/得多",title:"比较句（程度差别大）",explanation_zh:"表示比较的两方差别很大。",explanation_en:"Indicates a large difference between the two compared parties.",example_zh:"他比我高多了。\n汉语比英语难得多。\n今天比昨天冷多了。",example_pinyin:"Tā bǐ wǒ gāo duō le.\nH\xe0nyǔ bǐ yīngyǔ n\xe1n de duō.\nJīntiān bǐ zu\xf3tiān lěng duō le.",example_en:"He is much taller than me.\nChinese is much more difficult than English.\nToday is much colder than yesterday.",usage_notes:'多了/得多：表示程度差别大；"得多"比"多了"程度更深',category:"比较"},{id:"grammar-3-3",hsk_level:3,pattern:"A + 没有 + B + Adj",title:'比较句"没有"',explanation_zh:'表示A在某方面不如B，是"比"字句的否定形式之一。',explanation_en:'Indicates that A is not as good as B in some aspect, one of the negative forms of "bi" sentences.',example_zh:"我没有他高。\n这个没有那个贵。\n今天没有昨天热。",example_pinyin:"Wǒ m\xe9iyǒu tā gāo.\nZh\xe8ge m\xe9iyǒu n\xe0ge gu\xec.\nJīntiān m\xe9iyǒu zu\xf3tiān r\xe8.",example_en:"I am not as tall as him.\nThis is not as expensive as that.\nToday is not as hot as yesterday.",usage_notes:'"没有"表示比较时，后面可以加"这么/那么"',category:"比较"},{id:"grammar-3-4",hsk_level:3,pattern:"最 + Adj",title:'最高级"最"',explanation_zh:"表示在某一范围内程度达到顶点。",explanation_en:"Indicates reaching the peak degree within a certain range.",example_zh:"他是我们班最高的。\n这是最好的办法。\n我最喜欢学汉语。",example_pinyin:"Tā sh\xec wǒmen bān zu\xec gāo de.\nZh\xe8 sh\xec zu\xec hǎo de b\xe0nfǎ.\nWǒ zu\xec xǐhuan xu\xe9 h\xe0nyǔ.",example_en:"He is the tallest in our class.\nThis is the best way.\nI like studying Chinese the most.",usage_notes:"最：表示极端，没有否定形式",category:"副词"},{id:"grammar-3-5",hsk_level:3,pattern:"V + 得 + 很 / 极了 / 死了",title:"程度补语（高程度）",explanation_zh:'用"很/极了/死了"等表示程度很高。',explanation_en:'Use "hen / ji le / si le" etc. to indicate very high degree.',example_zh:"他跑得很快。\n今天热极了。\n我饿死了。",example_pinyin:"Tā pǎo de hěn ku\xe0i.\nJīntiān r\xe8 j\xed le.\nWǒ \xe8 sǐ le.",example_en:"He runs very fast.\nToday is extremely hot.\nI am starving to death.",usage_notes:"极了/死了：程度很高，常带感叹语气",category:"补语"},{id:"grammar-3-6",hsk_level:3,pattern:"可能补语（V + 得/不 + 结果/趋向）",title:"可能补语",explanation_zh:'在动词和结果补语或趋向补语之间加"得/不"，表示动作能不能实现。',explanation_en:'Insert "de/bu" between a verb and a resultative or directional complement to indicate whether the action can be realized.',example_zh:"这个菜我吃得完。\n太高了，我拿不到。\n你听得懂吗？",example_pinyin:"Zh\xe8ge c\xe0i wǒ chī de w\xe1n.\nT\xe0i gāo le, wǒ n\xe1 bu d\xe0o.\nNǐ tīng de dǒng ma?",example_en:"I can finish this dish.\nIt is too high, I cannot reach it.\nCan you understand?",usage_notes:'肯定式用"得"，否定式用"不"；疑问式用"得……不……"',category:"补语"},{id:"grammar-3-7",hsk_level:3,pattern:"V + 得 + 怎么样 / Adj 不 Adj",title:"程度补语的疑问式",explanation_zh:"询问动作的程度或状态如何。",explanation_en:"Asking about the degree or state of an action.",example_zh:"你汉语说得怎么样？\n这个菜做得好不好吃？\n他跑得很快不快？",example_pinyin:"Nǐ h\xe0nyǔ shuō de zěnmey\xe0ng?\nZh\xe8ge c\xe0i zu\xf2 de hǎo bu hǎochī?\nTā pǎo de hěn ku\xe0i bu ku\xe0i?",example_en:"How is your Chinese speaking?\nDoes this dish taste good?\nDoes he run fast?",usage_notes:'可以用"怎么样"或正反问形式提问',category:"补语"},{id:"grammar-3-8",hsk_level:3,pattern:"动量补语（V + 数量 + 次/遍/下/趟）",title:"动量补语",explanation_zh:"表示动作发生的次数。",explanation_en:"Indicates the number of times an action occurs.",example_zh:"这个电影我看过三次。\n请再说一遍。\n我去了一趟北京。",example_pinyin:"Zh\xe8ge di\xe0nyǐng wǒ k\xe0ngu\xf2 sān c\xec.\nQǐng z\xe0i shuō y\xed bi\xe0n.\nWǒ q\xf9 le y\xed t\xe0ng běijīng.",example_en:"I have seen this movie three times.\nPlease say it again.\nI made a trip to Beijing.",usage_notes:"次：一般动作次数；遍：从开始到结束的完整过程；下：短而快的动作；趟：往返一次的动作",category:"补语"},{id:"grammar-3-9",hsk_level:3,pattern:"时量补语（V + 时间）",title:"时量补语",explanation_zh:"表示动作持续的时间长度。",explanation_en:"Indicates the duration of an action.",example_zh:"我学了两年汉语。\n他每天工作八小时。\n我等了你半个小时。",example_pinyin:"Wǒ xu\xe9 le liǎng ni\xe1n h\xe0nyǔ.\nTā měitiān gōngzu\xf2 bā xiǎosh\xed.\nWǒ děng le nǐ b\xe0n ge xiǎosh\xed.",example_en:"I studied Chinese for two years.\nHe works eight hours every day.\nI waited for you for half an hour.",usage_notes:"如果动词有宾语，时量补语可在宾语前或后",category:"补语"},{id:"grammar-3-10",hsk_level:3,pattern:"S + 把 + O + V + 结果补语",title:'"把"字句（结果补语）',explanation_zh:'"把"字句中动词后带结果补语，表示对宾语的处置结果。',explanation_en:'In a "ba" sentence, the verb is followed by a resultative complement, indicating the result of disposing the object.',example_zh:"我把作业做完了。\n他把杯子打破了。\n请把窗户关上。",example_pinyin:"Wǒ bǎ zu\xf2y\xe8 zu\xf2w\xe1n le.\nTā bǎ bēizi dǎp\xf2 le.\nQǐng bǎ chuāngh\xf9 guānsh\xe0ng.",example_en:"I finished the homework.\nHe broke the cup.\nPlease close the window.",usage_notes:"结果补语说明动作对宾语产生的结果",category:"把字句"},{id:"grammar-3-11",hsk_level:3,pattern:"S + 把 + O + V + 趋向补语",title:'"把"字句（趋向补语）',explanation_zh:'"把"字句中动词后带趋向补语，表示宾语的移动方向。',explanation_en:'In a "ba" sentence, the verb is followed by a directional complement, indicating the direction of movement of the object.',example_zh:"请把书拿过来。\n他把衣服脱下来了。\n把这些东西搬出去。",example_pinyin:"Qǐng bǎ shū n\xe1 gu\xf2l\xe1i.\nTā bǎ yīfu tuō xi\xe0l\xe1i le.\nBǎ zh\xe8xiē dōngxi bān chūq\xf9.",example_en:"Please bring the book over.\nHe took off his clothes.\nMove these things out.",usage_notes:"趋向补语说明宾语移动的方向",category:"把字句"},{id:"grammar-3-12",hsk_level:3,pattern:"S + 把 + O1 + V + 给 + O2",title:'"把"字句（给予）',explanation_zh:"表示通过动作把某物交予某人。",explanation_en:"Indicates giving something to someone through an action.",example_zh:"他把书送给了我。\n我把信寄给了他。\n请把这个交给老师。",example_pinyin:"Tā bǎ shū s\xf2ng gěi le wǒ.\nWǒ bǎ x\xecn j\xec gěi le tā.\nQǐng bǎ zh\xe8ge jiāo gěi lǎoshī.",example_en:"He gave the book to me.\nI sent the letter to him.\nPlease hand this to the teacher.",usage_notes:"常用动词：送、交、寄、给、卖等",category:"把字句"},{id:"grammar-3-13",hsk_level:3,pattern:"S + 被 + O + V + 结果补语",title:'"被"字句（结果补语）',explanation_zh:"主语是动作的受事，结果补语说明动作造成的结果。",explanation_en:"The subject is the recipient of the action, and the resultative complement explains the result caused by the action.",example_zh:"杯子被他打破了。\n我的车被小偷偷走了。\n他被老师批评了。",example_pinyin:"Bēizi b\xe8i tā dǎp\xf2 le.\nWǒ de chē b\xe8i xiǎotōu tōuzǒu le.\nTā b\xe8i lǎoshī pīp\xedng le.",example_en:"The cup was broken by him.\nMy car was stolen by a thief.\nHe was criticized by the teacher.",usage_notes:'施事可以省略，如"杯子被打破了"',category:"被动"},{id:"grammar-3-14",hsk_level:3,pattern:"叫 / 让 + O + V + 了",title:"口语中的被动句（叫/让）",explanation_zh:'口语中常用"叫/让"代替"被"表示被动。',explanation_en:'In spoken Chinese, "jiao/rang" are often used instead of "bei" to express passive voice.',example_zh:"我的书叫朋友借走了。\n杯子让他打破了。\n钥匙让我弄丢了。",example_pinyin:"Wǒ de shū ji\xe0o p\xe9ngyou ji\xe8zǒu le.\nBēizi r\xe0ng tā dǎp\xf2 le.\nY\xe0oshi r\xe0ng wǒ n\xf2ng diū le.",example_en:"My book was borrowed by a friend.\nThe cup was broken by him.\nThe key was lost by me.",usage_notes:'"叫/让"比"被"更口语化；施事一般不能省略',category:"被动"},{id:"grammar-3-15",hsk_level:3,pattern:"连……都/也……",title:'"连……都/也……"',explanation_zh:'强调出乎意料，含有"甚至"的意思。',explanation_en:'Emphasizes something unexpected, with the meaning of "even".',example_zh:"他连汉语都不会说。\n我连一个字都没写。\n连小孩都知道。",example_pinyin:"Tā li\xe1n h\xe0nyǔ dōu b\xfa hu\xec shuō.\nWǒ li\xe1n y\xed g\xe8 z\xec dōu m\xe9i xiě.\nLi\xe1n xiǎoh\xe1i dōu zhīd\xe0o.",example_en:"He cannot even speak Chinese.\nI did not write even a single word.\nEven children know it.",usage_notes:"连……都/也……：强调极端情况",category:"句型"},{id:"grammar-3-16",hsk_level:3,pattern:"谁……谁……",title:"疑问代词的任指用法",explanation_zh:'疑问代词不表示疑问，而表示"任何"、"所有"的意思。',explanation_en:'Interrogative pronouns do not express doubt, but mean "any" or "all".',example_zh:"谁想去谁去。\n你想吃什么就吃什么。\n你想怎么去就怎么去。",example_pinyin:"Sh\xe9i xiǎng q\xf9 sh\xe9i q\xf9.\nNǐ xiǎng chī sh\xe9nme ji\xf9 chī sh\xe9nme.\nNǐ xiǎng zěnme q\xf9 ji\xf9 zěnme q\xf9.",example_en:"Whoever wants to go can go.\nEat whatever you want.\nGo however you want.",usage_notes:'两个相同的疑问代词前后呼应，表示"任何"',category:"代词"},{id:"grammar-3-17",hsk_level:3,pattern:"什么 + 都 / 也",title:"疑问代词的虚指用法",explanation_zh:"疑问代词表示不确定的人或事物，或表示全部。",explanation_en:"Interrogative pronouns indicate indefinite people or things, or indicate totality.",example_zh:"我什么都不知道。\n他什么也没说就走了。\n今天我哪儿都没去。",example_pinyin:"Wǒ sh\xe9nme dōu b\xf9 zhīd\xe0o.\nTā sh\xe9nme yě m\xe9i shuō ji\xf9 zǒu le.\nJīntiān wǒ nǎr dōu m\xe9i q\xf9.",example_en:"I don't know anything.\nHe left without saying anything.\nI didn't go anywhere today.",usage_notes:"什么/谁/哪儿 + 都/也：表示全部；常用于否定句",category:"代词"},{id:"grammar-3-18",hsk_level:3,pattern:"的字短语",title:'"的"字短语',explanation_zh:'由"动词/形容词/名词 + 的"构成的短语，作用相当于名词。',explanation_en:'A phrase formed by "verb/adjective/noun + de", functioning like a noun.',example_zh:"这本书是我的。\n那个高的是我哥哥。\n吃的东西很多。",example_pinyin:"Zh\xe8 běn shū sh\xec wǒ de.\nN\xe0ge gāo de sh\xec wǒ gēge.\nChī de dōngxi hěn duō.",example_en:"This book is mine.\nThat tall one is my older brother.\nThere is a lot of food.",usage_notes:"的字短语 = 形容词/动词/名词 + 的，可以代替名词",category:"助词"},{id:"grammar-3-19",hsk_level:3,pattern:"S + 在……上 / 下 / 中 / 里",title:'介词短语"在……上/下/中/里"',explanation_zh:"表示在某一方面、某一范围或某一条件下。",explanation_en:"Indicates in a certain aspect, range, or under certain conditions.",example_zh:"在学习上，他很努力。\n在老师的帮助下，我进步很快。\n在生活中，我们要互相帮助。",example_pinyin:"Z\xe0i xu\xe9x\xed sh\xe0ng, tā hěn nǔl\xec.\nZ\xe0i lǎoshī de bāngzh\xf9 xi\xe0, wǒ j\xecnb\xf9 hěn ku\xe0i.\nZ\xe0i shēnghu\xf3 zhōng, wǒmen y\xe0o h\xf9xiāng bāngzh\xf9.",example_en:"In study, he works very hard.\nWith the teacher's help, I progress quickly.\nIn life, we should help each other.",usage_notes:"在……上：方面；在……下：条件；在……中：过程、范围",category:"介词"},{id:"grammar-3-20",hsk_level:3,pattern:"S + 关于 + N + V",title:'介词"关于"',explanation_zh:"引出动作涉及的事物或范围。",explanation_en:"Introduces the thing or range that an action involves.",example_zh:"关于这个问题，我再说几句。\n关于中国文化，我很感兴趣。\n关于这件事，他知道得很多。",example_pinyin:"Guāny\xfa zh\xe8ge w\xe8nt\xed, wǒ z\xe0i shuō jǐ j\xf9.\nGuāny\xfa zhōnggu\xf3 w\xe9nhu\xe0, wǒ hěn gǎn x\xecngq\xf9.\nGuāny\xfa zh\xe8 ji\xe0n sh\xec, tā zhīd\xe0o de hěn duō.",example_en:"Regarding this issue, let me say a few more words.\nAbout Chinese culture, I am very interested.\nAbout this matter, he knows a lot.",usage_notes:'"关于"表示涉及的范围，可放在句首或主语后',category:"介词"},{id:"grammar-3-21",hsk_level:3,pattern:"S + 向 / 往 + 方向 + V",title:'介词"向/往"',explanation_zh:"表示动作的方向。",explanation_en:"Indicates the direction of an action.",example_zh:"向前走。\n他往学校去了。\n我们向他学习。",example_pinyin:"Xi\xe0ng qi\xe1n zǒu.\nTā wǎng xu\xe9xi\xe0o q\xf9 le.\nWǒmen xi\xe0ng tā xu\xe9x\xed.",example_en:"Walk forward.\nHe went toward the school.\nWe learn from him.",usage_notes:'向/往：表示方向；"向"还可以表示对象',category:"介词"},{id:"grammar-3-22",hsk_level:3,pattern:"S + 对 + O + 来说",title:'"对……来说"',explanation_zh:"表示从某人或某事物的角度来看。",explanation_en:"Indicates looking at something from the perspective of someone or something.",example_zh:"对我来说，汉语很难。\n对他来说，这很简单。\n对学生来说，学习很重要。",example_pinyin:"Du\xec wǒ l\xe1i shuō, h\xe0nyǔ hěn n\xe1n.\nDu\xec tā l\xe1i shuō, zh\xe8 hěn jiǎndān.\nDu\xec xu\xe9shēng l\xe1i shuō, xu\xe9x\xed hěn zh\xf2ngy\xe0o.",example_en:"For me, Chinese is very difficult.\nFor him, this is very simple.\nFor students, studying is very important.",usage_notes:"表示从某个角度、立场来看问题",category:"介词"},{id:"grammar-3-23",hsk_level:3,pattern:"就 / 才 + 数量 + 呢",title:'"就/才"表数量（主观评价）',explanation_zh:'"就"表示数量多，"才"表示数量少，都是说话人的主观看法。',explanation_en:'"Jiu" indicates large quantity, "cai" indicates small quantity, both are the speaker\'s subjective view.',example_zh:"他就要了三个，不够。\n他才要了三个，太少了。\n我就有十块钱。",example_pinyin:"Tā ji\xf9 y\xe0o le sān g\xe8, b\xf9 g\xf2u.\nTā c\xe1i y\xe0o le sān g\xe8, t\xe0i shǎo le.\nWǒ ji\xf9 yǒu sh\xed ku\xe0i qi\xe1n.",example_en:"He only asked for three, not enough.\nHe only asked for three, too few.\nI only have ten yuan.",usage_notes:"就：强调数量少（不够）或多（超出预期）；才：强调数量少（太少）",category:"副词"},{id:"grammar-3-24",hsk_level:3,pattern:"S + 终于 + V + 了",title:'副词"终于"',explanation_zh:"表示经过较长过程最后出现某种结果。",explanation_en:"Indicates that a certain result finally appears after a long process.",example_zh:"他终于来了。\n我终于学会了。\n考试终于结束了。",example_pinyin:"Tā zhōngy\xfa l\xe1i le.\nWǒ zhōngy\xfa xu\xe9hu\xec le.\nKǎosh\xec zhōngy\xfa ji\xe9sh\xf9 le.",example_en:"He finally came.\nI finally learned it.\nThe exam finally ended.",usage_notes:"终于：表示经过困难或等待后出现结果",category:"副词"},{id:"grammar-3-25",hsk_level:3,pattern:"S + 一直 / 始终 + V",title:'副词"一直/始终"',explanation_zh:"表示动作持续不断或状态持续不变。",explanation_en:"Indicates continuous action or unchanging state.",example_zh:"我一直在等你。\n他始终没来。\n雨一直下了一天。",example_pinyin:"Wǒ y\xeczh\xed z\xe0i děng nǐ.\nTā shǐzhōng m\xe9i l\xe1i.\nYǔ y\xeczh\xed xi\xe0 le y\xec tiān.",example_en:"I have been waiting for you all along.\nHe never came.\nIt rained continuously for a day.",usage_notes:"一直：口语书面都常用；始终：多用于书面",category:"副词"},{id:"grammar-3-26",hsk_level:3,pattern:"S + 已经 + V + 了 + 数量 + 了",title:'"已经……了"（持续）',explanation_zh:"表示动作或状态从过去开始持续到现在，可能继续下去。",explanation_en:"Indicates that an action or state started in the past and continues to the present, possibly continuing.",example_zh:"我已经学了两年汉语了。\n他已经走了三个小时了。\n我已经等了你半个小时了。",example_pinyin:"Wǒ yǐjīng xu\xe9 le liǎng ni\xe1n h\xe0nyǔ le.\nTā yǐjīng zǒu le sān ge xiǎosh\xed le.\nWǒ yǐjīng děng le nǐ b\xe0n ge xiǎosh\xed le.",example_en:"I have already studied Chinese for two years.\nHe has already been walking for three hours.\nI have already been waiting for you for half an hour.",usage_notes:'两个"了"：动词后+时量+了，表示动作持续到现在',category:"副词"},{id:"grammar-3-27",hsk_level:3,pattern:"S + 刚 / 刚刚 + V",title:'副词"刚/刚刚"',explanation_zh:"表示动作发生在不久以前。",explanation_en:"Indicates that an action happened not long ago.",example_zh:"他刚走。\n我刚刚来。\n电影刚开始。",example_pinyin:"Tā gāng zǒu.\nWǒ gānggāng l\xe1i.\nDi\xe0nyǐng gāng kāishǐ.",example_en:"He just left.\nI just arrived.\nThe movie just started.",usage_notes:'刚：强调动作发生的时间短；和"刚才"不同，"刚才"是时间名词',category:"副词"},{id:"grammar-3-28",hsk_level:3,pattern:"S + 又……又……",title:'"又……又……"',explanation_zh:"表示同时存在几种性质或情况。",explanation_en:"Indicates that several qualities or situations exist simultaneously.",example_zh:"这个苹果又大又红。\n他又聪明又努力。\n这个地方又干净又漂亮。",example_pinyin:"Zh\xe8ge p\xedngguǒ y\xf2u d\xe0 y\xf2u h\xf3ng.\nTā y\xf2u cōngm\xedng y\xf2u nǔl\xec.\nZh\xe8ge d\xecfāng y\xf2u gānj\xecng y\xf2u pi\xe0oliang.",example_en:"This apple is both big and red.\nHe is both smart and hardworking.\nThis place is both clean and beautiful.",usage_notes:"连接两个形容词，表示两种性质同时存在",category:"副词"},{id:"grammar-3-29",hsk_level:3,pattern:"只要……，就……",title:'条件复句"只要……就……"',explanation_zh:"前一分句提出充足条件，后一分句说明结果。",explanation_en:"The first clause presents a sufficient condition, the second clause explains the result.",example_zh:"只要努力，就能成功。\n只要你去，我就去。\n只要有钱，什么都能买到。",example_pinyin:"Zhǐy\xe0o nǔl\xec, ji\xf9 n\xe9ng ch\xe9nggōng.\nZhǐy\xe0o nǐ q\xf9, wǒ ji\xf9 q\xf9.\nZhǐy\xe0o yǒu qi\xe1n, sh\xe9nme dōu n\xe9ng mǎi d\xe0o.",example_en:"As long as you work hard, you can succeed.\nAs long as you go, I will go.\nAs long as you have money, you can buy anything.",usage_notes:"只要：充足条件，有此条件必然有此结果",category:"连词"},{id:"grammar-3-30",hsk_level:3,pattern:"只有……，才……",title:'条件复句"只有……才……"',explanation_zh:"前一分句提出必要条件，后一分句说明结果。",explanation_en:"The first clause presents a necessary condition, the second clause explains the result.",example_zh:"只有努力，才能成功。\n只有你去，我才去。\n只有学过汉语的人才懂。",example_pinyin:"Zhǐyǒu nǔl\xec, c\xe1i n\xe9ng ch\xe9nggōng.\nZhǐyǒu nǐ q\xf9, wǒ c\xe1i q\xf9.\nZhǐyǒu xu\xe9guo h\xe0nyǔ de r\xe9n c\xe1i dǒng.",example_en:"Only by working hard can one succeed.\nOnly if you go will I go.\nOnly people who have studied Chinese understand.",usage_notes:"只有：必要条件，没有这个条件就没有这个结果",category:"连词"},{id:"grammar-3-31",hsk_level:3,pattern:"不管……，都……",title:'条件复句"不管……都……"',explanation_zh:"前一分句排除一切条件，后一分句说明在任何条件下结果都一样。",explanation_en:"The first clause excludes all conditions, the second clause explains that the result is the same under any condition.",example_zh:"不管天气好不好，我都去。\n不管是谁，都要遵守规定。\n不管多难，我都要学会。",example_pinyin:"B\xf9guǎn tiānq\xec hǎo bu hǎo, wǒ dōu q\xf9.\nB\xf9guǎn sh\xec shu\xed, dōu y\xe0o zūnshǒu guīd\xecng.\nB\xf9guǎn duō n\xe1n, wǒ dōu y\xe0o xu\xe9hu\xec.",example_en:"No matter whether the weather is good or not, I will go.\nNo matter who it is, they must follow the rules.\nNo matter how difficult it is, I must learn it.",usage_notes:"不管：表示无条件，结果不变",category:"连词"},{id:"grammar-3-32",hsk_level:3,pattern:"既然……，就……",title:'因果复句"既然……就……"',explanation_zh:"前一分句提出前提，后一分句根据这个前提推出结论。",explanation_en:"The first clause presents a premise, the second clause draws a conclusion based on this premise.",example_zh:"既然你来了，就别走了。\n既然知道错了，就应该改正。\n既然答应了，就要做到。",example_pinyin:"J\xecr\xe1n nǐ l\xe1i le, ji\xf9 bi\xe9 zǒu le.\nJ\xecr\xe1n zhīd\xe0o cu\xf2 le, ji\xf9 yīnggāi gǎizh\xe8ng.\nJ\xecr\xe1n dāying le, ji\xf9 y\xe0o zu\xf2d\xe0o.",example_en:"Since you have come, don't leave.\nSince you know you are wrong, you should correct it.\nSince you promised, you must keep your word.",usage_notes:"既然：用于推论因果，根据已有事实推出结论",category:"连词"},{id:"grammar-3-33",hsk_level:3,pattern:"即使……，也……",title:'假设复句"即使……也……"',explanation_zh:"前一分句先退一步承认某种假设，后一分句说出相反的结论。",explanation_en:"The first clause takes a step back to admit a hypothesis, the second clause states the opposite conclusion.",example_zh:"即使下雨，我也去。\n即使困难再大，我们也要完成。\n即使你不说，我也知道。",example_pinyin:"J\xedshǐ xi\xe0 yǔ, wǒ yě q\xf9.\nJ\xedshǐ k\xf9nn\xe1n z\xe0i d\xe0, wǒmen yě y\xe0o w\xe1nch\xe9ng.\nJ\xedshǐ nǐ b\xf9 shuō, wǒ yě zhīd\xe0o.",example_en:"Even if it rains, I will go.\nEven if the difficulty is great, we must complete it.\nEven if you don't say it, I know.",usage_notes:"即使：表示假设的让步，结果不受假设影响",category:"连词"},{id:"grammar-3-34",hsk_level:3,pattern:"宁可……，也不……",title:'选择复句"宁可……也不……"',explanation_zh:"表示在两方面中选择一面，舍弃另一面。",explanation_en:"Indicates choosing one side and abandoning the other between two options.",example_zh:"我宁可走路去，也不坐车。\n他宁可不吃，也不吃难吃的东西。\n我宁可不做，也不做错。",example_pinyin:"Wǒ n\xecngkě zǒul\xf9 q\xf9, yě b\xf9 zu\xf2 chē.\nTā n\xecngkě b\xf9 chī, yě b\xf9 chī n\xe1nchī de dōngxi.\nWǒ n\xecngkě b\xf9 zu\xf2, yě b\xf9 zu\xf2 cu\xf2.",example_en:"I would rather walk than take the bus.\nHe would rather not eat than eat bad food.\nI would rather not do it than do it wrong.",usage_notes:"宁可：表示在比较利害得失后做出选择",category:"连词"},{id:"grammar-3-35",hsk_level:3,pattern:"与其……，不如……",title:'选择复句"与其……不如……"',explanation_zh:"表示比较两方面的利害得失，选择其中较好的一面。",explanation_en:"Indicates comparing the pros and cons of two aspects, choosing the better one.",example_zh:"与其等他，不如我们先走。\n与其买贵的，不如买便宜的。\n与其在家睡觉，不如出去走走。",example_pinyin:"Yǔq\xed děng tā, b\xf9r\xfa wǒmen xiān zǒu.\nYǔq\xed mǎi gu\xec de, b\xf9r\xfa mǎi pi\xe1nyi de.\nYǔq\xed z\xe0i jiā shu\xecji\xe0o, b\xf9r\xfa chūq\xf9 zǒuzou.",example_en:"Rather than wait for him, let's go first.\nRather than buy the expensive one, better buy the cheap one.\nRather than sleep at home, better go out for a walk.",usage_notes:"与其……不如……：表示在比较中选择后者",category:"连词"},{id:"grammar-3-36",hsk_level:3,pattern:"不但不……，反而……",title:'递进复句"不但不……反而……"',explanation_zh:"前一分句否定，后一分句从相反方向更进一层。",explanation_en:"The first clause is negative, the second clause goes a step further in the opposite direction.",example_zh:"他不但不生气，反而很高兴。\n吃了药不但不好，反而更重了。\n他不但不感谢，反而抱怨。",example_pinyin:"Tā b\xf9d\xe0n b\xf9 shēngq\xec, fǎn'\xe9r hěn gāox\xecng.\nChī le y\xe0o b\xf9d\xe0n b\xf9 hǎo, fǎn'\xe9r g\xe8ng zh\xf2ng le.\nTā b\xf9d\xe0n b\xf9 gǎnxi\xe8, fǎn'\xe9r b\xe0oyu\xe0n.",example_en:"Not only is he not angry, but on the contrary he is very happy.\nAfter taking medicine, not only did it not get better, but it got worse.\nNot only is he not grateful, but on the contrary he complains.",usage_notes:"不但不……反而……：表示反向递进",category:"连词"},{id:"grammar-3-37",hsk_level:3,pattern:"之所以……，是因为……",title:"因果倒装句",explanation_zh:"先说结果，后说原因，强调原因。",explanation_en:"State the result first, then the reason, emphasizing the reason.",example_zh:"他之所以成功，是因为他很努力。\n我之所以来，是因为你邀请我。\n之所以迟到，是因为堵车了。",example_pinyin:"Tā zhī suǒyǐ ch\xe9nggōng, sh\xec yīnw\xe8i tā hěn nǔl\xec.\nWǒ zhī suǒyǐ l\xe1i, sh\xec yīnw\xe8i nǐ yāoqǐng wǒ.\nZhī suǒyǐ ch\xedd\xe0o, sh\xec yīnw\xe8i dǔ chē le.",example_en:"The reason he succeeded is because he works very hard.\nThe reason I came is because you invited me.\nThe reason for being late is because of traffic jam.",usage_notes:"结果在前，原因在后，强调原因",category:"连词"},{id:"grammar-3-38",hsk_level:3,pattern:"V + 起来",title:'趋向补语"起来"（引申义）',explanation_zh:"表示动作开始、兴起、集合等抽象意义。",explanation_en:"Indicates abstract meanings like beginning, rising, gathering of an action.",example_zh:"他唱起歌来了。\n天气热起来了。\n大家团结起来。",example_pinyin:"Tā ch\xe0ng qǐ gē l\xe1i le.\nTiānq\xec r\xe8 qǐl\xe1i le.\nD\xe0jiā tu\xe1nji\xe9 qǐl\xe1i.",example_en:"He started singing.\nThe weather is getting hot.\nEveryone unite together.",usage_notes:"起来：开始、兴起、集合",category:"补语"},{id:"grammar-3-39",hsk_level:3,pattern:"V + 下去",title:'趋向补语"下去"（引申义）',explanation_zh:"表示动作继续进行或状态继续发展。",explanation_en:"Indicates that an action continues or a state continues to develop.",example_zh:"你说下去，我听着呢。\n坚持下去就是胜利。\n再做下去会很累的。",example_pinyin:"Nǐ shuō xi\xe0q\xf9, wǒ tīng zhe ne.\nJiānch\xed xi\xe0q\xf9 ji\xf9 sh\xec sh\xe8ngl\xec.\nZ\xe0i zu\xf2 xi\xe0q\xf9 hu\xec hěn l\xe8i de.",example_en:"Continue speaking, I am listening.\nPersisting means victory.\nContinuing to do it will be very tiring.",usage_notes:"下去：继续、持续",category:"补语"},{id:"grammar-3-40",hsk_level:3,pattern:"V + 出来",title:'趋向补语"出来"（引申义）',explanation_zh:"表示动作产生了结果或使隐藏的事物显现出来。",explanation_en:"Indicates that an action produces a result or makes hidden things appear.",example_zh:"我想出来了一个好办法。\n他终于说出了真相。\n这件事终于查出来了。",example_pinyin:"Wǒ xiǎng chūl\xe1i le y\xed ge hǎo b\xe0nfǎ.\nTā zhōngy\xfa shuō chū le zhēnxi\xe0ng.\nZh\xe8 ji\xe0n sh\xec zhōngy\xfa ch\xe1 chūl\xe1i le.",example_en:"I thought of a good idea.\nHe finally told the truth.\nThis matter was finally investigated.",usage_notes:"出来：产生、出现、显露",category:"补语"},{id:"grammar-3-41",hsk_level:3,pattern:"V + 过来 / 过去",title:'趋向补语"过来/过去"（引申义）',explanation_zh:"表示状态的转变或度过困难时期。",explanation_en:"Indicates change of state or getting through a difficult period.",example_zh:"他终于醒过来了。\n最困难的时期已经过去了。\n他反应不过来。",example_pinyin:"Tā zhōngy\xfa xǐng gu\xf2l\xe1i le.\nZu\xec k\xf9nn\xe1n de sh\xedqī yǐjīng gu\xf2q\xf9 le.\nTā fǎny\xecng bu gu\xf2l\xe1i.",example_en:"He finally woke up.\nThe most difficult period has passed.\nHe cannot react quickly enough.",usage_notes:"过来：恢复、醒悟；过去：度过、结束",category:"补语"},{id:"grammar-3-42",hsk_level:3,pattern:"主谓短语作谓语",title:"主谓谓语句",explanation_zh:"由主谓短语充当谓语的句子。",explanation_en:"A sentence where the predicate is a subject-predicate phrase.",example_zh:"他学习很努力。\n我头疼。\n这个菜味道不错。",example_pinyin:"Tā xu\xe9x\xed hěn nǔl\xec.\nWǒ t\xf3u t\xe9ng.\nZh\xe8ge c\xe0i w\xe8id\xe0o b\xf9cu\xf2.",example_en:"He studies very hard.\nI have a headache.\nThis dish tastes good.",usage_notes:"大主语和小主语有领属关系或整体与部分的关系",category:"句型"},{id:"grammar-3-43",hsk_level:3,pattern:"N1 + 叫 / 称 + N2 + N3",title:"双宾语句（称呼类）",explanation_zh:"表示称呼、命名的双宾语句。",explanation_en:"Double-object sentences expressing naming or addressing.",example_zh:"大家都叫他老王。\n人们称他为英雄。\n我们叫他小张。",example_pinyin:"D\xe0jiā dōu ji\xe0o tā lǎo w\xe1ng.\nR\xe9nmen chēng tā w\xe9i yīngxi\xf3ng.\nWǒmen ji\xe0o tā xiǎo zhāng.",example_en:"Everyone calls him Old Wang.\nPeople call him a hero.\nWe call him Little Zhang.",usage_notes:"常见动词：叫、称、选、选举等",category:"句型"},{id:"grammar-3-44",hsk_level:3,pattern:"各 + 量词 + 名词",title:'代词"各"',explanation_zh:"表示所有的、每个，强调个体。",explanation_en:"Indicates all or each, emphasizing individuality.",example_zh:"各有各的好处。\n各个班级都参加了。\n各国人民都热爱和平。",example_pinyin:"G\xe8 yǒu g\xe8 de hǎoch\xf9.\nG\xe8 g\xe8 bānj\xed dōu cānjiā le.\nG\xe8 gu\xf3 r\xe9nm\xedn dōu r\xe8'\xe0i h\xe9p\xedng.",example_en:"Each has its own advantages.\nEvery class participated.\nPeople of all countries love peace.",usage_notes:'各：每、所有；"每"强调全体中的任何一个，"各"强调不同',category:"代词"},{id:"grammar-3-45",hsk_level:3,pattern:"每 + 量词 + 名词 + 都",title:'代词"每"',explanation_zh:"指全体中的任何一个或一组，强调共性。",explanation_en:"Refers to any one or group in the whole, emphasizing commonality.",example_zh:"每个人都要努力。\n每天早上我都跑步。\n每个学生都有书。",example_pinyin:"Měi ge r\xe9n dōu y\xe0o nǔl\xec.\nMěi tiān zǎoshang wǒ dōu pǎo b\xf9.\nMěi ge xu\xe9shēng dōu yǒu shū.",example_en:"Everyone must work hard.\nEvery morning I run.\nEvery student has a book.",usage_notes:'每：强调全体中的任何一个都一样，后面常用"都"',category:"代词"},{id:"grammar-3-46",hsk_level:3,pattern:"多 / 少 + 动词",title:"形容词作状语（多/少）",explanation_zh:'"多/少"放在动词前作状语，表示数量。',explanation_en:'"Duo/shao" placed before a verb as an adverbial, indicating quantity.',example_zh:"多吃点水果。\n少抽烟。\n多穿点衣服。",example_pinyin:"Duō chī diǎn shuǐguǒ.\nShǎo chōu yān.\nDuō chuān diǎn yīfu.",example_en:"Eat more fruit.\nSmoke less.\nPut on more clothes.",usage_notes:"多/少+动词：表示数量上的建议或要求",category:"形容词"},{id:"grammar-3-47",hsk_level:3,pattern:"快 / 慢慢 + 动词",title:"形容词作状语（方式）",explanation_zh:"某些形容词可以直接放在动词前作状语，表示方式。",explanation_en:"Some adjectives can be placed directly before a verb as an adverbial, indicating manner.",example_zh:"你快走，别迟到了。\n慢慢说，别着急。\n快起床，要迟到了。",example_pinyin:"Nǐ ku\xe0i zǒu, bi\xe9 ch\xedd\xe0o le.\nM\xe0nm\xe0n shuō, bi\xe9 zh\xe1oj\xed.\nKu\xe0i qǐchu\xe1ng, y\xe0o ch\xedd\xe0o le.",example_en:"Hurry up, don't be late.\nSpeak slowly, don't worry.\nGet up quickly, you will be late.",usage_notes:'单音节形容词作状语较少，双音节形容词如"认真、努力、仔细"等可作状语',category:"形容词"},{id:"grammar-3-48",hsk_level:3,pattern:"AABB式形容词重叠",title:"双音节形容词重叠",explanation_zh:"双音节形容词重叠为AABB式，表示程度加深或状态的生动描述。",explanation_en:"Disyllabic adjectives reduplicated in AABB form indicate deepened degree or vivid description of state.",example_zh:"他高高兴兴地来了。\n干干净净的房间。\n认认真真地学习。",example_pinyin:"Tā gāogāo x\xecngx\xecng de l\xe1i le.\nGāngānj\xecngj\xecng de f\xe1ngjiān.\nR\xe8nr\xe8nzhēnzhēn de xu\xe9x\xed.",example_en:"He came happily.\nA clean room.\nStudy conscientiously.",usage_notes:'双音节形容词重叠：AABB式；作状语或定语时加"地/的"',category:"形容词"},{id:"grammar-3-49",hsk_level:3,pattern:"V + 的 + 是 + N",title:'"的"字结构作主语',explanation_zh:'由"动词+的"构成的"的"字结构作主语。',explanation_en:'A "de" phrase formed by "verb + de" functions as the subject.',example_zh:"来的人很多。\n说的比唱的还好听。\n用的都是好材料。",example_pinyin:"L\xe1i de r\xe9n hěn duō.\nShuō de bǐ ch\xe0ng de h\xe1i hǎotīng.\nY\xf2ng de dōu sh\xec hǎo c\xe1ili\xe0o.",example_en:"Many people came.\nWhat is said sounds better than what is sung.\nWhat is used are all good materials.",usage_notes:"的字结构可以作主语、宾语等句子成分",category:"助词"},{id:"grammar-3-50",hsk_level:3,pattern:"N + 似的 / 一样",title:'比况助词"似的/一样"',explanation_zh:"表示比喻或比较，说明事物相似。",explanation_en:"Indicates metaphor or comparison, showing similarity between things.",example_zh:"他像孩子似的高兴。\n他飞一样地跑了。\n他的话像刀子似的伤人。",example_pinyin:"Tā xi\xe0ng h\xe1izi sh\xec de gāox\xecng.\nTā fēi y\xedy\xe0ng de pǎo le.\nTā de hu\xe0 xi\xe0ng dāozi sh\xec de shāng r\xe9n.",example_en:"He is as happy as a child.\nHe ran like flying.\nHis words hurt like a knife.",usage_notes:'似的/一样：表示比喻，常和"像、仿佛"等搭配',category:"助词"},{id:"grammar-4-1",hsk_level:4,pattern:"A + 比 + B + 还 / 更 + Adj",title:'比较句"还/更"',explanation_zh:"表示比较的两方中，前者的程度比后者更深。",explanation_en:"Indicates that between the two compared parties, the former has a deeper degree than the latter.",example_zh:"他比我还高。\n这个比那个更好。\n今天比昨天更热。",example_pinyin:"Tā bǐ wǒ h\xe1i gāo.\nZh\xe8ge bǐ n\xe0ge g\xe8ng hǎo.\nJīntiān bǐ zu\xf3tiān g\xe8ng r\xe8.",example_en:"He is even taller than me.\nThis is even better than that.\nToday is even hotter than yesterday.",usage_notes:'还/更：表示程度加深，"更"比"还"程度略深',category:"比较"},{id:"grammar-4-2",hsk_level:4,pattern:"A + 不如 + B + (Adj)",title:'比较句"不如"',explanation_zh:"表示A比不上B，或A没有B好。",explanation_en:"Indicates that A is not as good as B, or A is inferior to B.",example_zh:"我不如他努力。\n这个不如那个好。\n我的汉语不如他。",example_pinyin:"Wǒ b\xf9r\xfa tā nǔl\xec.\nZh\xe8ge b\xf9r\xfa n\xe0ge hǎo.\nWǒ de h\xe0nyǔ b\xf9r\xfa tā.",example_en:"I am not as hardworking as him.\nThis is not as good as that.\nMy Chinese is not as good as his.",usage_notes:"不如：表示比较中前者比不上后者；也可以不带形容词",category:"比较"},{id:"grammar-4-3",hsk_level:4,pattern:"A + 等于 / 相当于 + B",title:'比较句"等于/相当于"',explanation_zh:"表示两个事物在某方面相同或差不多。",explanation_en:"Indicates that two things are the same or similar in some aspect.",example_zh:"一公斤等于两斤。\n他说的等于没说。\n这相当于给他帮忙。",example_pinyin:"Y\xec gōngjīn děngy\xfa liǎng jīn.\nTā shuō de děngy\xfa m\xe9i shuō.\nZh\xe8 xiāngdāng y\xfa gěi tā bāngm\xe1ng.",example_en:"One kilogram equals two jin.\nWhat he said is equivalent to not saying anything.\nThis is equivalent to helping him.",usage_notes:"等于：完全相同；相当于：差不多相等",category:"比较"},{id:"grammar-4-4",hsk_level:4,pattern:"V / Adj + 极了 / 死了 / 坏了",title:"程度补语（极/死/坏）",explanation_zh:"表示程度达到极点，多用于口语，常带有强烈的感情色彩。",explanation_en:"Indicates reaching the extreme degree, mostly used in spoken language, often with strong emotional color.",example_zh:"今天热死了。\n我高兴极了。\n这个孩子把妈妈气坏了。",example_pinyin:"Jīntiān r\xe8 sǐ le.\nWǒ gāox\xecng j\xed le.\nZh\xe8ge h\xe1izi bǎ māma q\xec hu\xe0i le.",example_en:"Today is so hot I could die.\nI am extremely happy.\nThis child made his mother extremely angry.",usage_notes:"极了/死了/坏了：都表示程度极高，多用于口语",category:"补语"},{id:"grammar-4-5",hsk_level:4,pattern:"V / Adj + 得 + 不得了 / 要命 / 不行",title:"程度补语（不得了/要命/不行）",explanation_zh:"表示程度很深，常用于口语，带有夸张的语气。",explanation_en:"Indicates very deep degree, often used in spoken language with exaggerated tone.",example_zh:"我饿得不得了。\n今天热得要命。\n他累得不行了。",example_pinyin:"Wǒ \xe8 de b\xf9d\xe9liǎo.\nJīntiān r\xe8 de y\xe0om\xecng.\nTā l\xe8i de b\xf9x\xedng le.",example_en:"I am extremely hungry.\nToday is terribly hot.\nHe is exhausted.",usage_notes:"不得了/要命/不行：都表示程度极深，口语中常用",category:"补语"},{id:"grammar-4-6",hsk_level:4,pattern:"V + 得 + 不能再 V 了",title:"程度补语（不能再……了）",explanation_zh:"表示程度达到了顶点，不能再继续了。",explanation_en:"Indicates that the degree has reached the peak and cannot continue.",example_zh:"我累得不能再累了。\n这个菜辣得不能再辣了。\n他快得不能再快了。",example_pinyin:"Wǒ l\xe8i de b\xf9 n\xe9ng z\xe0i l\xe8i le.\nZh\xe8ge c\xe0i l\xe0 de b\xf9 n\xe9ng z\xe0i l\xe0 le.\nTā ku\xe0i de b\xf9 n\xe9ng z\xe0i ku\xe0i le.",example_en:"I am as tired as I can be.\nThis dish is as spicy as it can be.\nHe is as fast as he can be.",usage_notes:"表示程度达到极限，无法再增加",category:"补语"},{id:"grammar-4-7",hsk_level:4,pattern:"S + 把 + O + V + 得 + 状态",title:'"把"字句（状态补语）',explanation_zh:'"把"字句中动词后带"得"字状态补语，表示动作使宾语达到某种状态。',explanation_en:'In a "ba" sentence, the verb is followed by a state complement with "de", indicating that the action brings the object to a certain state.',example_zh:"他把我气得不得了。\n你把房间弄得乱七八糟。\n他把衣服洗得干干净净。",example_pinyin:"Tā bǎ wǒ q\xec de b\xf9d\xe9liǎo.\nNǐ bǎ f\xe1ngjiān n\xf2ng de lu\xe0nqībāzāo.\nTā bǎ yīfu xǐ de gāngānj\xecngj\xecng.",example_en:"He made me extremely angry.\nYou made the room a mess.\nHe washed the clothes spotlessly clean.",usage_notes:"状态补语说明动作对宾语产生的状态或结果",category:"把字句"},{id:"grammar-4-8",hsk_level:4,pattern:"S + 把 + O + V + 成 / 作 + N",title:'"把"字句（当作/作为）',explanation_zh:"表示把宾语当作、看作另一个事物。",explanation_en:"Indicates treating the object as or considering it another thing.",example_zh:"他把我当成朋友了。\n把学校当作自己的家。\n把困难看作挑战。",example_pinyin:"Tā bǎ wǒ d\xe0ngch\xe9ng p\xe9ngyou le.\nBǎ xu\xe9xi\xe0o d\xe0ngzu\xf2 z\xecjǐ de jiā.\nBǎ k\xf9nn\xe1n k\xe0nzu\xf2 tiǎozh\xe0n.",example_en:"He regards me as a friend.\nTreat the school as your own home.\nRegard difficulties as challenges.",usage_notes:"当成/当作/看作：表示主观上认为是某种事物",category:"把字句"},{id:"grammar-4-9",hsk_level:4,pattern:"S + 把 + O + V1 + V2",title:'"把"字句（连动式）',explanation_zh:'"把"字句中动词带两个或两个以上的补语或趋向。',explanation_en:'In a "ba" sentence, the verb has two or more complements or directions.',example_zh:"他把书拿了出来。\n把衣服脱了下来。\n他把车开了过去。",example_pinyin:"Tā bǎ shū n\xe1 le chūl\xe1i.\nBǎ yīfu tuō le xi\xe0l\xe1i.\nTā bǎ chē kāi le gu\xf2q\xf9.",example_en:"He took the book out.\nTake off the clothes.\nHe drove the car over.",usage_notes:'"把"字句中动词后可以有"了"和趋向补语等多个成分',category:"把字句"},{id:"grammar-4-10",hsk_level:4,pattern:"S + 被 + O + V + 得 + 状态",title:'"被"字句（状态补语）',explanation_zh:'"被"字句中动词后带"得"字状态补语，表示被动动作造成的状态。',explanation_en:'In a "bei" sentence, the verb is followed by a state complement with "de", indicating the state caused by the passive action.',example_zh:"他被打得浑身是伤。\n我被气得说不出话。\n她被感动得流下了眼泪。",example_pinyin:"Tā b\xe8i dǎ de h\xfanshēn sh\xec shāng.\nWǒ b\xe8i q\xec de shuō bu chū hu\xe0.\nTā b\xe8i gǎnd\xf2ng de li\xfa xi\xe0 le yǎnl\xe8i.",example_en:"He was beaten black and blue.\nI was so angry I could not speak.\nShe was moved to tears.",usage_notes:"状态补语说明被动动作造成的状态",category:"被动"},{id:"grammar-4-11",hsk_level:4,pattern:"为 / 被 / 给 + 所 + V",title:'被动句"为……所……"',explanation_zh:"书面语中表示被动的格式。",explanation_en:"A formal pattern for expressing passive voice in written language.",example_zh:"他的为人所敬重。\n这个故事为人们所传颂。\n他的作品被大家所喜爱。",example_pinyin:"Tā de w\xe9ir\xe9n suǒ j\xecngzh\xf2ng.\nZh\xe8ge g\xf9shi w\xe9i r\xe9nmen suǒ chu\xe1ns\xf2ng.\nTā de zu\xf2pǐn b\xe8i d\xe0jiā suǒ xǐ'\xe0i.",example_en:"He is respected by people.\nThis story is eulogized by people.\nHis works are loved by everyone.",usage_notes:"为……所……：书面语，较正式",category:"被动"},{id:"grammar-4-12",hsk_level:4,pattern:"S + 为 + O + V",title:'介词"为"',explanation_zh:"表示动作的对象、目的或原因。",explanation_en:"Indicates the object, purpose, or reason of an action.",example_zh:"为人民服务。\n他为我买了一本书。\n为了健康，他每天锻炼。",example_pinyin:"W\xe8i r\xe9nm\xedn f\xfaw\xf9.\nTā w\xe8i wǒ mǎi le y\xec běn shū.\nW\xe8ile ji\xe0nkāng, tā měitiān du\xe0nli\xe0n.",example_en:"Serve the people.\nHe bought a book for me.\nFor health, he exercises every day.",usage_notes:"为：引出对象或目的；为了：专门表示目的",category:"介词"},{id:"grammar-4-13",hsk_level:4,pattern:"S + 按照 / 根据 + N + V",title:'介词"按照/根据"',explanation_zh:"表示动作的依据、标准。",explanation_en:"Indicates the basis or standard of an action.",example_zh:"请按照规定做。\n根据调查，他是对的。\n按照计划，我们明天出发。",example_pinyin:"Qǐng \xe0nzh\xe0o guīd\xecng zu\xf2.\nGēnj\xf9 di\xe0och\xe1, tā sh\xec du\xec de.\n\xc0nzh\xe0o j\xechu\xe0, wǒmen m\xedngtiān chūfā.",example_en:"Please do it according to the rules.\nAccording to the investigation, he is right.\nAccording to the plan, we leave tomorrow.",usage_notes:"按照/根据：表示以某事为依据",category:"介词"},{id:"grammar-4-14",hsk_level:4,pattern:"S + 由于 + N / 句子 + V",title:'介词"由于"',explanation_zh:"表示原因，多用于书面语。",explanation_en:"Indicates reason, mostly used in written language.",example_zh:"由于天气不好，飞机晚点了。\n由于他的帮助，我成功了。\n由于下雨，比赛取消了。",example_pinyin:"Y\xf3uy\xfa tiānq\xec b\xf9 hǎo, fēijī wǎndiǎn le.\nY\xf3uy\xfa tā de bāngzh\xf9, wǒ ch\xe9nggōng le.\nY\xf3uy\xfa xi\xe0 yǔ, bǐs\xe0i qǔxiāo le.",example_en:"Due to bad weather, the plane was late.\nThanks to his help, I succeeded.\nDue to rain, the game was canceled.",usage_notes:'由于：表示原因，比"因为"更正式',category:"介词"},{id:"grammar-4-15",hsk_level:4,pattern:"S + 通过 + N + V",title:'介词"通过"',explanation_zh:"表示动作的媒介、方式或手段。",explanation_en:"Indicates the medium, method, or means of an action.",example_zh:"通过学习，我了解了中国文化。\n通过朋友介绍，我认识了他。\n通过考试，证明了他的能力。",example_pinyin:"Tōnggu\xf2 xu\xe9x\xed, wǒ liǎojiě le zhōnggu\xf3 w\xe9nhu\xe0.\nTōnggu\xf2 p\xe9ngyou ji\xe8sh\xe0o, wǒ r\xe8nshi le tā.\nTōnggu\xf2 kǎosh\xec, zh\xe8ngm\xedng le tā de n\xe9ngl\xec.",example_en:"Through studying, I learned about Chinese culture.\nThrough a friend's introduction, I met him.\nThrough the exam, his ability was proven.",usage_notes:"通过：表示以某种方式、手段达到目的",category:"介词"},{id:"grammar-4-16",hsk_level:4,pattern:"S + 对于 + O + 来说 / 来讲",title:'"对于……来说/来讲"',explanation_zh:"表示从某人或某事物的角度来考虑、判断。",explanation_en:"Indicates considering or judging from the perspective of someone or something.",example_zh:"对于学生来说，学习最重要。\n对于他来讲，这很简单。\n对于老年人来说，健康最重要。",example_pinyin:"Du\xecy\xfa xu\xe9shēng l\xe1i shuō, xu\xe9x\xed zu\xec zh\xf2ngy\xe0o.\nDu\xecy\xfa tā l\xe1i jiǎng, zh\xe8 hěn jiǎndān.\nDu\xecy\xfa lǎoni\xe1nr\xe9n l\xe1i shuō, ji\xe0nkāng zu\xec zh\xf2ngy\xe0o.",example_en:"For students, studying is the most important.\nFor him, this is very simple.\nFor the elderly, health is the most important.",usage_notes:"对于……来说/来讲：表示从某个角度看问题",category:"介词"},{id:"grammar-4-17",hsk_level:4,pattern:"S + 非 + Adj/V + 不可",title:'"非……不可"',explanation_zh:"表示必须、一定要这样，强调必要性。",explanation_en:"Indicates that something must be done, emphasizing necessity.",example_zh:"今天我非去不可。\n这件事非你做不可。\n我非学好汉语不可。",example_pinyin:"Jīntiān wǒ fēi q\xf9 b\xf9kě.\nZh\xe8 ji\xe0n sh\xec fēi nǐ zu\xf2 b\xf9kě.\nWǒ fēi xu\xe9hǎo h\xe0nyǔ b\xf9kě.",example_en:"I absolutely must go today.\nThis matter must be done by you.\nI must learn Chinese well.",usage_notes:'非……不可：表示强烈的必要性，"一定"的意思',category:"句型"},{id:"grammar-4-18",hsk_level:4,pattern:"是……还是……？",title:'选择疑问句"是……还是……"',explanation_zh:"提出两种或几种可能，让对方选择回答。",explanation_en:"Present two or several possibilities for the other person to choose and answer.",example_zh:"你是喝茶还是喝咖啡？\n今天是星期三还是星期四？\n你去还是不去？",example_pinyin:"Nǐ sh\xec hē ch\xe1 h\xe1ish\xec hē kāfēi?\nJīntiān sh\xec xīngqīsān h\xe1ish\xec xīngqīs\xec?\nNǐ q\xf9 h\xe1ish\xec b\xfa q\xf9?",example_en:"Do you drink tea or coffee?\nIs today Wednesday or Thursday?\nAre you going or not?",usage_notes:"是……还是……：表示选择，可用于各种成分",category:"句型"},{id:"grammar-4-19",hsk_level:4,pattern:"S + 本来 + V/Adj",title:'副词"本来"',explanation_zh:"表示原先、先前的情况，或表示理所当然。",explanation_en:"Indicates the original or previous situation, or indicates something that goes without saying.",example_zh:"我本来不想去。\n他本来就是中国人。\n这本是我的书。",example_pinyin:"Wǒ běnl\xe1i b\xf9 xiǎng q\xf9.\nTā běnl\xe1i ji\xf9 sh\xec zhōnggu\xf3 r\xe9n.\nZh\xe8 běn sh\xec wǒ de shū.",example_en:"I originally did not want to go.\nHe is originally Chinese.\nThis is originally my book.",usage_notes:"本来：原先、先前；理所当然",category:"副词"},{id:"grammar-4-20",hsk_level:4,pattern:"S + 居然 / 竟然 + V",title:'副词"居然/竟然"',explanation_zh:"表示出乎意料，没想到。",explanation_en:"Indicates something unexpected, beyond expectation.",example_zh:"他居然来了。\n这么难的题，他竟然做出来了。\n我居然忘了你的名字。",example_pinyin:"Tā jūr\xe1n l\xe1i le.\nZh\xe8me n\xe1n de t\xed, tā j\xecngr\xe1n zu\xf2 chūl\xe1i le.\nWǒ jūr\xe1n w\xe0ng le nǐ de m\xedngzi.",example_en:"He actually came.\nSuch a difficult problem, he actually solved it.\nI actually forgot your name.",usage_notes:'居然/竟然：表示出乎意料，"竟然"语气略重',category:"副词"},{id:"grammar-4-21",hsk_level:4,pattern:"S + 果然 + V/Adj",title:'副词"果然"',explanation_zh:"表示事实与所说或所料相符。",explanation_en:"Indicates that the facts match what was said or expected.",example_zh:"他果然来了。\n天气预报说今天下雨，果然下了。\n这个办法果然有效。",example_pinyin:"Tā guǒr\xe1n l\xe1i le.\nTiānq\xec y\xf9b\xe0o shuō jīntiān xi\xe0 yǔ, guǒr\xe1n xi\xe0 le.\nZh\xe8ge b\xe0nfǎ guǒr\xe1n yǒuxi\xe0o.",example_en:"He came as expected.\nThe weather forecast said it would rain today, and it did.\nThis method really works as expected.",usage_notes:"果然：表示事情的结果与预料的一样",category:"副词"},{id:"grammar-4-22",hsk_level:4,pattern:"S + 只好 / 只得 + V",title:'副词"只好/只得"',explanation_zh:"表示没有别的办法，只能这样。",explanation_en:"Indicates there is no other way, can only do this.",example_zh:"没有车了，我只好走路回去。\n他不同意，我只得放弃。\n没钱了，只好不买了。",example_pinyin:"M\xe9iyǒu chē le, wǒ zhǐhǎo zǒul\xf9 hu\xedq\xf9.\nTā b\xf9 t\xf3ngy\xec, wǒ zhǐd\xe9 f\xe0ngq\xec.\nM\xe9i qi\xe1n le, zhǐhǎo b\xf9 mǎi le.",example_en:"There is no more bus, I have to walk back.\nHe disagreed, I had to give up.\nNo money, so I have to not buy it.",usage_notes:"只好/只得：表示不得已，只能这么做",category:"副词"},{id:"grammar-4-23",hsk_level:4,pattern:"S + 反正 + V/Adj",title:'副词"反正"',explanation_zh:"表示情况虽然不同，但结果都一样；表示肯定的语气。",explanation_en:"Indicates that although situations differ, the result is the same; expresses affirmative tone.",example_zh:"反正我不去，你别劝我了。\n反正都一样，随便吧。\n反正他会来的，你别急。",example_pinyin:"Fǎnzh\xe8ng wǒ b\xfa q\xf9, nǐ bi\xe9 qu\xe0n wǒ le.\nFǎnzh\xe8ng dōu y\xedy\xe0ng, su\xedbi\xe0n ba.\nFǎnzh\xe8ng tā hu\xec l\xe1i de, nǐ bi\xe9 j\xed.",example_en:"Anyway I am not going, stop persuading me.\nAnyway it is all the same, whatever.\nAnyway he will come, don't worry.",usage_notes:"反正：表示不管怎样，结果都一样",category:"副词"},{id:"grammar-4-24",hsk_level:4,pattern:"S + 简直 + Adj/V",title:'副词"简直"',explanation_zh:"表示完全如此，语气带有夸张或强调。",explanation_en:"Indicates completely so, tone carries exaggeration or emphasis.",example_zh:"他简直太聪明了。\n这简直是个奇迹。\n我简直不敢相信。",example_pinyin:"Tā jiǎnzh\xed t\xe0i cōngm\xedng le.\nZh\xe8 jiǎnzh\xed sh\xec ge q\xedj\xec.\nWǒ jiǎnzh\xed b\xf9 gǎn xiāngx\xecn.",example_en:"He is simply too smart.\nThis is simply a miracle.\nI simply cannot believe it.",usage_notes:"简直：表示强调，带有夸张语气",category:"副词"},{id:"grammar-4-25",hsk_level:4,pattern:"S + 万一 + 句子，就……",title:'副词/连词"万一"',explanation_zh:"表示可能性极小的假设，多用于不希望发生的事。",explanation_en:"Indicates a hypothesis with very small possibility, mostly used for things not hoped to happen.",example_zh:"万一下雨怎么办？\n万一他不来，我们就先走。\n万一有问题，给我打电话。",example_pinyin:"W\xe0nyī xi\xe0 yǔ zěnme b\xe0n?\nW\xe0nyī tā b\xf9 l\xe1i, wǒmen ji\xf9 xiān zǒu.\nW\xe0nyī yǒu w\xe8nt\xed, gěi wǒ dǎ di\xe0nhu\xe0.",example_en:"What if it rains?\nIn case he does not come, we will leave first.\nIn case there is a problem, call me.",usage_notes:"万一：表示可能性极小的假设，多指不如意的事",category:"副词"},{id:"grammar-4-26",hsk_level:4,pattern:"S + 忽然 / 突然 + V",title:'副词"忽然/突然"',explanation_zh:"表示事情发生得迅速而又出乎意料。",explanation_en:"Indicates that something happens quickly and unexpectedly.",example_zh:"他忽然来了。\n突然下起了大雨。\n我忽然想起了一件事。",example_pinyin:"Tā hūr\xe1n l\xe1i le.\nTūr\xe1n xi\xe0 qǐ le d\xe0 yǔ.\nWǒ hūr\xe1n xiǎng qǐ le y\xed ji\xe0n sh\xec.",example_en:"He suddenly came.\nIt suddenly started raining heavily.\nI suddenly remembered something.",usage_notes:'忽然/突然：表示发生得快而出乎意料；"突然"还可以作形容词',category:"副词"},{id:"grammar-4-27",hsk_level:4,pattern:"S + 悄悄 / 偷偷 + V",title:'副词"悄悄/偷偷"',explanation_zh:"表示动作声音很小，不让别人知道。",explanation_en:"Indicates that the action is done quietly, without letting others know.",example_zh:"他悄悄地走了。\n我偷偷地看了他一眼。\n请小声点，悄悄说。",example_pinyin:"Tā qiāoqiāo de zǒu le.\nWǒ tōutōu de k\xe0n le tā y\xec yǎn.\nQǐng xiǎo shēng diǎn, qiāoqiāo shuō.",example_en:"He left quietly.\nI secretly glanced at him.\nPlease keep your voice down, speak quietly.",usage_notes:"悄悄：声音小、不让人知道；偷偷：瞒着人做",category:"副词"},{id:"grammar-4-28",hsk_level:4,pattern:"A + 跟 + B + 比起来 / 相比",title:'"跟……比起来/相比"',explanation_zh:"表示比较两个事物的异同。",explanation_en:"Indicates comparing the similarities and differences of two things.",example_zh:"跟去年比起来，今年的产量提高了。\n跟他相比，我还差得远。\n和过去比起来，现在好多了。",example_pinyin:"Gēn q\xf9ni\xe1n bǐ qǐl\xe1i, jīnni\xe1n de chǎnli\xe0ng t\xedgāo le.\nGēn tā xiāngbǐ, wǒ h\xe1i ch\xe0 de yuǎn.\nH\xe9 gu\xf2q\xf9 bǐ qǐl\xe1i, xi\xe0nz\xe0i hǎo duō le.",example_en:"Compared with last year, this year's production has increased.\nCompared with him, I am still far behind.\nCompared with the past, it is much better now.",usage_notes:"跟/和……比起来/相比：引出比较的对象",category:"比较"},{id:"grammar-4-29",hsk_level:4,pattern:"不仅……，还/而且……",title:'递进复句"不仅……还/而且……"',explanation_zh:"表示在原有的基础上，还有进一步的内容。",explanation_en:"Indicates that on the existing basis, there is further content.",example_zh:"他不仅会说英语，还会说法语。\n这个办法不仅简单，而且有效。\n我不仅认识他，还很了解他。",example_pinyin:"Tā b\xf9jǐn hu\xec shuō yīngyǔ, h\xe1i hu\xec shuō fǎyǔ.\nZh\xe8ge b\xe0nfǎ b\xf9jǐn jiǎndān, \xe9rqiě yǒuxi\xe0o.\nWǒ b\xf9jǐn r\xe8nshi tā, h\xe1i hěn liǎojiě tā.",example_en:"He can not only speak English, but also French.\nThis method is not only simple, but also effective.\nI not only know him, but also understand him well.",usage_notes:"不仅……还/而且……：表示递进，后者比前者更进一层",category:"连词"},{id:"grammar-4-30",hsk_level:4,pattern:"既……也/又……",title:'并列复句"既……也/又……"',explanation_zh:"表示两个方面同时存在或两种动作同时进行。",explanation_en:"Indicates that two aspects exist simultaneously or two actions proceed simultaneously.",example_zh:"他既聪明又努力。\n既要努力学习，也要注意身体。\n这个办法既简单又有效。",example_pinyin:"Tā j\xec cōngm\xedng y\xf2u nǔl\xec.\nJ\xec y\xe0o nǔl\xec xu\xe9x\xed, yě y\xe0o zh\xf9y\xec shēntǐ.\nZh\xe8ge b\xe0nfǎ j\xec jiǎndān y\xf2u yǒuxi\xe0o.",example_en:"He is both smart and hardworking.\nWe must both study hard and take care of our health.\nThis method is both simple and effective.",usage_notes:"既……也……：两个方面同等重要；既……又……：两种性质同时具备",category:"连词"},{id:"grammar-4-31",hsk_level:4,pattern:"要么……，要么……",title:'选择复句"要么……要么……"',explanation_zh:"表示在两种情况中选择一种，非此即彼。",explanation_en:"Indicates choosing one of two situations, either this or that.",example_zh:"要么你去，要么我去。\n要么现在就走，要么明天再走。\n要么学汉语，要么学英语。",example_pinyin:"Y\xe0ome nǐ q\xf9, y\xe0ome wǒ q\xf9.\nY\xe0ome xi\xe0nz\xe0i ji\xf9 zǒu, y\xe0ome m\xedngtiān z\xe0i zǒu.\nY\xe0ome xu\xe9 h\xe0nyǔ, y\xe0ome xu\xe9 yīngyǔ.",example_en:"Either you go, or I go.\nEither leave now, or leave tomorrow.\nEither study Chinese, or study English.",usage_notes:"要么……要么……：表示二者必居其一",category:"连词"},{id:"grammar-4-32",hsk_level:4,pattern:"幸亏……，不然/否则……",title:'因果复句"幸亏……不然/否则……"',explanation_zh:"表示由于某种有利条件而侥幸避免了不良后果。",explanation_en:"Indicates that due to some favorable condition, a bad consequence was fortunately avoided.",example_zh:"幸亏你提醒我，不然我就忘了。\n幸亏有你帮忙，否则我做不完。\n幸亏他来了，不然就麻烦了。",example_pinyin:"X\xecngkuī nǐ t\xedxǐng wǒ, b\xf9r\xe1n wǒ ji\xf9 w\xe0ng le.\nX\xecngkuī yǒu nǐ bāngm\xe1ng, fǒuz\xe9 wǒ zu\xf2 bu w\xe1n.\nX\xecngkuī tā l\xe1i le, b\xf9r\xe1n ji\xf9 m\xe1fan le.",example_en:"Fortunately you reminded me, otherwise I would have forgotten.\nFortunately with your help, otherwise I could not finish.\nFortunately he came, otherwise there would be trouble.",usage_notes:"幸亏：表示借以免除困难的有利情况",category:"连词"},{id:"grammar-4-33",hsk_level:4,pattern:"除非……，才/否则……",title:'条件复句"除非……才/否则……"',explanation_zh:"表示唯一的条件，只有在这个条件下才会有某种结果。",explanation_en:"Indicates the only condition, only under this condition will there be a certain result.",example_zh:"除非你努力，否则不会成功。\n除非他来，我才走。\n除非你答应我，我才告诉你。",example_pinyin:"Ch\xfafēi nǐ nǔl\xec, fǒuz\xe9 b\xfa hu\xec ch\xe9nggōng.\nCh\xfafēi tā l\xe1i, wǒ c\xe1i zǒu.\nCh\xfafēi nǐ dāying wǒ, wǒ c\xe1i g\xe0osu nǐ.",example_en:"Unless you work hard, you will not succeed.\nOnly if he comes will I leave.\nOnly if you promise me will I tell you.",usage_notes:'除非：表示唯一的条件，相当于"只有"',category:"连词"},{id:"grammar-4-34",hsk_level:4,pattern:"无论 / 不管……都 / 也……",title:'条件复句"无论/不管……都/也……"',explanation_zh:"表示在任何条件下结果都不会改变。",explanation_en:"Indicates that the result will not change under any conditions.",example_zh:"无论天气好不好，我都去。\n不管你同意不同意，我都要做。\n无论多难，也不能放弃。",example_pinyin:"W\xfal\xf9n tiānq\xec hǎo bu hǎo, wǒ dōu q\xf9.\nB\xf9guǎn nǐ t\xf3ngy\xec b\xf9 t\xf3ngy\xec, wǒ dōu y\xe0o zu\xf2.\nW\xfal\xf9n duō n\xe1n, yě b\xf9 n\xe9ng f\xe0ngq\xec.",example_en:"No matter whether the weather is good or not, I will go.\nWhether you agree or not, I will do it.\nNo matter how difficult, we must not give up.",usage_notes:'无论/不管：表示无条件，后面多用"都、也"呼应',category:"连词"},{id:"grammar-4-35",hsk_level:4,pattern:"V + 开 / 开来",title:'趋向补语"开/开来"（引申义）',explanation_zh:"表示动作开始并继续，或表示舒展、展开。",explanation_en:"Indicates that an action starts and continues, or indicates unfolding or spreading out.",example_zh:"他笑开了。\n天气暖和起来了，花儿都开了。\n消息传开了。",example_pinyin:"Tā xi\xe0o kāi le.\nTiānq\xec nuǎnhuo qǐl\xe1i le, huā'\xe9r dōu kāi le.\nXiāoxi chu\xe1n kāi le.",example_en:"He started laughing.\nThe weather is getting warm, flowers are all blooming.\nThe news spread.",usage_notes:"开：开始并继续；展开、舒展；分开",category:"补语"},{id:"grammar-4-36",hsk_level:4,pattern:"V + 住",title:'趋向/结果补语"住"',explanation_zh:"表示动作的结果是停留、固定、牢固。",explanation_en:"Indicates that the result of an action is staying, fixing, or securing.",example_zh:"请等一下，别拦住他。\n房子盖好了，终于住上了。\n他把我叫住了。",example_pinyin:"Qǐng děng y\xedxi\xe0, bi\xe9 l\xe1nzh\xf9 tā.\nF\xe1ngzi g\xe0i hǎo le, zhōngy\xfa zh\xf9 sh\xe0ng le.\nTā bǎ wǒ ji\xe0o zh\xf9 le.",example_en:"Wait a moment, don't stop him.\nThe house is built, finally we can live in it.\nHe called out to stop me.",usage_notes:"住：表示停止、停留、固定；表示居住",category:"补语"},{id:"grammar-4-37",hsk_level:4,pattern:"V + 掉",title:'结果补语"掉"',explanation_zh:"表示动作的结果是除去、脱落、丢失。",explanation_en:"Indicates that the result of an action is removal, falling off, or loss.",example_zh:"他把衣服脱掉了。\n杯子掉在地上打碎了。\n我把这个坏习惯改掉了。",example_pinyin:"Tā bǎ yīfu tuō di\xe0o le.\nBēizi di\xe0o z\xe0i d\xecsh\xe0ng dǎsu\xec le.\nWǒ bǎ zh\xe8ge hu\xe0i x\xedgu\xe0n gǎi di\xe0o le.",example_en:"He took off his clothes.\nThe cup fell on the ground and broke.\nI got rid of this bad habit.",usage_notes:"掉：表示除去、脱落；表示落下",category:"补语"},{id:"grammar-4-38",hsk_level:4,pattern:"V + 成",title:'结果补语"成"',explanation_zh:"表示动作完成、成功，或表示成为某种状态。",explanation_en:"Indicates completion or success of an action, or becoming a certain state.",example_zh:"他办成了一件大事。\n我把他当成了朋友。\n你把这句话翻译成中文。",example_pinyin:"Tā b\xe0n ch\xe9ng le y\xed ji\xe0n d\xe0 sh\xec.\nWǒ bǎ tā d\xe0ngch\xe9ng le p\xe9ngyou.\nNǐ bǎ zh\xe8 j\xf9 hu\xe0 fāny\xec ch\xe9ng zhōngw\xe9n.",example_en:"He accomplished a great thing.\nI regard him as a friend.\nTranslate this sentence into Chinese.",usage_notes:"成：完成、成功；成为、变为",category:"补语"},{id:"grammar-4-39",hsk_level:4,pattern:'可能补语"得了/不了"',title:'可能补语"得了/不了"',explanation_zh:"表示动作能否完成或实现。",explanation_en:"Indicates whether an action can be completed or realized.",example_zh:"这么多饭，我吃不了。\n这个我办得了。\n他的病好不了了。",example_pinyin:"Zh\xe8me duō f\xe0n, wǒ chī bu liǎo.\nZh\xe8ge wǒ b\xe0n de liǎo.\nTā de b\xecng hǎo bu liǎo le.",example_en:"So much rice, I cannot finish it.\nI can handle this.\nHis illness cannot be cured.",usage_notes:"得了：能完成；不了：不能完成",category:"补语"},{id:"grammar-4-40",hsk_level:4,pattern:'可能补语"动得/不动"',title:'可能补语"动得/不动"',explanation_zh:"表示能否进行某动作，多用于体力或力量方面。",explanation_en:"Indicates whether an action can be carried out, mostly in terms of physical strength or force.",example_zh:"太重了，我搬不动。\n他跑得动吗？\n我走不动了。",example_pinyin:"T\xe0i zh\xf2ng le, wǒ bān bu d\xf2ng.\nTā pǎo de d\xf2ng ma?\nWǒ zǒu bu d\xf2ng le.",example_en:"It is too heavy, I cannot carry it.\nCan he still run?\nI cannot walk anymore.",usage_notes:"动得：能进行；不动：不能进行",category:"补语"},{id:"grammar-4-41",hsk_level:4,pattern:"V + 起 + O + 来",title:'趋向补语"起来"（分散到集中）',explanation_zh:"表示分散的事物集中起来，或表示动作开始、兴起。",explanation_en:"Indicates scattered things gathering together, or indicating the start or rise of an action.",example_zh:"把东西收起来。\n大家团结起来。\n他唱起歌来了。",example_pinyin:"Bǎ dōngxi shōu qǐl\xe1i.\nD\xe0jiā tu\xe1nji\xe9 qǐl\xe1i.\nTā ch\xe0ng qǐ gē l\xe1i le.",example_en:"Put things away.\nEveryone unite together.\nHe started singing.",usage_notes:"起来：表示集中、聚拢；表示开始、兴起",category:"补语"},{id:"grammar-4-42",hsk_level:4,pattern:"V + 下去",title:'趋向补语"下去"（持续）',explanation_zh:"表示动作继续进行或状态继续发展。",explanation_en:"Indicates that an action continues or a state continues to develop.",example_zh:"坚持下去就是胜利。\n你说下去，我听着。\n再这样下去不行。",example_pinyin:"Jiānch\xed xi\xe0q\xf9 ji\xf9 sh\xec sh\xe8ngl\xec.\nNǐ shuō xi\xe0q\xf9, wǒ tīng zhe.\nZ\xe0i zh\xe8y\xe0ng xi\xe0q\xf9 b\xf9x\xedng.",example_en:"Persisting means victory.\nContinue speaking, I am listening.\nContinuing like this won't work.",usage_notes:"下去：表示继续、持续",category:"补语"},{id:"grammar-4-43",hsk_level:4,pattern:"双宾语结构",title:"双宾语句（全面）",explanation_zh:"有些动词可以带两个宾语，一个指人（近宾语），一个指物（远宾语）。",explanation_en:"Some verbs can take two objects, one referring to a person (indirect object) and one to a thing (direct object).",example_zh:"老师教我们汉语。\n他问我一个问题。\n我告诉你一个好消息。",example_pinyin:"Lǎoshī jiāo wǒmen h\xe0nyǔ.\nTā w\xe8n wǒ y\xed ge w\xe8nt\xed.\nWǒ g\xe0osu nǐ y\xed ge hǎo xiāoxi.",example_en:"The teacher teaches us Chinese.\nHe asks me a question.\nI tell you a piece of good news.",usage_notes:"常见动词：给、送、教、借、还、问、告诉、通知等",category:"句型"},{id:"grammar-4-44",hsk_level:4,pattern:"兼语句（使令类）",title:"兼语句（使令类）",explanation_zh:"第一个动词是表示使令意义的动词，宾语兼作第二个动词的主语。",explanation_en:"The first verb is a causative verb, and its object also serves as the subject of the second verb.",example_zh:"老师让我们做作业。\n妈妈叫我回家。\n他请我去他家。",example_pinyin:"Lǎoshī r\xe0ng wǒmen zu\xf2 zu\xf2y\xe8.\nMāma ji\xe0o wǒ hu\xed jiā.\nTā qǐng wǒ q\xf9 tā jiā.",example_en:"The teacher asks us to do homework.\nMother tells me to go home.\nHe invites me to his home.",usage_notes:"常见使令动词：让、叫、请、使、令、派、选等",category:"句型"},{id:"grammar-4-45",hsk_level:4,pattern:"是……的（强调时间/地点/方式）",title:'"是……的"句（强调）',explanation_zh:"强调已经发生的动作的时间、地点、方式、对象等。",explanation_en:"Emphasizes the time, place, manner, object, etc. of an already occurred action.",example_zh:"我是昨天来的。\n他是坐飞机来的。\n这本书是我在北京买的。",example_pinyin:"Wǒ sh\xec zu\xf3tiān l\xe1i de.\nTā sh\xec zu\xf2 fēijī l\xe1i de.\nZh\xe8 běn shū sh\xec wǒ z\xe0i běijīng mǎi de.",example_en:"I came yesterday.\nHe came by plane.\nI bought this book in Beijing.",usage_notes:'强调的成分放在"是"和"的"之间；动词后不能加"了"',category:"句型"},{id:"grammar-4-46",hsk_level:4,pattern:"存现句（出现/消失）",title:"存现句（出现/消失）",explanation_zh:"表示什么地方出现或消失了什么人或事物。",explanation_en:"Indicates that someone or something appears or disappears in a certain place.",example_zh:"前面来了一个人。\n家里走了一位客人。\n天空中出现了一道彩虹。",example_pinyin:"Qi\xe1nmian l\xe1i le y\xed ge r\xe9n.\nJiā lǐ zǒu le y\xed w\xe8i k\xe8r\xe9n.\nTiānkōng zhōng chūxi\xe0n le y\xed d\xe0o cǎih\xf3ng.",example_en:"A person is coming from the front.\nA guest left the house.\nA rainbow appeared in the sky.",usage_notes:"句首是处所，动词表示出现或消失，宾语是存现的人或物",category:"句型"},{id:"grammar-4-47",hsk_level:4,pattern:'比况结构"像……似的/一样"',title:'比况助词"似的/一样"',explanation_zh:"表示比喻或比较，说明事物在某方面相似。",explanation_en:"Indicates metaphor or comparison, showing that things are similar in some aspect.",example_zh:"他像孩子似的高兴。\n他飞一样地跑了。\n像你这样的人不多。",example_pinyin:"Tā xi\xe0ng h\xe1izi sh\xec de gāox\xecng.\nTā fēi y\xedy\xe0ng de pǎo le.\nXi\xe0ng nǐ zh\xe8y\xe0ng de r\xe9n b\xf9 duō.",example_en:"He is as happy as a child.\nHe ran like flying.\nThere are not many people like you.",usage_notes:'似的/一样：跟"像、仿佛"等搭配，表示比喻',category:"助词"},{id:"grammar-4-48",hsk_level:4,pattern:"等 + O + V",title:'助词"等/等等"',explanation_zh:"表示列举未尽，或表示列举后煞尾。",explanation_en:"Indicates that the list is incomplete, or indicates the end of a list.",example_zh:"桌子上有书、本子、笔等。\n北京、上海、广州等等都是大城市。\n水果有苹果、香蕉等等。",example_pinyin:"Zhuōzi sh\xe0ng yǒu shū、běnzi、bǐ děng.\nBěijīng、sh\xe0nghǎi、guǎngzhōu děngdeng dōu sh\xec d\xe0 ch\xe9ngsh\xec.\nShuǐguǒ yǒu p\xedngguǒ、xiāngjiāo děngdeng.",example_en:"There are books, notebooks, pens, etc. on the table.\nBeijing, Shanghai, Guangzhou, etc. are all big cities.\nFruits include apples, bananas, and so on.",usage_notes:"等：列举未尽；等等：列举后煞尾，语气较舒缓",category:"助词"},{id:"grammar-4-49",hsk_level:4,pattern:"S + 所 + V + 的 + N",title:'助词"所"',explanation_zh:"用在动词前面，构成名词性短语，多用于书面语。",explanation_en:"Used before a verb to form a nominal phrase, mostly used in written language.",example_zh:"这是我所说的。\n他是大家所尊敬的人。\n我所知道的就是这些。",example_pinyin:"Zh\xe8 sh\xec wǒ suǒ shuō de.\nTā sh\xec d\xe0jiā suǒ zūnj\xecng de r\xe9n.\nWǒ suǒ zhīd\xe0o de ji\xf9 sh\xec zh\xe8xiē.",example_en:"This is what I said.\nHe is a person respected by everyone.\nThis is all I know.",usage_notes:'所：用在动词前，构成"所"字结构，相当于"……的(事物/人)"',category:"助词"},{id:"grammar-4-50",hsk_level:4,pattern:"被 / 叫 / 让 / 给 + 被动",title:"被动句（多种形式）",explanation_zh:"表示主语是动作的受事，有多种被动表达方式。",explanation_en:"Indicates that the subject is the recipient of the action, with various passive expression methods.",example_zh:"杯子被他打破了。\n杯子叫他打破了。\n杯子让他打破了。",example_pinyin:"Bēizi b\xe8i tā dǎp\xf2 le.\nBēizi ji\xe0o tā dǎp\xf2 le.\nBēizi r\xe0ng tā dǎp\xf2 le.",example_en:"The cup was broken by him.\nThe cup was broken by him.\nThe cup was broken by him.",usage_notes:"被：书面口语都用；叫/让：口语化；给：口语中加强语气",category:"被动"},{id:"grammar-4-51",hsk_level:4,pattern:"把 + O + 给 + V + 补语",title:'"把"字句中的"给"',explanation_zh:'"把"字句中动词前加"给"，加强处置的语气，多用于口语。',explanation_en:'Adding "gei" before the verb in a "ba" sentence strengthens the disposing tone, mostly used in spoken language.',example_zh:"他把衣服给洗干净了。\n我把信给寄出去了。\n他把杯子给打碎了。",example_pinyin:"Tā bǎ yīfu gěi xǐ gānj\xecng le.\nWǒ bǎ x\xecn gěi j\xec chūq\xf9 le.\nTā bǎ bēizi gěi dǎ su\xec le.",example_en:"He washed the clothes clean.\nI sent the letter out.\nHe broke the cup.",usage_notes:'"给"在这里是加强语气，没有实际意义',category:"把字句"},{id:"grammar-4-52",hsk_level:4,pattern:"一 + 量词 + 比 + 一 + 量词 + Adj",title:'"一……比一……"',explanation_zh:"表示程度逐次加深，一个比一个更甚。",explanation_en:"Indicates that the degree deepens successively, each one more than the previous.",example_zh:"他的成绩一次比一次好。\n天气一天比一天热。\n这些苹果一个比一个大。",example_pinyin:"Tā de ch\xe9ngj\xec y\xed c\xec bǐ y\xed c\xec hǎo.\nTiānq\xec y\xec tiān bǐ y\xec tiān r\xe8.\nZh\xe8xiē p\xedngguǒ y\xed ge bǐ y\xed ge d\xe0.",example_en:"His grades are getting better each time.\nThe weather is getting hotter day by day.\nThese apples are getting bigger one by one.",usage_notes:"一……比一……：表示逐个比较，程度逐次加深",category:"比较"},{id:"grammar-4-53",hsk_level:4,pattern:"越来越…… / 越……越……",title:'"越来越/越……越……"',explanation_zh:"表示程度随时间或动作的发展而加深。",explanation_en:"Indicates that degree intensifies as time or action develops.",example_zh:"天气越来越热了。\n我越学越喜欢汉语。\n他越跑越快。",example_pinyin:"Tiānq\xec yu\xe8l\xe1iyu\xe8 r\xe8 le.\nWǒ yu\xe8 xu\xe9 yu\xe8 xǐhuan h\xe0nyǔ.\nTā yu\xe8 pǎo yu\xe8 ku\xe0i.",example_en:"The weather is getting hotter and hotter.\nThe more I study, the more I like Chinese.\nThe more he runs, the faster he gets.",usage_notes:"越来越：程度随时间变化；越……越……：程度随动作变化",category:"比较"},{id:"grammar-4-54",hsk_level:4,pattern:"各 + 量词 + 名词",title:'代词"各/每"辨析',explanation_zh:'"各"和"每"都指所有个体，但侧重点不同。',explanation_en:'Both "ge" and "mei" refer to all individuals, but with different emphases.',example_zh:"各班都有自己的特点。\n每个学生都要努力。\n各有各的好处。",example_pinyin:"G\xe8 bān dōu yǒu z\xecjǐ de t\xe8diǎn.\nMěi ge xu\xe9shēng dōu y\xe0o nǔl\xec.\nG\xe8 yǒu g\xe8 de hǎoch\xf9.",example_en:"Each class has its own characteristics.\nEvery student must work hard.\nEach has its own advantages.",usage_notes:"各：强调不同个体之间的差异；每：强调全体中的任何一个都一样",category:"代词"},{id:"grammar-4-55",hsk_level:4,pattern:"Adj + 于",title:'形容词+"于"',explanation_zh:'某些形容词后加"于"，表示比较或引出对象。',explanation_en:'Adding "yu" after certain adjectives indicates comparison or introduces an object.',example_zh:"他的成绩高于平均分。\n这个办法优于那个。\n他小于二十岁。",example_pinyin:"Tā de ch\xe9ngj\xec gāo y\xfa p\xedngjūn fēn.\nZh\xe8ge b\xe0nfǎ yōu y\xfa n\xe0ge.\nTā xiǎo y\xfa \xe8rsh\xed su\xec.",example_en:"His grades are higher than the average.\nThis method is superior to that one.\nHe is younger than twenty.",usage_notes:"常见的有：大于、小于、高于、低于、优于、等于等",category:"形容词"},{id:"grammar-4-56",hsk_level:4,pattern:"离合动词",title:"离合动词",explanation_zh:"有些双音节词，合起来是一个词，分开用时中间可以插入其他成分。",explanation_en:"Some disyllabic words can be used as one word when combined, and other elements can be inserted when separated.",example_zh:"我每天睡觉睡八个小时。\n他帮了我很大的忙。\n我们见过几次面。",example_pinyin:"Wǒ měitiān shu\xecji\xe0o shu\xec bā ge xiǎosh\xed.\nTā bāng le wǒ hěn d\xe0 de m\xe1ng.\nWǒmen ji\xe0n gu\xf2 jǐ c\xec mi\xe0n.",example_en:"I sleep eight hours every day.\nHe helped me a great deal.\nWe have met several times.",usage_notes:"常见离合词：睡觉、帮忙、见面、结婚、吵架、唱歌等",category:"动词"},{id:"grammar-4-57",hsk_level:4,pattern:"V + 来 + V + 去",title:'"V来V去"',explanation_zh:"表示动作反复进行，没有确定结果。",explanation_en:"Indicates repeated action without a definite result.",example_zh:"他想来想去还是想不明白。\n我走来走去就是找不到。\n他看来看去觉得还是这个好。",example_pinyin:"Tā xiǎng l\xe1i xiǎng q\xf9 h\xe1i sh\xec xiǎng bu m\xedngbai.\nWǒ zǒu l\xe1i zǒu q\xf9 ji\xf9 sh\xec zhǎo bu d\xe0o.\nTā k\xe0n l\xe1i k\xe0n q\xf9 ju\xe9de h\xe1i sh\xec zh\xe8ge hǎo.",example_en:"He thought and thought but still could not understand.\nI walked back and forth but just could not find it.\nHe looked and looked and still thought this one was better.",usage_notes:"V来V去：表示动作反复、无确定结果",category:"动词"},{id:"grammar-4-58",hsk_level:4,pattern:"就 / 才 + 时间/数量",title:'"就/才"表时间数量辨析',explanation_zh:'"就"表示早、快、多；"才"表示晚、慢、少，都是主观评价。',explanation_en:'"Jiu" indicates early, fast, many; "cai" indicates late, slow, few, both are subjective evaluations.',example_zh:"他八点就来了。\n他十点才来。\n我就要了三个。",example_pinyin:"Tā bā diǎn ji\xf9 l\xe1i le.\nTā sh\xed diǎn c\xe1i l\xe1i.\nWǒ ji\xf9 y\xe0o le sān g\xe8.",example_en:"He came as early as eight o'clock.\nHe came as late as ten o'clock.\nI only asked for three.",usage_notes:"就：早、快、多（主观评价）；才：晚、慢、少（主观评价）",category:"副词"},{id:"grammar-4-59",hsk_level:4,pattern:"又 / 再 / 还",title:'"又/再/还"辨析',explanation_zh:"都表示动作重复或继续，但用法不同。",explanation_en:"All indicate repetition or continuation of action, but with different usages.",example_zh:"他昨天又来了。\n请再说一遍。\n他还没来。",example_pinyin:"Tā zu\xf3tiān y\xf2u l\xe1i le.\nQǐng z\xe0i shuō y\xed bi\xe0n.\nTā h\xe1i m\xe9i l\xe1i.",example_en:"He came again yesterday.\nPlease say it again.\nHe has not come yet.",usage_notes:"又：已发生的重复；再：未发生的重复；还：持续、仍然",category:"副词"},{id:"grammar-4-60",hsk_level:4,pattern:"的 / 地 / 得",title:'"的/地/得"辨析',explanation_zh:"三个结构助词，分别用于定语、状语和补语前。",explanation_en:"Three structural particles, used before attributive, adverbial, and complement respectively.",example_zh:"他是一个聪明的学生。\n他认真地学习。\n他学习学得很认真。",example_pinyin:"Tā sh\xec y\xed ge cōngm\xedng de xu\xe9shēng.\nTā r\xe8nzhēn de xu\xe9x\xed.\nTā xu\xe9x\xed xu\xe9 de hěn r\xe8nzhēn.",example_en:"He is a smart student.\nHe studies conscientiously.\nHe studies very conscientiously.",usage_notes:"的：定语后；地：状语后；得：补语前",category:"助词"},{id:"grammar-5-1",hsk_level:5,pattern:"A 比 B + 形容词 + 得多 / 多了 / 远了",title:"比较句（程度差别大）",explanation_zh:'表示比较的两方差别很大，用"得多、多了、远了等表示。',explanation_en:'Indicates a large difference between two compared parties, using "de duo, duo le, yuan le" etc.',example_zh:"他比我高得多。\n今天比昨天热多了。\n他的汉语比我好多了。",example_pinyin:"Tā bǐ wǒ gāo de duō.\nJīntiān bǐ zu\xf3tiān r\xe8 duō le.\nTā de h\xe0nyǔ bǐ wǒ hǎo duō le.",example_en:"He is much taller than me.\nToday is much hotter than yesterday.\nHis Chinese is much better than mine.",usage_notes:"得多/多了/远了：都表示程度差别大",category:"比较"},{id:"grammar-5-2",hsk_level:5,pattern:"S + 不如 / 比不上 / 赶不上 + O",title:'比较句"不如/比不上/赶不上"',explanation_zh:"表示前面的人或事物比不上后面的。",explanation_en:"Indicates that the preceding person or thing is not as good as the following one.",example_zh:"我的汉语不如他。\n我比不上他那么努力。\n这个班的成绩赶不上班上。",example_pinyin:"Wǒ de h\xe0nyǔ b\xf9r\xfa tā.\nWǒ bǐbush\xe0ng tā n\xe0me nǔl\xec.\nZh\xe8ge bān de ch\xe9ngj\xec gǎnbush\xe0ng bi\xe9 bān.",example_en:"My Chinese is not as good as his.\nI cannot compare with his hard work.\nThis class's grades cannot keep up with other classes.",usage_notes:"不如/比不上/赶不上：都表示前者不如后者",category:"比较"},{id:"grammar-5-3",hsk_level:5,pattern:"与其……不如……/宁可……也不……",title:"选择复句（取舍关系）",explanation_zh:"在两种情况中经过比较选择一种，舍弃另一种。",explanation_en:"After comparison, choose one option and abandon the other between two situations.",example_zh:"与其在家看电视，不如去看书。\n我宁可饿死，也不接受他的帮助。\n与其等他，不如我们先走。",example_pinyin:"Yǔq\xed z\xe0i jiā k\xe0n di\xe0nsh\xec, b\xf9r\xfa q\xf9 k\xe0n shū.\nWǒ n\xecngkě \xe8 sǐ, yě b\xf9 jiēsh\xf2u tā de bāngzh\xf9.\nYǔq\xed děng tā, b\xf9r\xfa wǒmen xiān zǒu.",example_en:"Rather than watch TV at home, better go read a book.\nI would rather starve than accept his help.\nRather than wait for him, let's go first.",usage_notes:"与其……不如……：选择后者；宁可……也不……：选择前者",category:"连词"},{id:"grammar-5-4",hsk_level:5,pattern:"固然……但是/可是/不过……",title:'转折复句"固然……但是……"',explanation_zh:"先承认某个事实，然后转折到另一方面。",explanation_en:"First acknowledge a fact, then转折 to another aspect.",example_zh:"这个办法固然好，但是太麻烦了。\n他固然聪明，可是不够努力。\n这样做固然没错，不过还要注意安全。",example_pinyin:"Zh\xe8ge b\xe0nfǎ g\xf9r\xe1n hǎo, d\xe0nsh\xec t\xe0i m\xe1fan le.\nTā g\xf9r\xe1n cōngm\xedng, kěsh\xec b\xf9g\xf2u nǔl\xec.\nZh\xe8y\xe0ng zu\xf2 g\xf9r\xe1n m\xe9i cu\xf2, b\xf9gu\xf2 h\xe1i y\xe0o zh\xf9y\xec ānqu\xe1n.",example_en:"This method is certainly good, but it is too troublesome.\nHe is certainly smart, but not hardworking enough.\nDoing this is certainly not wrong, but we must also pay attention to safety.",usage_notes:"固然：表示承认某个事实，引起下文转折",category:"连词"},{id:"grammar-5-5",hsk_level:5,pattern:"即使/哪怕/就算……也……",title:"假设让步复句",explanation_zh:"先退一步承认假设的情况，然后说出结果仍然不变。",explanation_en:"Take a step back to acknowledge a hypothetical situation, then state that the result remains unchanged.",example_zh:"即使下雨，我也去。\n哪怕困难再大，我们也要克服。\n就算你不说，我也知道。",example_pinyin:"J\xedshǐ xi\xe0 yǔ, wǒ yě q\xf9.\nNǎp\xe0 k\xf9nn\xe1n z\xe0i d\xe0, wǒmen yě y\xe0o k\xe8f\xfa.\nJi\xf9su\xe0n nǐ b\xf9 shuō, wǒ yě zhīd\xe0o.",example_en:"Even if it rains, I will go.\nEven if the difficulty is great, we must overcome it.\nEven if you don't say it, I know.",usage_notes:"即使/哪怕/就算：都表示假设的让步",category:"连词"},{id:"grammar-5-6",hsk_level:5,pattern:"无论/不管/不论……都/也……",title:"无条件复句",explanation_zh:"表示在任何条件下结果都一样。",explanation_en:"Indicates that the result is the same under any conditions.",example_zh:"无论你说什么，我都不相信。\n不管是谁，都要遵守规定。\n不论多难，也要坚持下去。",example_pinyin:"W\xfal\xf9n nǐ shuō sh\xe9nme, wǒ dōu b\xf9 xiāngx\xecn.\nB\xf9guǎn sh\xec shu\xed, dōu y\xe0o zūnshǒu guīd\xecng.\nB\xf9l\xf9n duō n\xe1n, yě y\xe0o jiānch\xed xi\xe0q\xf9.",example_en:"No matter what you say, I don't believe it.\nNo matter who it is, they must follow the rules.\nNo matter how difficult, we must persevere.",usage_notes:"无论/不管/不论：都表示无条件，结果不变",category:"连词"},{id:"grammar-5-7",hsk_level:5,pattern:"只要……就…… / 只有……才……",title:"条件复句辨析",explanation_zh:'"只要"是充足条件，"只有"是必要条件。',explanation_en:'"Zhǐy\xe0o" is a sufficient condition, "zhǐyǒu" is a necessary condition.',example_zh:"只要努力，就能成功。\n只有努力，才能成功。\n只要你去，我就去。",example_pinyin:"Zhǐy\xe0o nǔl\xec, ji\xf9 n\xe9ng ch\xe9nggōng.\nZhǐyǒu nǔl\xec, c\xe1i n\xe9ng ch\xe9nggōng.\nZhǐy\xe0o nǐ q\xf9, wǒ ji\xf9 q\xf9.",example_en:"As long as you work hard, you can succeed.\nOnly by working hard can one succeed.\nAs long as you go, I will go.",usage_notes:"只要……就……：充足条件；只有……才……：必要条件",category:"连词"},{id:"grammar-5-8",hsk_level:5,pattern:"既然……就/那么……",title:"推论因果复句",explanation_zh:"根据已经存在的事实推出结论。",explanation_en:"Draw a conclusion based on existing facts.",example_zh:"既然你知道错了，就应该改正。\n既然他不来，那我们就先走。\n既然答应了，就要做到。",example_pinyin:"J\xecr\xe1n nǐ zhīd\xe0o cu\xf2 le, ji\xf9 yīnggāi gǎizh\xe8ng.\nJ\xecr\xe1n tā b\xf9 l\xe1i, n\xe0 wǒmen ji\xf9 xiān zǒu.\nJ\xecr\xe1n dāying le, ji\xf9 y\xe0o zu\xf2d\xe0o.",example_en:"Since you know you are wrong, you should correct it.\nSince he is not coming, then let's go first.\nSince you promised, you must keep your word.",usage_notes:"既然：用于推论因果，根据事实推出结论",category:"连词"},{id:"grammar-5-9",hsk_level:5,pattern:"不但/不仅/不光……而且/并且/还……",title:"递进复句",explanation_zh:"后一分句比前一分句在意思上更进一层。",explanation_en:"The second clause goes a step further in meaning than the first clause.",example_zh:"他不但会说英语，而且会说法语。\n不仅我认识他，还很了解他。\n不光是我，大家都去。",example_pinyin:"Tā b\xf9d\xe0n hu\xec shuō yīngyǔ, \xe9rqiě hu\xec shuō fǎyǔ.\nB\xf9jǐn wǒ r\xe8nshi tā, h\xe1i hěn liǎojiě tā.\nB\xf9guāng sh\xec wǒ, d\xe0jiā dōu q\xf9.",example_en:"He can not only speak English, but also French.\nNot only do I know him, but I also understand him well.\nNot just me, everyone is going.",usage_notes:"不但/不仅/不光：都表示递进，后者比前者更进一层",category:"连词"},{id:"grammar-5-10",hsk_level:5,pattern:"尚且……何况/更不用说……",title:'递进复句"尚且……何况……"',explanation_zh:"前一句提出程度更甚的事例作为衬托，后一句用反问语气表示更进一层。",explanation_en:"The first sentence presents a more extreme case as contrast, the second sentence uses rhetorical tone to go further.",example_zh:"这么难的题，大人尚且不会，何况孩子呢？\n他尚且做不到，更不用说我了。\n平时他都忙，何况过年的时候呢？",example_pinyin:"Zh\xe8me n\xe1n de t\xed, d\xe0r\xe9n sh\xe0ngqiě b\xfa hu\xec, h\xe9ku\xe0ng h\xe1izi ne?\nTā sh\xe0ngqiě zu\xf2 bu d\xe0o, g\xe8ng b\xfay\xf2ng shuō wǒ le.\nP\xedngsh\xed tā dōu m\xe1ng, h\xe9ku\xe0ng gu\xf2ni\xe1n de sh\xedhou ne?",example_en:"Such a difficult problem, even adults cannot do it, let alone children?\nEven he cannot do it, not to mention me.\nHe is busy even on ordinary days, let alone during the New Year?",usage_notes:"尚且……何况……：用反问语气表示递进",category:"连词"},{id:"grammar-5-11",hsk_level:5,pattern:"由于/因为……所以/因此/因而……",title:"因果复句",explanation_zh:"前一分句说明原因，后一分句说明结果。",explanation_en:"The first clause explains the cause, the second clause explains the effect.",example_zh:"由于天气不好，所以飞机晚点了。\n因为他努力，因此成绩很好。\n他没来，因而不知道这件事。",example_pinyin:"Y\xf3uy\xfa tiānq\xec b\xf9 hǎo, suǒyǐ fēijī wǎndiǎn le.\nYīnw\xe8i tā nǔl\xec, yīncǐ ch\xe9ngj\xec hěn hǎo.\nTā m\xe9i l\xe1i, yīn'\xe9r b\xf9 zhīd\xe0o zh\xe8 ji\xe0n sh\xec.",example_en:"Due to bad weather, the plane was late.\nBecause he works hard, his grades are very good.\nHe did not come, therefore he does not know about this matter.",usage_notes:"由于/因为：表示原因；所以/因此/因而：表示结果",category:"连词"},{id:"grammar-5-12",hsk_level:5,pattern:"之所以……是因为/是由于……",title:"因果倒装句",explanation_zh:"先说结果，后说原因，强调原因。",explanation_en:"State the result first, then the reason, emphasizing the reason.",example_zh:"他之所以成功，是因为他很努力。\n我之所以来，是因为你邀请了我。\n他之所以没来，是由于生病了。",example_pinyin:"Tā zhī suǒyǐ ch\xe9nggōng, sh\xec yīnw\xe8i tā hěn nǔl\xec.\nWǒ zhī suǒyǐ l\xe1i, sh\xec yīnw\xe8i nǐ yāoqǐng le wǒ.\nTā zhī suǒyǐ m\xe9i l\xe1i, sh\xec y\xf3uy\xfa shēngb\xecng le.",example_en:"The reason he succeeded is because he works very hard.\nThe reason I came is because you invited me.\nThe reason he did not come is because he was sick.",usage_notes:"之所以……是因为/是由于……：结果在前，原因在后，强调原因",category:"连词"},{id:"grammar-5-13",hsk_level:5,pattern:"以便/以免/省得",title:"目的复句",explanation_zh:"前一分句表示动作，后一分句表示动作的目的。",explanation_en:"The first clause indicates an action, the second clause indicates the purpose of the action.",example_zh:"请早点儿来，以便有时间准备。\n请小声点，以免吵醒孩子。\n快走吧，省得迟到。",example_pinyin:"Qǐng zǎo diǎnr l\xe1i, yǐbi\xe0n yǒu sh\xedjiān zhǔnb\xe8i.\nQǐng xiǎo shēng diǎn, yǐmiǎn chǎoxǐng h\xe1izi.\nKu\xe0i zǒu ba, shěngde ch\xedd\xe0o.",example_en:"Please come earlier so that there is time to prepare.\nPlease keep your voice down so as not to wake the child.\nLet's go quickly, to avoid being late.",usage_notes:"以便：表示好的目的；以免/省得：表示避免不好的结果",category:"连词"},{id:"grammar-5-14",hsk_level:5,pattern:"V + 得 + 情态补语",title:"情态补语",explanation_zh:'在动词后用"得"引出补语，表示动作的状态、程度等。',explanation_en:'Use "de" after a verb to introduce a complement, indicating the state, degree, etc. of the action.',example_zh:"他跑得满头大汗。\n她笑得合不拢嘴。\n他说得大家都笑了。",example_pinyin:"Tā pǎo de mǎn t\xf3u d\xe0 h\xe0n.\nTā xi\xe0o de h\xe9 bu lǒng zuǐ.\nTā shuō de d\xe0jiā dōu xi\xe0o le.",example_en:"He ran until he was sweating profusely.\nShe laughed from ear to ear.\nHe spoke until everyone laughed.",usage_notes:"情态补语表示动作的状态或结果，常带有夸张意味",category:"补语"},{id:"grammar-5-15",hsk_level:5,pattern:"V / Adj + 得 + 很 / 极了 / 慌 / 要命 / 不行",title:"程度补语（高程度）",explanation_zh:"表示程度很高，多用于口语。",explanation_en:"Indicates very high degree, mostly used in spoken language.",example_zh:"今天热得很。\n我饿得慌。\n他累得不行了。",example_pinyin:"Jīntiān r\xe8 de hěn.\nWǒ \xe8 de huāng.\nTā l\xe8i de b\xf9x\xedng le.",example_en:"Today is very hot.\nI am extremely hungry.\nHe is exhausted.",usage_notes:"得很/极了/慌/要命/不行：都表示程度很深",category:"补语"},{id:"grammar-5-16",hsk_level:5,pattern:"V + 结果补语（到/见/懂/完/好/成/住/掉/开/惯",title:"结果补语（扩展）",explanation_zh:"表示动作的结果，动词后加结果补语。",explanation_en:"Indicates the result of an action, add a resultative complement after the verb.",example_zh:"我已经收到了你的信。\n我听懂了他的话。\n他已经住惯了这里的生活。",example_pinyin:"Wǒ yǐjīng shōud\xe0o le nǐ de x\xecn.\nWǒ tīngdǒng le tā de hu\xe0.\nTā yǐjīng zh\xf9gu\xe0n le zh\xe8lǐ de shēnghu\xf3.",example_en:"I have already received your letter.\nI understood what he said.\nHe has already gotten used to life here.",usage_notes:"常见结果补语：到、见、懂、完、好、成、住、掉、开、惯等",category:"补语"},{id:"grammar-5-17",hsk_level:5,pattern:"V + 得 / 不 + 结果补语",title:"可能补语（结果类）",explanation_zh:'在动词和结果补语之间加"得/不"，表示动作能否产生某种结果。',explanation_en:'Insert "de/bu" between the verb and resultative complement to indicate whether the action can produce a certain result.',example_zh:"这个题我做得对不对？\n太高了，我够不到。\n你看得见吗？",example_pinyin:"Zh\xe8ge t\xed wǒ zu\xf2 de du\xec bu du\xec?\nT\xe0i gāo le, wǒ g\xf2u bu d\xe0o.\nNǐ k\xe0n de ji\xe0n ma?",example_en:"Can I solve this problem correctly?\nIt is too high, I cannot reach it.\nCan you see it?",usage_notes:"可能补语表示主客观条件是否允许实现某种结果",category:"补语"},{id:"grammar-5-18",hsk_level:5,pattern:"V + 得 / 不 + 趋向补语",title:"可能补语（趋向类）",explanation_zh:'在动词和趋向补语之间加"得/不"，表示动作的趋向能否实现。',explanation_en:'Insert "de/bu" between the verb and directional complement to indicate whether the direction of the action can be realized.',example_zh:"这么高，我爬不上去。\n你出得来吗？\n他跑得过去吗？",example_pinyin:"Zh\xe8me gāo, wǒ p\xe1 bu sh\xe0ngq\xf9.\nNǐ chū de l\xe1i ma?\nTā pǎo de gu\xf2q\xf9 ma?",example_en:"So high, I cannot climb up.\nCan you come out?\nCan he run across?",usage_notes:'趋向补语的可能式：加"得"表示能，加"不"表示不能',category:"补语"},{id:"grammar-5-19",hsk_level:5,pattern:"V + 得 / 不 + 了 (liǎo)",title:'可能补语"得了/不了"',explanation_zh:"表示动作能否完成或实现，或表示能否承受。",explanation_en:"Indicates whether an action can be completed or realized, or whether it can be endured.",example_zh:"这么多饭，我吃不了。\n这个我办得了。\n他的病好不了了。",example_pinyin:"Zh\xe8me duō f\xe0n, wǒ chī bu liǎo.\nZh\xe8ge wǒ b\xe0n de liǎo.\nTā de b\xecng hǎo bu liǎo le.",example_en:"So much rice, I cannot finish it.\nI can handle this.\nHis illness cannot be cured.",usage_notes:"得了：能完成、能承受；不了：不能完成、不能承受",category:"补语"},{id:"grammar-5-20",hsk_level:5,pattern:"V + 得 / 不 + 动",title:'可能补语"动得/不动"',explanation_zh:"表示能否进行某动作，多用于体力、力量方面。",explanation_en:"Indicates whether an action can be carried out, mostly in terms of physical strength, force.",example_zh:"太重了，我搬不动。\n他还走得动吗？\n饿得都走不动了。",example_pinyin:"T\xe0i zh\xf2ng le, wǒ bān bu d\xf2ng.\nTā h\xe1i zǒu de d\xf2ng ma?\n\xc8 de dōu zǒu bu d\xf2ng le.",example_en:"It is too heavy, I cannot carry it.\nCan he still walk?\nSo hungry that I cannot walk anymore.",usage_notes:"动得：能进行；不动：不能进行",category:"补语"},{id:"grammar-5-21",hsk_level:5,pattern:"V + 上 / 下 / 进 / 出 / 回 / 过 / 起 / 开",title:"简单趋向补语",explanation_zh:"表示动作的方向，单音节趋向动词作补语。",explanation_en:"Indicates the direction of an action, monosyllabic directional verbs act as complements.",example_zh:"他爬上了山。\n请把窗户关上。\n他走进了房间。",example_pinyin:"Tā p\xe1sh\xe0ng le shān.\nQǐng bǎ chuāngh\xf9 guānsh\xe0ng.\nTā zǒuj\xecn le f\xe1ngjiān.",example_en:"He climbed up the mountain.\nPlease close the window.\nHe walked into the room.",usage_notes:"上/下/进/出/回/过/起/开：单音节趋向补语",category:"补语"},{id:"grammar-5-22",hsk_level:5,pattern:"V + 上来 / 下去 / 进来 / 出去 / 回来 / 过去 / 起来 / 开来",title:"复合趋向补语",explanation_zh:"由两个趋向动词组成的趋向补语。",explanation_en:"A directional complement composed of two directional verbs.",example_zh:"他走进来了。\n他跑出去了。\n把东西收起来。",example_pinyin:"Tā zǒu j\xecnl\xe1i le.\nTā pǎo chūq\xf9 le.\nBǎ dōngxi shōu qǐl\xe1i.",example_en:"He walked in.\nHe ran out.\nPut things away.",usage_notes:"复合趋向补语=简单趋向补语+来/去",category:"补语"},{id:"grammar-5-23",hsk_level:5,pattern:"趋向补语的引申义",title:"趋向补语的引申用法",explanation_zh:"趋向补语除了表示方向，还有很多抽象的引申义。",explanation_en:"Besides indicating direction, directional complements also have many abstract extended meanings.",example_zh:"他笑起来了。\n坚持下去就是胜利。\n他想起来了一件事。",example_pinyin:"Tā xi\xe0o qǐl\xe1i le.\nJiānch\xed xi\xe0q\xf9 ji\xf9 sh\xec sh\xe8ngl\xec.\nTā xiǎng qǐl\xe1i le y\xed ji\xe0n sh\xec.",example_en:"He started laughing.\nPersisting means victory.\nHe remembered something.",usage_notes:"起来：开始、兴起；下去：继续；出来：产生、出现",category:"补语"},{id:"grammar-5-24",hsk_level:5,pattern:"时量补语 / 动量补语 / 处所补语",title:"数量/处所补语",explanation_zh:"表示动作的时间长度、次数或处所。",explanation_en:"Indicates the duration, frequency, or location of an action.",example_zh:"我学了三年汉语。\n这个电影我看过三次。\n他住在北京。",example_pinyin:"Wǒ xu\xe9 le sān ni\xe1n h\xe0nyǔ.\nZh\xe8ge di\xe0nyǐng wǒ k\xe0ngu\xf2 sān c\xec.\nTā zh\xf9 z\xe0i běijīng.",example_en:"I studied Chinese for three years.\nI have seen this movie three times.\nHe lives in Beijing.",usage_notes:"时量补语：时间长度；动量补语：次数；处所补语：地点",category:"补语"},{id:"grammar-5-25",hsk_level:5,pattern:"把 + O + V + 结果补语 / 趋向补语 / 状态补语",title:'"把"字句（全面）',explanation_zh:'用"把"将宾语提前，表示对宾语的处置、影响。',explanation_en:'Use "ba" to move the object forward, indicating disposal or influence on the object.',example_zh:"他把作业做完了。\n把书拿过来。\n他把我气得说不出话。",example_pinyin:"Tā bǎ zu\xf2y\xe8 zu\xf2w\xe1n le.\nBǎ shū n\xe1 gu\xf2l\xe1i.\nTā bǎ wǒ q\xec de shuō bu chū hu\xe0.",example_en:"He finished the homework.\nBring the book over.\nHe made me so angry I could not speak.",usage_notes:"把字句：表示处置、影响；动词后要有补语或其他成分",category:"把字句"},{id:"grammar-5-26",hsk_level:5,pattern:"S + 被 / 叫 / 让 / 给 + V + 补语",title:"被动句（全面）",explanation_zh:"主语是动作的受事，表示被动。",explanation_en:"The subject is the recipient of the action, expressing passive voice.",example_zh:"杯子被他打破了。\n他叫老师批评了。\n他让雨淋了。",example_pinyin:"Bēizi b\xe8i tā dǎp\xf2 le.\nTā ji\xe0o lǎoshī pīp\xedng le.\nTā r\xe0ng yǔ l\xedn le.",example_en:"The cup was broken by him.\nHe was criticized by the teacher.\nHe got caught in the rain.",usage_notes:"被：书面口语都用；叫/让：口语化；给：口语加强语气",category:"被动"},{id:"grammar-5-27",hsk_level:5,pattern:"被……所 + V",title:'被动句"为……所……/被……所……"',explanation_zh:"书面语中的被动格式。",explanation_en:"Passive pattern in written language.",example_zh:"他的为人所大家所佩服。\n这个故事被人们所传颂。\n他的作品被广大读者所喜爱。",example_pinyin:"Tā de w\xe9ir\xe9n w\xe9i d\xe0jiā suǒ p\xe8if\xfa.\nZh\xe8ge g\xf9shi b\xe8i r\xe9nmen suǒ chu\xe1ns\xf2ng.\nTā de zu\xf2pǐn b\xe8i guǎngd\xe0 d\xfazhě suǒ xǐ'\xe0i.",example_en:"His character is admired by everyone.\nThis story is eulogized by people.\nHis works are loved by广大 readers.",usage_notes:"为……所……/被……所……：书面语，较正式",category:"被动"},{id:"grammar-5-28",hsk_level:5,pattern:"兼语句（使令/爱恨/称呼/推选）",title:"兼语句（多种类型）",explanation_zh:"第一个动词的宾语兼作第二个动词的主语。",explanation_en:"The object of the first verb also serves as the subject of the second verb.",example_zh:"老师让我们做作业。\n大家选他当班长。\n他怪我没告诉他。",example_pinyin:"Lǎoshī r\xe0ng wǒmen zu\xf2 zu\xf2y\xe8.\nD\xe0jiā xuǎn tā dāng bānzhǎng.\nTā gu\xe0i wǒ m\xe9i g\xe0osu tā.",example_en:"The teacher asks us to do homework.\nEveryone elected him class monitor.\nHe blames me for not telling him.",usage_notes:"兼语句类型：使令类、爱恨类、称呼类、推选类等",category:"句型"},{id:"grammar-5-29",hsk_level:5,pattern:"连动句（先后/方式目的/伴随）",title:"连动句（多种类型）",explanation_zh:"一个主语后面有两个或两个以上的动词短语。",explanation_en:"A subject is followed by two or more verb phrases.",example_zh:"我去学校上课。\n他用左手写字。\n他站着说话。",example_pinyin:"Wǒ q\xf9 xu\xe9xi\xe0o sh\xe0ng k\xe8.\nTā y\xf2ng zuǒshǒu xiě z\xec.\nTā zh\xe0nzhe shuō hu\xe0.",example_en:"I go to school to attend class.\nHe writes with his left hand.\nHe speaks while standing.",usage_notes:"连动句类型：先后动作、方式目的、伴随状态等",category:"句型"},{id:"grammar-5-30",hsk_level:5,pattern:"存现句（存在/出现/消失）",title:"存现句（全面）",explanation_zh:"表示什么地方存在、出现或消失了什么人或物。",explanation_en:"Indicates that someone or something exists, appears, or disappears in a certain place.",example_zh:"桌子上放着一本书。\n前面来了一个人。\n家里走了一位客人。",example_pinyin:"Zhuōzi sh\xe0ng f\xe0ngzhe y\xec běn shū.\nQi\xe1nmian l\xe1i le y\xed ge r\xe9n.\nJiā lǐ zǒu le y\xed w\xe8i k\xe8r\xe9n.",example_en:"A book is placed on the table.\nA person is coming from the front.\nA guest left the house.",usage_notes:"存现句：处所词+动词+人/物",category:"句型"},{id:"grammar-5-31",hsk_level:5,pattern:"主谓谓语句",title:"主谓谓语句",explanation_zh:"由主谓短语充当谓语的句子。",explanation_en:"A sentence where the predicate is a subject-predicate phrase.",example_zh:"他学习很努力。\n我头疼。\n这个菜味道不错。",example_pinyin:"Tā xu\xe9x\xed hěn nǔl\xec.\nWǒ t\xf3u t\xe9ng.\nZh\xe8ge c\xe0i w\xe8id\xe0o b\xf9cu\xf2.",example_en:"He studies very hard.\nI have a headache.\nThis dish tastes good.",usage_notes:"大主语是话题，小谓语对话题进行说明",category:"句型"},{id:"grammar-5-32",hsk_level:5,pattern:"双宾语句",title:"双宾语句（全面）",explanation_zh:"动词带两个宾语，一个指人，一个指物。",explanation_en:"A verb takes two objects, one referring to a person and one to a thing.",example_zh:"老师教我们汉语。\n他给我一本书。\n我问你一个问题。",example_pinyin:"Lǎoshī jiāo wǒmen h\xe0nyǔ.\nTā gěi wǒ y\xec běn shū.\nWǒ w\xe8n nǐ y\xed ge w\xe8nt\xed.",example_en:"The teacher teaches us Chinese.\nHe gives me a book.\nI ask you a question.",usage_notes:"近宾指人，远宾指物；常见动词：给、送、教、借、还、问、告诉等",category:"句型"},{id:"grammar-5-33",hsk_level:5,pattern:'"是……的"句（强调）',title:'"是……的"句（强调句型）',explanation_zh:"强调动作的时间、地点、方式、目的、对象等。",explanation_en:"Emphasizes the time, place, manner, purpose, object, etc. of an action.",example_zh:"我是昨天来的。\n他是坐飞机来的。\n是我帮他的。",example_pinyin:"Wǒ sh\xec zu\xf3tiān l\xe1i de.\nTā sh\xec zu\xf2 fēijī l\xe1i de.\nSh\xec wǒ bāng tā de.",example_en:"I came yesterday.\nHe came by plane.\nIt was I who helped him.",usage_notes:'强调的部分在"是"和"的"之间；动词后不能加"了"',category:"句型"},{id:"grammar-5-34",hsk_level:5,pattern:"连……都/也……",title:'"连……都/也……"（强调）',explanation_zh:'强调极端情况，含有"甚至"的意思。',explanation_en:'Emphasizes extreme situations, with the meaning of "even".',example_zh:"他连汉语都不会说。\n我连一个字都没写。\n连小孩都知道。",example_pinyin:"Tā li\xe1n h\xe0nyǔ dōu b\xfa hu\xec shuō.\nWǒ li\xe1n y\xed g\xe8 z\xec dōu m\xe9i xiě.\nLi\xe1n xiǎoh\xe1i dōu zhīd\xe0o.",example_en:"He cannot even speak Chinese.\nI did not write even a single word.\nEven children know it.",usage_notes:"连……都/也……：强调极端，出乎意料",category:"句型"},{id:"grammar-5-35",hsk_level:5,pattern:"疑问代词的任指/虚指/反问用法",title:"疑问代词的非疑问用法",explanation_zh:"疑问代词不表示疑问，而表示任指、虚指等。",explanation_en:"Interrogative pronouns do not express doubt, but express arbitrary reference, indefinite reference, etc.",example_zh:"谁想去谁去。\n我好像在哪儿见过他。\n谁知道他去哪儿了！",example_pinyin:"Sh\xe9i xiǎng q\xf9 sh\xe9i q\xf9.\nWǒ hǎoxi\xe0ng z\xe0i nǎr ji\xe0nguo tā.\nSh\xe9i zhīd\xe0o tā q\xf9 nǎr le!",example_en:"Whoever wants to go can go.\nI seem to have seen him somewhere.\nWho knows where he went!",usage_notes:"任指：任何；虚指：不确定的；反问：加强否定语气",category:"代词"},{id:"grammar-5-36",hsk_level:5,pattern:"每 / 各 / 某 / 另 / 其 / 别 / 本 / 该",title:"指示代词（扩展）",explanation_zh:"表示指示或代替人或事物的代词。",explanation_en:"Pronouns that indicate or replace people or things.",example_zh:"每个人都要努力。\n各班都有自己的特点。\n某天，他来到了北京。",example_pinyin:"Měi ge r\xe9n dōu y\xe0o nǔl\xec.\nG\xe8 bān dōu yǒu z\xecjǐ de t\xe8diǎn.\nMǒu tiān, tā l\xe1i d\xe0o le běijīng.",example_en:"Everyone must work hard.\nEach class has its own characteristics.\nOne day, he came to Beijing.",usage_notes:"每：全体中的任何一个；各：每个不同的；某：不确定的；另：另外的",category:"代词"},{id:"grammar-5-37",hsk_level:5,pattern:"的 / 地 / 得",title:'结构助词"的/地/得"',explanation_zh:"三个结构助词，分别用于定语、状语、补语。",explanation_en:"Three structural particles, used for attributive, adverbial, and complement respectively.",example_zh:"他是一个聪明的学生。\n他认真地学习。\n他学习学得很认真。",example_pinyin:"Tā sh\xec y\xed ge cōngm\xedng de xu\xe9shēng.\nTā r\xe8nzhēn de xu\xe9x\xed.\nTā xu\xe9x\xed xu\xe9 de hěn r\xe8nzhēn.",example_en:"He is a smart student.\nHe studies conscientiously.\nHe studies very conscientiously.",usage_notes:"的：定语标志；地：状语标志；得：补语标志",category:"助词"},{id:"grammar-5-38",hsk_level:5,pattern:"了 / 着 / 过",title:'动态助词"了/着/过"',explanation_zh:"表示动作的状态：完成、进行、经历。",explanation_en:"Indicates the state of an action: completion, progression, experience.",example_zh:"我吃了饭了。\n他看着书呢。\n我去过北京。",example_pinyin:"Wǒ chī le f\xe0n le.\nTā k\xe0nzhe shū ne.\nWǒ q\xf9gu\xf2 běijīng.",example_en:"I have eaten.\nHe is reading a book.\nI have been to Beijing.",usage_notes:"了：动作完成；着：动作进行/状态持续；过：过去的经历",category:"助词"},{id:"grammar-5-39",hsk_level:5,pattern:"语气助词（啊 / 呢 / 吧 / 嘛 / 呗 / 喽 / 罢了",title:"语气助词（扩展）",explanation_zh:"表示各种语气，放在句末。",explanation_en:"Express various moods, placed at the end of a sentence.",example_zh:"你好啊！\n他还没来呢。\n你走吧。",example_pinyin:"Nǐ hǎo a!\nTā h\xe1i m\xe9i l\xe1i ne.\nNǐ zǒu ba.",example_en:"Hello!\nHe has not come yet.\nYou go ahead.",usage_notes:"啊：感叹、舒缓；呢：持续、疑问；吧：商量、推测；嘛：显而易见",category:"助词"},{id:"grammar-5-40",hsk_level:5,pattern:"所 / 等 / 似的 / 一样 / 般",title:"其他助词",explanation_zh:"表示各种其他助词的用法。",explanation_en:"Usage of various other particles.",example_zh:"这是我所说的。\n桌子上有书、本子等。\n他像孩子似的。",example_pinyin:"Zh\xe8 sh\xec wǒ suǒ shuō de.\nZhuōzi sh\xe0ng yǒu shū、běnzi děng.\nTā xi\xe0ng h\xe1izi sh\xec de.",example_en:"This is what I said.\nThere are books, notebooks, etc. on the table.\nHe is like a child.",usage_notes:"所：书面语；等：列举未尽；似的/一样：比喻",category:"助词"},{id:"grammar-5-41",hsk_level:5,pattern:"在 / 从 / 向 / 往 / 朝 / 沿 / 顺",title:"处所/方向介词",explanation_zh:"表示动作的处所、方向的介词。",explanation_en:"Prepositions indicating location or direction of an action.",example_zh:"我在学校学习。\n他从中国来。\n向前走。",example_pinyin:"Wǒ z\xe0i xu\xe9xi\xe0o xu\xe9x\xed.\nTā c\xf3ng zhōnggu\xf3 l\xe1i.\nXi\xe0ng qi\xe1n zǒu.",example_en:"I study at school.\nHe comes from China.\nWalk forward.",usage_notes:"在：位置；从：起点；向/往/朝：方向；沿/顺：顺着",category:"介词"},{id:"grammar-5-42",hsk_level:5,pattern:"对 / 对于 / 关于 / 至于",title:"对象/范围介词",explanation_zh:"表示动作的对象或涉及的范围。",explanation_en:"Indicates the object or scope of an action.",example_zh:"他对我很好。\n对于这个问题，我有不同看法。\n关于中国文化，我很感兴趣。",example_pinyin:"Tā du\xec wǒ hěn hǎo.\nDu\xecy\xfa zh\xe8ge w\xe8nt\xed, wǒ yǒu b\xf9t\xf3ng k\xe0nfǎ.\nGuāny\xfa zhōnggu\xf3 w\xe9nhu\xe0, wǒ hěn gǎn x\xecngq\xf9.",example_en:"He is very good to me.\nRegarding this issue, I have different views.\nAbout Chinese culture, I am very interested.",usage_notes:"对：对象；对于：引进对象；关于：涉及范围；至于：另提一事",category:"介词"},{id:"grammar-5-43",hsk_level:5,pattern:"为 / 为了 / 给 / 替",title:"目的/对象介词",explanation_zh:"表示动作的目的或服务对象。",explanation_en:"Indicates the purpose or service object of an action.",example_zh:"为人民服务。\n为了健康，他每天锻炼。\n我给你买了一本书。",example_pinyin:"W\xe8i r\xe9nm\xedn f\xfaw\xf9.\nW\xe8ile ji\xe0nkāng, tā měitiān du\xe0nli\xe0n.\nWǒ gěi nǐ mǎi le y\xec běn shū.",example_en:"Serve the people.\nFor health, he exercises every day.\nI bought a book for you.",usage_notes:"为/为了：目的；给/替：服务对象、代替",category:"介词"},{id:"grammar-5-44",hsk_level:5,pattern:"比 / 跟 / 同 / 与",title:"比较介词",explanation_zh:"表示比较的对象。",explanation_en:"Indicates the object of comparison.",example_zh:"他比我高。\n这个跟那个一样。\n他同我一样大。",example_pinyin:"Tā bǐ wǒ gāo.\nZh\xe8ge gēn n\xe0ge y\xedy\xe0ng.\nTā t\xf3ng wǒ y\xedy\xe0ng d\xe0.",example_en:"He is taller than me.\nThis is the same as that.\nHe is the same age as me.",usage_notes:"比：比较差别；跟/同/与：比较异同",category:"介词"},{id:"grammar-5-45",hsk_level:5,pattern:"把 / 被 / 叫 / 让 / 给",title:"处置/被动介词",explanation_zh:"表示处置或被动。",explanation_en:"Indicates disposal or passive voice.",example_zh:"他把作业做完了。\n杯子被他打破了。\n杯子叫他打破了。",example_pinyin:"Tā bǎ zu\xf2y\xe8 zu\xf2w\xe1n le.\nBēizi b\xe8i tā dǎp\xf2 le.\nBēizi ji\xe0o tā dǎp\xf2 le.",example_en:"He finished the homework.\nThe cup was broken by him.\nThe cup was broken by him.",usage_notes:"把：处置；被/叫/让/给：被动",category:"介词"},{id:"grammar-5-46",hsk_level:5,pattern:"按照 / 根据 / 凭 / 靠",title:"依据介词",explanation_zh:"表示动作的依据、凭借。",explanation_en:"Indicates the basis or reliance of an action.",example_zh:"请按照规定做。\n根据调查，他是对的。\n他凭自己的努力成功了。",example_pinyin:"Qǐng \xe0nzh\xe0o guīd\xecng zu\xf2.\nGēnj\xf9 di\xe0och\xe1, tā sh\xec du\xec de.\nTā p\xedng z\xecjǐ de nǔl\xec ch\xe9nggōng le.",example_en:"Please do it according to the rules.\nAccording to the investigation, he is right.\nHe succeeded by his own efforts.",usage_notes:"按照/根据：依据；凭/靠：凭借",category:"介词"},{id:"grammar-5-47",hsk_level:5,pattern:"由于 / 因为",title:"原因介词",explanation_zh:"表示动作的原因。",explanation_en:"Indicates the cause of an action.",example_zh:"由于天气不好，飞机晚点了。\n因为生病，他没来。",example_pinyin:"Y\xf3uy\xfa tiānq\xec b\xf9 hǎo, fēijī wǎndiǎn le.\nYīnw\xe8i shēngb\xecng, tā m\xe9i l\xe1i.",example_en:"Due to bad weather, the plane was late.\nBecause of illness, he did not come.",usage_notes:"由于：较正式；因为：口语书面都用",category:"介词"},{id:"grammar-5-48",hsk_level:5,pattern:"除了……以外 / 除……之外",title:"排除介词",explanation_zh:"表示排除、不计算在内。",explanation_en:"Indicates exclusion, not counting.",example_zh:"除了汉语，我还学英语。\n除了我，大家都去了。\n除此以外，我什么都不知道。",example_pinyin:"Ch\xfale h\xe0nyǔ, wǒ h\xe1i xu\xe9 yīngyǔ.\nCh\xfale wǒ, d\xe0jiā dōu q\xf9 le.\nCh\xfa cǐ yǐw\xe0i, wǒ sh\xe9nme dōu b\xf9 zhīd\xe0o.",example_en:"Besides Chinese, I also study English.\nExcept for me, everyone went.\nBesides this, I know nothing.",usage_notes:"除了……还：追加；除了……都：排除",category:"介词"},{id:"grammar-5-49",hsk_level:5,pattern:"程度副词（很 / 太 / 非常 / 十分 / 极其 / 格外）",title:"程度副词",explanation_zh:"表示动作或性质的程度。",explanation_en:"Indicates the degree of an action or quality.",example_zh:"他很高。\n今天太热了。\n他非常努力。",example_pinyin:"Tā hěn gāo.\nJīntiān t\xe0i r\xe8 le.\nTā fēich\xe1ng nǔl\xec.",example_en:"He is very tall.\nToday is too hot.\nHe is extremely hardworking.",usage_notes:"很：一般程度；太：程度高、感叹；非常/十分/极其：程度很高",category:"副词"},{id:"grammar-5-50",hsk_level:5,pattern:"范围副词（都 / 全 / 皆 / 总共 / 一共 / 仅仅）",title:"范围副词",explanation_zh:"表示动作或事物的范围。",explanation_en:"Indicates the scope of an action or thing.",example_zh:"我们都去。\n他们全来了。\n我一共买了三本书。",example_pinyin:"Wǒmen dōu q\xf9.\nTāmen qu\xe1n l\xe1i le.\nWǒ y\xedg\xf2ng mǎi le sān běn shū.",example_en:"We are all going.\nThey all came.\nI bought a total of three books.",usage_notes:"都/全/皆：总括；总共/一共：总计；仅仅/只：限定范围小",category:"副词"},{id:"grammar-5-51",hsk_level:5,pattern:"时间副词（已经 / 曾经 / 刚刚 / 正 / 在 / 正在）",title:"时间副词",explanation_zh:"表示动作发生的时间。",explanation_en:"Indicates the time when an action occurs.",example_zh:"他已经来了。\n我曾经去过北京。\n他正在吃饭。",example_pinyin:"Tā yǐjīng l\xe1i le.\nWǒ c\xe9ngjīng q\xf9gu\xf2 běijīng.\nTā zh\xe8ngz\xe0i chī f\xe0n.",example_en:"He has already come.\nI have been to Beijing before.\nHe is eating.",usage_notes:"已经：完成；曾经：过去经历；刚刚：刚发生；正/在/正在：进行",category:"副词"},{id:"grammar-5-52",hsk_level:5,pattern:"频率副词（再 / 又 / 还 / 也 / 常常 / 往往 / 总是）",title:"频率副词",explanation_zh:"表示动作发生的频率。",explanation_en:"Indicates the frequency of an action.",example_zh:"请再说一遍。\n他昨天又来了。\n他常常来我家。",example_pinyin:"Qǐng z\xe0i shuō y\xed bi\xe0n.\nTā zu\xf3tiān y\xf2u l\xe1i le.\nTā ch\xe1ngch\xe1ng l\xe1i wǒ jiā.",example_en:"Please say it again.\nHe came again yesterday.\nHe often comes to my house.",usage_notes:"再：未发生的重复；又：已发生的重复；常常/往往：经常；总是：一直",category:"副词"},{id:"grammar-5-53",hsk_level:5,pattern:"语气副词（难道 / 究竟 / 偏偏 / 明明 / 果然 / 居然）",title:"语气副词",explanation_zh:"表示各种语气。",explanation_en:"Expresses various moods.",example_zh:"难道你不知道吗？\n你究竟去不去？\n他偏偏不来。",example_pinyin:"N\xe1nd\xe0o nǐ b\xf9 zhīd\xe0o ma?\nNǐ jiūj\xecng q\xf9 bu q\xf9?\nTā piānpiān b\xf9 l\xe1i.",example_en:"Don't you know?\nAre you going or not?\nHe just refuses to come.",usage_notes:"难道：反问；究竟：追究；偏偏：故意相反；果然：不出所料；居然：出乎意料",category:"副词"},{id:"grammar-5-54",hsk_level:5,pattern:"肯定/否定副词（必 / 必须 / 一定 / 未必 / 不必）",title:"肯定否定副词",explanation_zh:"表示肯定或否定的语气。",explanation_en:"Expresses affirmative or negative mood.",example_zh:"你必须来。\n他一定去。\n你不必担心。",example_pinyin:"Nǐ b\xecxū l\xe1i.\nTā y\xedd\xecng q\xf9.\nNǐ b\xf9b\xec dānxīn.",example_en:"You must come.\nHe will definitely go.\nYou don't have to worry.",usage_notes:"必/必须/一定：肯定；未必/不必：否定",category:"副词"},{id:"grammar-5-55",hsk_level:5,pattern:"情态动词（能 / 会 / 可以 / 可能 / 应该 / 必须）",title:"能愿动词（情态动词）",explanation_zh:"表示能力、可能性、必要性、意愿等。",explanation_en:"Expresses ability, possibility, necessity, willingness, etc.",example_zh:"我会说汉语。\n他能跑很快。\n你应该努力学习。",example_pinyin:"Wǒ hu\xec shuō h\xe0nyǔ.\nTā n\xe9ng pǎo hěn ku\xe0i.\nNǐ yīnggāi nǔl\xec xu\xe9x\xed.",example_en:"I can speak Chinese.\nHe can run very fast.\nYou should study hard.",usage_notes:"能/会/可以：能力、可能；应该/必须：必要性；要/想：意愿",category:"动词"},{id:"grammar-5-56",hsk_level:5,pattern:"离合动词",title:"离合动词",explanation_zh:"有些双音节动词可以拆开使用，中间插入其他成分。",explanation_en:"Some disyllabic verbs can be used separately, with other elements inserted in between.",example_zh:"我每天睡觉睡八个小时。\n他帮了我很大的忙。\n我们见过几次面。",example_pinyin:"Wǒ měitiān shu\xecji\xe0o shu\xec bā ge xiǎosh\xed.\nTā bāng le wǒ hěn d\xe0 de m\xe1ng.\nWǒmen ji\xe0n gu\xf2 jǐ c\xec mi\xe0n.",example_en:"I sleep eight hours every day.\nHe helped me a great deal.\nWe have met several times.",usage_notes:"常见离合词：睡觉、帮忙、见面、结婚、洗澡、散步、吵架等",category:"动词"},{id:"grammar-5-57",hsk_level:5,pattern:"动词重叠（AA / ABAB / AABB）",title:"动词重叠",explanation_zh:"动词重叠表示动作时间短、尝试、轻松等。",explanation_en:"Verb reduplication indicates short duration, attempt, casualness, etc.",example_zh:"你看看这本书。\n我们讨论讨论这个问题。\n大家都高高兴兴的。",example_pinyin:"Nǐ k\xe0nkan zh\xe8 běn shū.\nWǒmen tǎol\xf9n tǎol\xf9n zh\xe8ge w\xe8nt\xed.\nD\xe0jiā dōu gāogāo x\xecngx\xecng de.",example_en:"Take a look at this book.\nLet's discuss this problem.\nEveryone is happy.",usage_notes:"单音节：AA式；双音节：ABAB式；AABB式多为形容词",category:"动词"},{id:"grammar-5-58",hsk_level:5,pattern:"形容词重叠（AA / AABB / ABAB）",title:"形容词重叠",explanation_zh:"形容词重叠表示程度加深或状态生动。",explanation_en:"Adjective reduplication indicates deepened degree or vivid state.",example_zh:"大大的眼睛。\n干干净净的房间。\n雪白雪白的墙。",example_pinyin:"D\xe0d\xe0 de yǎnjing.\nGāngānj\xecngj\xecng de f\xe1ngjiān.\nXuěb\xe1i xuěb\xe1i de qi\xe1ng.",example_en:"Big eyes.\nA clean room.\nSnow-white walls.",usage_notes:"单音节：AA式；双音节：AABB式；状态形容词：ABAB式",category:"形容词"},{id:"grammar-5-59",hsk_level:5,pattern:"名量词 / 动量词 / 时量词 / 复合量词",title:"量词（扩展）",explanation_zh:"表示事物或动作的单位。",explanation_en:"Units of things or actions.",example_zh:"三个人、两本书、一杯茶。\n去一趟、看一遍、打一下。",example_pinyin:"Sān g\xe8 r\xe9n、liǎng běn shū、y\xec bēi ch\xe1.\nQ\xf9 y\xed t\xe0ng、k\xe0n y\xed bi\xe0n、dǎ y\xed xi\xe0.",example_en:"Three people, two books, a cup of tea.\nMake a trip, read once, hit once.",usage_notes:"名量词：事物单位；动量词：动作次数；时量词：时间单位",category:"量词"},{id:"grammar-5-60",hsk_level:5,pattern:"数量短语的句法功能",title:"数量短语的用法",explanation_zh:"数词+量词构成数量短语，可作定语、状语、补语等。",explanation_en:"Numeral + measure word form a quantity phrase, which can function as attributive, adverbial, complement, etc.",example_zh:"三本书都很好。\n他一次买了三本。\n他跑了三趟。",example_pinyin:"Sān běn shū dōu hěn hǎo.\nTā y\xed c\xec mǎi le sān běn.\nTā pǎo le sān t\xe0ng.",example_en:"All three books are very good.\nHe bought three at once.\nHe ran three trips.",usage_notes:"数量短语可作主语、定语、宾语、补语、状语等",category:"量词"},{id:"grammar-5-61",hsk_level:5,pattern:"一……就…… / 越……越……",title:'副词"一……就……/越……越……"',explanation_zh:"表示两个动作紧接或程度随动作加深。",explanation_en:"Indicates two actions in quick succession or degree deepening with action.",example_zh:"我一到就给你打电话。\n我越学越喜欢汉语。\n他越跑越快。",example_pinyin:"Wǒ y\xed d\xe0o ji\xf9 gěi nǐ dǎ di\xe0nhu\xe0.\nWǒ yu\xe8 xu\xe9 yu\xe8 xǐhuan h\xe0nyǔ.\nTā yu\xe8 pǎo yu\xe8 ku\xe0i.",example_en:"I will call you as soon as I arrive.\nThe more I study, the more I like Chinese.\nThe more he runs, the faster he gets.",usage_notes:"一……就……：紧接；越……越……：程度加深",category:"副词"},{id:"grammar-5-62",hsk_level:5,pattern:"才 / 就 / 都 / 也 / 还 / 又 / 再 / 还",title:"常用副词辨析",explanation_zh:"一些常用副词的用法辨析。",explanation_en:"Analysis of the usage of some common adverbs.",example_zh:"他八点就来了。\n他十点才来。\n我也要去。",example_pinyin:"Tā bā diǎn ji\xf9 l\xe1i le.\nTā sh\xed diǎn c\xe1i l\xe1i.\nWǒ yě y\xe0o q\xf9.",example_en:"He came as early as eight o'clock.\nHe came as late as ten o'clock.\nI am also going.",usage_notes:"就：早、快、多；才：晚、慢、少；也：同样；都：全部",category:"副词"},{id:"grammar-5-63",hsk_level:5,pattern:"再 / 又 / 还 / 也",title:'"再/又/还/也"辨析',explanation_zh:"都表示动作重复或继续，但含义不同。",explanation_en:"All indicate repetition or continuation of action, but with different meanings.",example_zh:"请再说一遍。\n他昨天又来了。\n他还没来。\n我也要去。",example_pinyin:"Qǐng z\xe0i shuō y\xed bi\xe0n.\nTā zu\xf3tiān y\xf2u l\xe1i le.\nTā h\xe1i m\xe9i l\xe1i.\nWǒ yě y\xe0o q\xf9.",example_en:"Please say it again.\nHe came again yesterday.\nHe has not come yet.\nI am also going.",usage_notes:"再：未发生；又：已发生；还：持续；也：同样",category:"副词"},{id:"grammar-5-64",hsk_level:5,pattern:"就 / 才",title:'"就/才"辨析',explanation_zh:'"就"和"才"都表示主观评价，但意义相反。',explanation_en:'Both "jiu" and "cai" express subjective evaluation, but with opposite meanings.',example_zh:"他八点就来了。\n他十点才来。\n我就要了三个。",example_pinyin:"Tā bā diǎn ji\xf9 l\xe1i le.\nTā sh\xed diǎn c\xe1i l\xe1i.\nWǒ ji\xf9 y\xe0o le sān g\xe8.",example_en:"He came as early as eight o'clock.\nHe came as late as ten o'clock.\nI only asked for three.",usage_notes:"就：早、快、多、容易；才：晚、慢、少、难",category:"副词"},{id:"grammar-5-65",hsk_level:5,pattern:"又……又…… / 既……又…… / 一边……一边……",title:"并列结构辨析",explanation_zh:"都表示两种情况同时存在，但用法不同。",explanation_en:"All indicate two situations existing simultaneously, but with different usages.",example_zh:"他又聪明又努力。\n他既聪明又努力。\n他一边吃饭一边看电视。",example_pinyin:"Tā y\xf2u cōngm\xedng y\xf2u nǔl\xec.\nTā j\xec cōngm\xedng y\xf2u nǔl\xec.\nTā y\xecbiān chī f\xe0n y\xecbiān k\xe0n di\xe0nsh\xec.",example_en:"He is both smart and hardworking.\nHe is both smart and hardworking.\nHe eats while watching TV.",usage_notes:"又……又……：两种性质；既……又……：两方面；一边……一边……：同时动作",category:"连词"},{id:"grammar-5-66",hsk_level:5,pattern:"因为 / 由于 / 既然",title:"原因连词辨析",explanation_zh:"都表示原因，但用法不同。",explanation_en:"All indicate cause, but with different usages.",example_zh:"因为下雨，所以我不去了。\n由于下雨，比赛取消了。\n既然下雨了，就别走了。",example_pinyin:"Yīnw\xe8i xi\xe0 yǔ, suǒyǐ wǒ b\xfa q\xf9 le.\nY\xf3uy\xfa xi\xe0 yǔ, bǐs\xe0i qǔxiāo le.\nJ\xecr\xe1n xi\xe0 yǔ le, ji\xf9 bi\xe9 zǒu le.",example_en:"Because it is raining, I am not going.\nDue to rain, the game was canceled.\nSince it is raining, don't leave.",usage_notes:"因为：说明原因；由于：较正式；既然：推论因果",category:"连词"},{id:"grammar-5-67",hsk_level:5,pattern:"虽然 / 尽管 / 固然",title:"转折连词辨析",explanation_zh:"都表示转折，但语气和用法不同。",explanation_en:"All indicate转折, but with different tones and usages.",example_zh:"虽然他很累，但是还在工作。\n尽管困难很多，我们也要坚持。\n这个办法固然好，但是太麻烦。",example_pinyin:"Suīr\xe1n tā hěn l\xe8i, d\xe0nsh\xec h\xe1i z\xe0i gōngzu\xf2.\nJǐnguǎn k\xf9nn\xe1n hěn duō, wǒmen yě y\xe0o jiānch\xed.\nZh\xe8ge b\xe0nfǎ g\xf9r\xe1n hǎo, d\xe0nsh\xec t\xe0i m\xe1fan.",example_en:"Although he is very tired, he is still working.\nDespite many difficulties, we must persevere.\nThis method is certainly good, but too troublesome.",usage_notes:"虽然：一般转折；尽管：让步转折；固然：先承认后转折",category:"连词"},{id:"grammar-5-68",hsk_level:5,pattern:"如果 / 要是 / 假如 / 倘若",title:"假设连词辨析",explanation_zh:"都表示假设，但语体色彩不同。",explanation_en:"All indicate hypothesis, but with different stylistic colors.",example_zh:"如果明天下雨，我就不去了。\n要是你有空，请来玩。\n假如有问题，可以问我。",example_pinyin:"R\xfaguǒ m\xedngtiān xi\xe0 yǔ, wǒ ji\xf9 b\xfa q\xf9 le.\nY\xe0oshi nǐ yǒu k\xf2ng, qǐng l\xe1i w\xe1n.\nJiǎr\xfa yǒu w\xe8nt\xed, kěyǐ w\xe8n wǒ.",example_en:"If it rains tomorrow, I will not go.\nIf you have time, please come visit.\nIf you have questions, you can ask me.",usage_notes:"如果：最常用；要是：口语化；假如/倘若：书面语",category:"连词"},{id:"grammar-5-69",hsk_level:5,pattern:"只要 / 只有 / 除非",title:"条件连词辨析",explanation_zh:"都表示条件，但含义不同。",explanation_en:"All indicate condition, but with different meanings.",example_zh:"只要努力，就能成功。\n只有努力，才能成功。\n除非你努力，否则不会成功。",example_pinyin:"Zhǐy\xe0o nǔl\xec, ji\xf9 n\xe9ng ch\xe9nggōng.\nZhǐyǒu nǔl\xec, c\xe1i n\xe9ng ch\xe9nggōng.\nCh\xfafēi nǐ nǔl\xec, fǒuz\xe9 b\xfa hu\xec ch\xe9nggōng.",example_en:"As long as you work hard, you can succeed.\nOnly by working hard can you succeed.\nUnless you work hard, you will not succeed.",usage_notes:"只要：充足条件；只有：必要条件；除非：唯一条件",category:"连词"},{id:"grammar-5-70",hsk_level:5,pattern:"不但 / 不仅 / 不光 / 不只",title:"递进连词辨析",explanation_zh:"都表示递进关系，但语体和用法略有不同。",explanation_en:"All indicate progressive relationship, but with slight differences in style and usage.",example_zh:"他不但会说英语，而且会说法语。\n不仅我去，大家都去。\n不光是我，他也去。",example_pinyin:"Tā b\xf9d\xe0n hu\xec shuō yīngyǔ, \xe9rqiě hu\xec shuō fǎyǔ.\nB\xf9jǐn wǒ q\xf9, d\xe0jiā dōu q\xf9.\nB\xf9guāng sh\xec wǒ, tā yě q\xf9.",example_en:"He can not only speak English, but also French.\nNot only I am going, everyone is going.\nNot just me, he is also going.",usage_notes:"不但：最常用；不仅：书面；不光/不只：口语化",category:"连词"},{id:"grammar-6-1",hsk_level:6,pattern:"A 比 B + 还 + Adj",title:'比较句"还"（夸张）',explanation_zh:'"还"在比较句中表示程度加深，带有夸张语气，表示比预想的更甚。',explanation_en:'"Hai" in comparative sentences indicates deepened degree with exaggerated tone, meaning even more than expected.',example_zh:"他比我还高。\n这个比那个还好。\n你比他还努力。",example_pinyin:"Tā bǐ wǒ h\xe1i gāo.\nZh\xe8ge bǐ n\xe0ge h\xe1i hǎo.\nNǐ bǐ tā h\xe1i nǔl\xec.",example_en:"He is even taller than me.\nThis is even better than that.\nYou are even harder working than him.",usage_notes:"还：表示程度超出预期，带有夸张语气",category:"比较"},{id:"grammar-6-2",hsk_level:6,pattern:"A 比 B + 都 + Adj",title:'比较句"都"',explanation_zh:'"都"在比较句中强调程度，表示A已经达到甚至超过B的程度。',explanation_en:'"Dou" in comparative sentences emphasizes degree, indicating that A has reached or even exceeded B\'s degree.',example_zh:"他比我都高。\n你比他都胖。\n这个比那个都贵。",example_pinyin:"Tā bǐ wǒ dōu gāo.\nNǐ bǐ tā dōu p\xe0ng.\nZh\xe8ge bǐ n\xe0ge dōu gu\xec.",example_en:"He is even taller than me.\nYou are even fatter than him.\nThis is even more expensive than that.",usage_notes:"都：强调程度已达到某种标准，常带有惊讶语气",category:"比较"},{id:"grammar-6-3",hsk_level:6,pattern:"与其说……不如说……",title:'选择复句"与其说……不如说……"',explanation_zh:"表示对事物的判断，认为后一种说法更准确、更恰当。",explanation_en:"Expresses judgment about something, considering the latter statement more accurate and appropriate.",example_zh:"与其说他聪明，不如说他努力。\n与其说这是困难，不如说这是挑战。\n与其说他来帮忙，不如说他来看热闹。",example_pinyin:"Yǔq\xed shuō tā cōngm\xedng, b\xf9r\xfa shuō tā nǔl\xec.\nYǔq\xed shuō zh\xe8 sh\xec k\xf9nn\xe1n, b\xf9r\xfa shuō zh\xe8 sh\xec tiǎozh\xe0n.\nYǔq\xed shuō tā l\xe1i bāngm\xe1ng, b\xf9r\xfa shuō tā l\xe1i k\xe0n r\xe8n\xe0o.",example_en:"Rather than saying he is smart, it is better to say he is hardworking.\nRather than saying this is a difficulty, it is better to say it is a challenge.\nRather than saying he came to help, it is better to say he came to watch the excitement.",usage_notes:"与其说……不如说……：表示判断，选择更恰当的说法",category:"连词"},{id:"grammar-6-4",hsk_level:6,pattern:"宁肯/宁愿……也不/也要……",title:'选择复句"宁肯/宁愿……"',explanation_zh:"表示经过比较后做出选择，强调主观意愿。",explanation_en:"Indicates making a choice after comparison, emphasizing subjective will.",example_zh:"我宁肯饿死，也不接受他的施舍。\n他宁愿自己受苦，也不让孩子受累。\n我宁肯多花点钱，也要买个好的。",example_pinyin:"Wǒ n\xecngkěn \xe8 sǐ, yě b\xf9 jiēsh\xf2u tā de shīshě.\nTā n\xecngyu\xe0n z\xecjǐ sh\xf2u kǔ, yě b\xf9 r\xe0ng h\xe1izi sh\xf2u l\xe8i.\nWǒ n\xecngkěn duō huā diǎn qi\xe1n, yě y\xe0o mǎi ge hǎo de.",example_en:"I would rather starve than accept his charity.\nHe would rather suffer himself than let the child suffer.\nI would rather spend a bit more money to buy a good one.",usage_notes:'宁肯/宁愿：强调主观意愿上的选择，比"宁可"语气更重',category:"连词"},{id:"grammar-6-5",hsk_level:6,pattern:"别说/不要说……就是/即使……也……",title:'递进复句"别说……就是……也……"',explanation_zh:'先贬低或排除一种情况，然后用"就是"引出更甚的情况，表示进一步的强调。',explanation_en:'First belittle or exclude one case, then use "jiushi" to introduce an even more extreme case, indicating further emphasis.',example_zh:"别说你了，就是我也不知道。\n别说一个人，就是十个人也搬不动。\n别说是中文，就是英文他也看不懂。",example_pinyin:"Bi\xe9 shuō nǐ le, ji\xf9sh\xec wǒ yě b\xf9 zhīd\xe0o.\nBi\xe9 shuō y\xed ge r\xe9n, ji\xf9sh\xec sh\xed ge r\xe9n yě bān bu d\xf2ng.\nBi\xe9 shuō sh\xec zhōngw\xe9n, ji\xf9sh\xec yīngw\xe9n tā yě k\xe0n bu dǒng.",example_en:"Let alone you, even I do not know.\nLet alone one person, even ten people cannot move it.\nLet alone Chinese, even English he cannot understand.",usage_notes:"别说……就是……也……：表示递进，前者当然如此，后者更不用说",category:"连词"},{id:"grammar-6-6",hsk_level:6,pattern:"尚且……何况/更不用说/遑论……",title:'递进复句"尚且……何况……"',explanation_zh:"用反问语气表示递进，前一句提出程度更甚的事例，后一句更进一层。",explanation_en:"Expresses progression with rhetorical tone, the first sentence presents a more extreme case, the second sentence goes further.",example_zh:"这么难的题，大人尚且不会，何况孩子呢？\n他尚且做不到，更不用说我了。\n平时他都忙，遑论过年的时候呢？",example_pinyin:"Zh\xe8me n\xe1n de t\xed, d\xe0r\xe9n sh\xe0ngqiě b\xfa hu\xec, h\xe9ku\xe0ng h\xe1izi ne?\nTā sh\xe0ngqiě zu\xf2 bu d\xe0o, g\xe8ng b\xfay\xf2ng shuō wǒ le.\nP\xedngsh\xed tā dōu m\xe1ng, hu\xe1ngl\xf9n gu\xf2ni\xe1n de sh\xedhou ne?",example_en:"Such a difficult problem, even adults cannot do it, let alone children?\nEven he cannot do it, not to mention me.\nHe is busy even on ordinary days, let alone during the New Year?",usage_notes:"尚且：提出程度更甚的事例作为衬托；何况/更不用说：用反问语气表示更进一层",category:"连词"},{id:"grammar-6-7",hsk_level:6,pattern:"不但不/没……反倒/反而……",title:'递进复句"不但不……反而……"',explanation_zh:"前一分句否定，后一分句从相反方向向更深处推进。",explanation_en:"The first clause is negative, the second clause pushes deeper from the opposite direction.",example_zh:"他不但不生气，反倒很高兴。\n吃了药不但没好，反而更重了。\n他不但不感谢，反而抱怨起来。",example_pinyin:"Tā b\xf9d\xe0n b\xf9 shēngq\xec, fǎnd\xe0o hěn gāox\xecng.\nChī le y\xe0o b\xf9d\xe0n m\xe9i hǎo, fǎn'\xe9r g\xe8ng zh\xf2ng le.\nTā b\xf9d\xe0n b\xf9 gǎnxi\xe8, fǎn'\xe9r b\xe0oyu\xe0n qǐl\xe1i.",example_en:"Not only is he not angry, but on the contrary he is very happy.\nAfter taking medicine, not only did it not get better, but it got worse.\nNot only is he not grateful, but on the contrary he started complaining.",usage_notes:"不但不/没……反倒/反而……：表示反向递进",category:"连词"},{id:"grammar-6-8",hsk_level:6,pattern:"虽然……但是…… / 尽管……但是…… / 固然……但是……",title:"转折复句辨析",explanation_zh:"都表示转折关系，但语气和侧重点不同。",explanation_en:"All indicate转折 relationship, but with different tones and focuses.",example_zh:"虽然他很累，但是还在工作。\n尽管困难重重，我们也要坚持。\n这个办法固然好，但是太麻烦。",example_pinyin:"Suīr\xe1n tā hěn l\xe8i, d\xe0nsh\xec h\xe1i z\xe0i gōngzu\xf2.\nJǐnguǎn k\xf9nn\xe1n ch\xf3ngch\xf3ng, wǒmen yě y\xe0o jiānch\xed.\nZh\xe8ge b\xe0nfǎ g\xf9r\xe1n hǎo, d\xe0nsh\xec t\xe0i m\xe1fan.",example_en:"Although he is very tired, he is still working.\nDespite many difficulties, we must persevere.\nThis method is certainly good, but too troublesome.",usage_notes:"虽然：一般转折；尽管：让步语气更重；固然：先承认后转折",category:"连词"},{id:"grammar-6-9",hsk_level:6,pattern:"然而 / 然则 / 不过 / 只是",title:"转折连词辨析",explanation_zh:"都表示转折，但轻重和语体不同。",explanation_en:"All indicate转折, but with different weight and style.",example_zh:"他虽然年轻，然而很有经验。\n这办法好，不过太麻烦。\n他来了，只是晚了一点。",example_pinyin:"Tā suīr\xe1n ni\xe1nqīng, r\xe1n'\xe9r hěn yǒu jīngy\xe0n.\nZh\xe8 b\xe0nfǎ hǎo, b\xf9gu\xf2 t\xe0i m\xe1fan.\nTā l\xe1i le, zhǐsh\xec wǎn le y\xecdiǎn.",example_en:"Although he is young, however he is very experienced.\nThis method is good, but it is too troublesome.\nHe came, just a little late.",usage_notes:"然而：书面语，转折较重；不过：口语，转折较轻；只是：补充修正",category:"连词"},{id:"grammar-6-10",hsk_level:6,pattern:"既然/既是……就/那么……",title:"推论因果复句",explanation_zh:"根据已经存在的事实推出结论。",explanation_en:"Draw conclusions based on already existing facts.",example_zh:"既然你知道错了，就应该改正。\n既是你不愿意，那就算了。\n既然答应了，就要做到。",example_pinyin:"J\xecr\xe1n nǐ zhīd\xe0o cu\xf2 le, ji\xf9 yīnggāi gǎizh\xe8ng.\nJ\xecsh\xec nǐ b\xf9 yu\xe0ny\xec, n\xe0 ji\xf9 su\xe0n le.\nJ\xecr\xe1n dāying le, ji\xf9 y\xe0o zu\xf2d\xe0o.",example_en:"Since you know you are wrong, you should correct it.\nSince you are not willing, then forget it.\nSince you promised, you must keep your word.",usage_notes:"既然/既是：表示推论的依据，多用于口语",category:"连词"},{id:"grammar-6-11",hsk_level:6,pattern:"因此 / 因而 / 所以 / 于是 / 从而",title:"结果连词辨析",explanation_zh:"都表示因果关系中的结果，但用法不同。",explanation_en:"All indicate the result in a causal relationship, but with different usages.",example_zh:"他努力学习，因此成绩很好。\n他生病了，因而没来上课。\n他努力了，所以成功了。",example_pinyin:"Tā nǔl\xec xu\xe9x\xed, yīncǐ ch\xe9ngj\xec hěn hǎo.\nTā shēngb\xecng le, yīn'\xe9r m\xe9i l\xe1i sh\xe0ng k\xe8.\nTā nǔl\xec le, suǒyǐ ch\xe9nggōng le.",example_en:"He studies hard, therefore his grades are very good.\nHe was sick, thus he did not come to class.\nHe worked hard, so he succeeded.",usage_notes:"因此：最常用；因而：书面；所以：最口语；于是：承接；从而：进而",category:"连词"},{id:"grammar-6-12",hsk_level:6,pattern:"即使/即便/纵然/纵使……也……",title:"假设让步复句",explanation_zh:"先退一步承认假设，然后说出结果仍然不变。",explanation_en:"Take a step back to acknowledge the hypothesis, then state that the result remains unchanged.",example_zh:"即使下雨，我也去。\n纵然困难再大，我们也要完成。\n即便你不说，我也知道。",example_pinyin:"J\xedshǐ xi\xe0 yǔ, wǒ yě q\xf9.\nZ\xf2ngr\xe1n k\xf9nn\xe1n z\xe0i d\xe0, wǒmen yě y\xe0o w\xe1nch\xe9ng.\nJ\xedbi\xe0n nǐ b\xf9 shuō, wǒ yě zhīd\xe0o.",example_en:"Even if it rains, I will go.\nEven if the difficulty is great, we must complete it.\nEven if you don't say it, I know.",usage_notes:"即使：最常用；即便：较正式；纵然/纵使：书面语，语气最重",category:"连词"},{id:"grammar-6-13",hsk_level:6,pattern:"万一/一旦/倘使……就/则……",title:"假设连词辨析",explanation_zh:"都表示假设，但语体和可能性不同。",explanation_en:"All indicate hypothesis, but with different styles and possibilities.",example_zh:"万一下雨怎么办？\n一旦决定了，就不能改变。\n倘使有问题，请随时联系。",example_pinyin:"W\xe0nyī xi\xe0 yǔ zěnme b\xe0n?\nYīd\xe0n ju\xe9d\xecng le, ji\xf9 b\xf9 n\xe9ng gǎibi\xe0n.\nTǎngshǐ yǒu w\xe8nt\xed, qǐng su\xedsh\xed li\xe1nx\xec.",example_en:"What if it rains?\nOnce decided, it cannot be changed.\nShould there be any questions, please feel free to contact.",usage_notes:'万一：可能性小；一旦：表示"要是有一天"；倘使：书面语',category:"连词"},{id:"grammar-6-14",hsk_level:6,pattern:"只要……就…… / 只有……才…… / 除非……才/否则……",title:"条件复句辨析",explanation_zh:"表示不同类型的条件关系。",explanation_en:"Indicates different types of conditional relationships.",example_zh:"只要努力，就能成功。\n只有努力，才能成功。\n除非努力，否则不会成功。",example_pinyin:"Zhǐy\xe0o nǔl\xec, ji\xf9 n\xe9ng ch\xe9nggōng.\nZhǐyǒu nǔl\xec, c\xe1i n\xe9ng ch\xe9nggōng.\nCh\xfafēi nǔl\xec, fǒuz\xe9 b\xfa hu\xec ch\xe9nggōng.",example_en:"As long as you work hard, you can succeed.\nOnly by working hard can you succeed.\nUnless you work hard, you will not succeed.",usage_notes:"只要：充足条件；只有：必要条件；除非：唯一条件",category:"连词"},{id:"grammar-6-15",hsk_level:6,pattern:"无论/不论/不管/任凭……都/也……",title:"无条件复句辨析",explanation_zh:"表示在任何条件下结果都一样。",explanation_en:"Indicates that the result is the same under any conditions.",example_zh:"无论多困难，都要坚持。\n不论是谁，都要遵守规定。\n任凭他怎么说，我都不信。",example_pinyin:"W\xfal\xf9n duō k\xf9nn\xe1n, dōu y\xe0o jiānch\xed.\nB\xf9l\xf9n sh\xec shu\xed, dōu y\xe0o zūnshǒu guīd\xecng.\nR\xe8np\xedng tā zěnme shuō, wǒ dōu b\xf9 x\xecn.",example_en:"No matter how difficult, we must persevere.\nNo matter who it is, they must follow the rules.\nNo matter what he says, I don't believe it.",usage_notes:"无论/不论：较正式；不管：口语化；任凭：书面语，语气重",category:"连词"},{id:"grammar-6-16",hsk_level:6,pattern:"以便 / 以免 / 省得 / 为的是",title:"目的复句辨析",explanation_zh:"表示动作的目的。",explanation_en:"Indicates the purpose of an action.",example_zh:"请早点来，以便有时间准备。\n请小声点，以免吵醒孩子。\n快走吧，省得迟到。",example_pinyin:"Qǐng zǎo diǎn l\xe1i, yǐbi\xe0n yǒu sh\xedjiān zhǔnb\xe8i.\nQǐng xiǎo shēng diǎn, yǐmiǎn chǎoxǐng h\xe1izi.\nKu\xe0i zǒu ba, shěngde ch\xedd\xe0o.",example_en:"Please come earlier so that there is time to prepare.\nPlease keep your voice down so as not to wake the child.\nLet's go quickly, to avoid being late.",usage_notes:"以便/为的是：好的目的；以免/省得：避免不好的结果",category:"连词"},{id:"grammar-6-17",hsk_level:6,pattern:"首先 / 其次 / 再次 / 最后",title:"承接复句（顺序）",explanation_zh:"表示事情发展的先后顺序。",explanation_en:"Indicates the sequential order of event development.",example_zh:"首先，我们要明确目标。\n其次，要制定计划。\n最后，要付诸实施。",example_pinyin:"Shǒuxiān, wǒmen y\xe0o m\xedngqu\xe8 m\xf9biāo.\nQ\xedc\xec, y\xe0o zh\xecd\xecng j\xechu\xe0.\nZu\xech\xf2u, y\xe0o f\xf9zhū sh\xedshī.",example_en:"First, we must clarify our goals.\nSecond, we must make a plan.\nFinally, we must put it into practice.",usage_notes:"首先/其次/再次/最后：表示顺序，常用于议论文或说明文中",category:"连词"},{id:"grammar-6-18",hsk_level:6,pattern:"一方面……另一方面…… / 一则……二则……",title:"并列复句",explanation_zh:"表示两个方面并列存在。",explanation_en:"Indicates two aspects existing side by side.",example_zh:"一方面要努力学习，另一方面也要注意身体。\n一则要注意安全，二则要提高效率。",example_pinyin:"Y\xec fāngmi\xe0n y\xe0o nǔl\xec xu\xe9x\xed, l\xecng y\xec fāngmi\xe0n yě y\xe0o zh\xf9y\xec shēntǐ.\nYī z\xe9 y\xe0o zh\xf9y\xec ānqu\xe1n, \xe8r z\xe9 y\xe0o t\xedgāo xi\xe0olǜ.",example_en:"On one hand we must study hard, on the other hand we must also pay attention to health.\nFor one thing we must pay attention to safety, for another we must improve efficiency.",usage_notes:"一方面……另一方面……：并列两方面；一则……二则……：两个原因或理由",category:"连词"},{id:"grammar-6-19",hsk_level:6,pattern:"V + 得 + 情态/程度补语（扩展）",title:"情态/程度补语（高级）",explanation_zh:"补语表示动作的状态、程度，形式更加丰富多样。",explanation_en:"Complements indicate the state and degree of actions, with richer and more diverse forms.",example_zh:"他说得大家都笑了。\n我饿得前胸贴后背。\n他跑得气喘吁吁。",example_pinyin:"Tā shuō de d\xe0jiā dōu xi\xe0o le.\nWǒ \xe8 de qi\xe1nxiōng tiē h\xf2ub\xe8i.\nTā pǎo de q\xecchuǎnxūxū.",example_en:"He spoke until everyone laughed.\nI am so hungry my front is touching my back.\nHe ran until he was panting heavily.",usage_notes:"情态补语可以是短语、句子、成语等，表示动作的状态或结果",category:"补语"},{id:"grammar-6-20",hsk_level:6,pattern:"V + 得 + 个 + 正着 / 不亦乐乎 / 痛快",title:'"个"字补语',explanation_zh:'在动词后用"个"连接补语，表示程度高或达到饱和状态。',explanation_en:'Use "ge" after a verb to connect a complement, indicating high degree or reaching a saturated state.',example_zh:"今天我们玩了个痛快。\n他把我骂了个狗血喷头。\n大家吃了个不亦乐乎。",example_pinyin:"Jīntiān wǒmen w\xe1n le ge t\xf2ngku\xe0i.\nTā bǎ wǒ m\xe0 le ge gǒuxu\xe8pēnt\xf3u.\nD\xe0jiā chī le ge b\xf9y\xecl\xe8hū.",example_en:"Today we had a great time playing.\nHe scolded me severely.\nEveryone ate to their heart's content.",usage_notes:"V+个+补语：表示程度高、尽兴、彻底",category:"补语"},{id:"grammar-6-21",hsk_level:6,pattern:"V + 结果补语（死/坏/透/烂/遍/满）",title:"结果补语（扩展）",explanation_zh:"更多的结果补语，表示各种不同的结果。",explanation_en:"More resultative complements, indicating various results.",example_zh:"我饿死了。\n他把我气坏了。\n这个水果烂透了。",example_pinyin:"Wǒ \xe8 sǐ le.\nTā bǎ wǒ q\xec hu\xe0i le.\nZh\xe8ge shuǐguǒ l\xe0n t\xf2u le.",example_en:"I am starving.\nHe made me so angry.\nThis fruit is completely rotten.",usage_notes:"死/坏：程度极深；透：彻底；遍：到处；满：充满",category:"补语"},{id:"grammar-6-22",hsk_level:6,pattern:"V + 趋向补语（上/下/进/出/回/过/起/开 + 来/去）",title:"复合趋向补语（全面）",explanation_zh:"由两个趋向动词组成的复合趋向补语及其引申义。",explanation_en:"Compound directional complements composed of two directional verbs and their extended meanings.",example_zh:"他走进来了。\n他跑出去了。\n天气热起来了。",example_pinyin:"Tā zǒu j\xecnl\xe1i le.\nTā pǎo chūq\xf9 le.\nTiānq\xec r\xe8 qǐl\xe1i le.",example_en:"He walked in.\nHe ran out.\nThe weather is getting hot.",usage_notes:"复合趋向补语：简单趋向补语+来/去；有丰富的引申义",category:"补语"},{id:"grammar-6-23",hsk_level:6,pattern:"趋向补语的引申义（起来/下去/出来/过来/过去/开来）",title:"趋向补语引申义（全面）",explanation_zh:"趋向补语除方向外的各种抽象引申义。",explanation_en:"Various abstract extended meanings of directional complements besides direction.",example_zh:"他笑起来了。\n坚持下去就是胜利。\n他终于醒过来了。",example_pinyin:"Tā xi\xe0o qǐl\xe1i le.\nJiānch\xed xi\xe0q\xf9 ji\xf9 sh\xec sh\xe8ngl\xec.\nTā zhōngy\xfa xǐng gu\xf2l\xe1i le.",example_en:"He started laughing.\nPersisting means victory.\nHe finally woke up.",usage_notes:"起来：开始、兴起；下去：继续；出来：产生、显露；过来：恢复；过去：度过；开来：展开",category:"补语"},{id:"grammar-6-24",hsk_level:6,pattern:"可能补语的各种形式",title:"可能补语（全面）",explanation_zh:'表示动作能否实现，包括结果类、趋向类、"得了/不了"、"动得/不动"等。',explanation_en:'Indicates whether an action can be realized, including result type, directional type, "de liao/bu liao", "dong de/bu dong", etc.',example_zh:"这个题我做得对。\n太高了，我爬不上去。\n这么多，我吃不了。",example_pinyin:"Zh\xe8ge t\xed wǒ zu\xf2 de du\xec.\nT\xe0i gāo le, wǒ p\xe1 bu sh\xe0ngq\xf9.\nZh\xe8me duō, wǒ chī bu liǎo.",example_en:"I can solve this problem correctly.\nIt is too high, I cannot climb up.\nSo much, I cannot finish it.",usage_notes:"可能补语：表示主客观条件是否允许实现某种结果",category:"补语"},{id:"grammar-6-25",hsk_level:6,pattern:"数量补语（时量/动量/差量）",title:"数量补语（全面）",explanation_zh:"表示动作的时间长度、次数或数量差别。",explanation_en:"Indicates the duration, frequency, or quantity difference of an action.",example_zh:"我学了三年汉语。\n这个电影我看过三次。\n他比我高五厘米。",example_pinyin:"Wǒ xu\xe9 le sān ni\xe1n h\xe0nyǔ.\nZh\xe8ge di\xe0nyǐng wǒ k\xe0ngu\xf2 sān c\xec.\nTā bǐ wǒ gāo wǔ l\xedmǐ.",example_en:"I studied Chinese for three years.\nI have seen this movie three times.\nHe is five centimeters taller than me.",usage_notes:"时量：时间长度；动量：次数；差量：比较的差别",category:"补语"},{id:"grammar-6-26",hsk_level:6,pattern:'"把"字句的各种形式',title:'"把"字句（全面）',explanation_zh:'"把"字句的各种结构和用法。',explanation_en:'Various structures and usages of "ba" sentences.',example_zh:"他把作业做完了。\n把书拿过来。\n他把我气得说不出话。",example_pinyin:"Tā bǎ zu\xf2y\xe8 zu\xf2w\xe1n le.\nBǎ shū n\xe1 gu\xf2l\xe1i.\nTā bǎ wǒ q\xec de shuō bu chū hu\xe0.",example_en:"He finished the homework.\nBring the book over.\nHe made me so angry I could not speak.",usage_notes:"把字句结构：S+把+O+V+其他成分；表示处置、影响",category:"把字句"},{id:"grammar-6-27",hsk_level:6,pattern:'"把"字句的给/个/成/作',title:'"把"字句的特殊形式',explanation_zh:'"把"字句的一些特殊结构。',explanation_en:'Some special structures of "ba" sentences.',example_zh:"他把衣服给洗干净了。\n把他骂了个狗血喷头。\n把他当成朋友。",example_pinyin:"Tā bǎ yīfu gěi xǐ gānj\xecng le.\nBǎ tā m\xe0 le ge gǒuxu\xe8pēnt\xf3u.\nBǎ tā d\xe0ngch\xe9ng p\xe9ngyou.",example_en:"He washed the clothes clean.\nScolded him severely.\nRegard him as a friend.",usage_notes:"给：加强语气；个：程度高；成/作：当作、作为",category:"把字句"},{id:"grammar-6-28",hsk_level:6,pattern:"被动句的各种形式（被/叫/让/给/为……所）",title:"被动句（全面）",explanation_zh:"各种被动句的形式和用法。",explanation_en:"Various forms and usages of passive sentences.",example_zh:"杯子被他打破了。\n杯子叫他打破了。\n他的为人所大家所佩服。",example_pinyin:"Bēizi b\xe8i tā dǎp\xf2 le.\nBēizi ji\xe0o tā dǎp\xf2 le.\nTā de w\xe9ir\xe9n w\xe9i d\xe0jiā suǒ p\xe8if\xfa.",example_en:"The cup was broken by him.\nThe cup was broken by him.\nHis character is admired by everyone.",usage_notes:"被：通用；叫/让：口语；给：口语加强；为……所：书面语",category:"被动"},{id:"grammar-6-29",hsk_level:6,pattern:"兼语句的各种类型",title:"兼语句（全面）",explanation_zh:"各种类型的兼语句，包括使令、爱恨、称呼、推选等。",explanation_en:"Various types of pivotal sentences, including causative, love-hate, naming, election, etc.",example_zh:"老师让我们做作业。\n大家选他当班长。\n他怪我没告诉他。",example_pinyin:"Lǎoshī r\xe0ng wǒmen zu\xf2 zu\xf2y\xe8.\nD\xe0jiā xuǎn tā dāng bānzhǎng.\nTā gu\xe0i wǒ m\xe9i g\xe0osu tā.",example_en:"The teacher asks us to do homework.\nEveryone elected him class monitor.\nHe blames me for not telling him.",usage_notes:"兼语句：第一个动词的宾语兼作第二个动词的主语",category:"句型"},{id:"grammar-6-30",hsk_level:6,pattern:"连动句的各种类型",title:"连动句（全面）",explanation_zh:"各种类型的连动句，包括先后、方式目的、伴随等。",explanation_en:"Various types of serial verb sentences, including sequential, manner-purpose, accompanying, etc.",example_zh:"我去学校上课。\n他用左手写字。\n他站着说话。",example_pinyin:"Wǒ q\xf9 xu\xe9xi\xe0o sh\xe0ng k\xe8.\nTā y\xf2ng zuǒshǒu xiě z\xec.\nTā zh\xe0nzhe shuō hu\xe0.",example_en:"I go to school to attend class.\nHe writes with his left hand.\nHe speaks while standing.",usage_notes:"连动句：一个主语带两个或以上的动词短语",category:"句型"},{id:"grammar-6-31",hsk_level:6,pattern:"双宾语句的各种类型",title:"双宾语句（全面）",explanation_zh:"各种类型的双宾语句，包括给予、告知、称呼等。",explanation_en:"Various types of double-object sentences, including giving, informing, naming, etc.",example_zh:"他给我一本书。\n老师教我们汉语。\n大家叫他老王。",example_pinyin:"Tā gěi wǒ y\xec běn shū.\nLǎoshī jiāo wǒmen h\xe0nyǔ.\nD\xe0jiā ji\xe0o tā lǎo w\xe1ng.",example_en:"He gives me a book.\nThe teacher teaches us Chinese.\nEveryone calls him Old Wang.",usage_notes:"双宾语：近宾指人，远宾指物；常见动词：给、送、教、问、告诉、叫等",category:"句型"},{id:"grammar-6-32",hsk_level:6,pattern:"存现句的各种类型",title:"存现句（全面）",explanation_zh:"表示存在、出现、消失的句子。",explanation_en:"Sentences expressing existence, appearance, disappearance.",example_zh:"桌子上放着一本书。\n前面来了一个人。\n家里走了一位客人。",example_pinyin:"Zhuōzi sh\xe0ng f\xe0ngzhe y\xec běn shū.\nQi\xe1nmian l\xe1i le y\xed ge r\xe9n.\nJiā lǐ zǒu le y\xed w\xe8i k\xe8r\xe9n.",example_en:"A book is placed on the table.\nA person is coming from the front.\nA guest left the house.",usage_notes:"存现句：处所词+动词+人/物",category:"句型"},{id:"grammar-6-33",hsk_level:6,pattern:"主谓谓语句的各种类型",title:"主谓谓语句（全面）",explanation_zh:"各种类型的主谓谓语句。",explanation_en:"Various types of subject-predicate predicate sentences.",example_zh:"他学习很努力。\n我头疼。\n这个菜味道不错。",example_pinyin:"Tā xu\xe9x\xed hěn nǔl\xec.\nWǒ t\xf3u t\xe9ng.\nZh\xe8ge c\xe0i w\xe8id\xe0o b\xf9cu\xf2.",example_en:"He studies very hard.\nI have a headache.\nThis dish tastes good.",usage_notes:"主谓谓语句：大主语+小主语+小谓语",category:"句型"},{id:"grammar-6-34",hsk_level:6,pattern:'"是……的"句的各种用法',title:'"是……的"句（全面）',explanation_zh:"强调动作的时间、地点、方式、目的、对象、施事等。",explanation_en:"Emphasizes the time, place, manner, purpose, object, agent, etc. of an action.",example_zh:"我是昨天来的。\n他是坐飞机来的。\n是我帮他的。",example_pinyin:"Wǒ sh\xec zu\xf3tiān l\xe1i de.\nTā sh\xec zu\xf2 fēijī l\xe1i de.\nSh\xec wǒ bāng tā de.",example_en:"I came yesterday.\nHe came by plane.\nIt was I who helped him.",usage_notes:'是……的：强调已发生动作的某个方面；动词后不加"了"',category:"句型"},{id:"grammar-6-35",hsk_level:6,pattern:'"连……都/也……" / "甚至……都/也……"',title:'强调句型"连/甚至……都/也……"',explanation_zh:'强调极端情况，含有"更不用说其他的了"的意思。',explanation_en:'Emphasizes extreme situations, with the meaning of "let alone others".',example_zh:"他连汉语都不会说。\n甚至小孩都知道。\n我连一个字都没写。",example_pinyin:"Tā li\xe1n h\xe0nyǔ dōu b\xfa hu\xec shuō.\nSh\xe8nzh\xec xiǎoh\xe1i dōu zhīd\xe0o.\nWǒ li\xe1n y\xed g\xe8 z\xec dōu m\xe9i xiě.",example_en:"He cannot even speak Chinese.\nEven children know it.\nI did not write even a single word.",usage_notes:"连/甚至：强调极端情况，后者更书面；都/也：呼应",category:"句型"},{id:"grammar-6-36",hsk_level:6,pattern:"反问句（难道/哪里/怎么/何必）",title:"反问句",explanation_zh:"用疑问的形式表达确定的意思，答案在问句之中。",explanation_en:"Express definite meaning in the form of a question, with the answer implicit in the question.",example_zh:"难道你不知道吗？\n我哪里知道啊！\n你何必这么着急呢？",example_pinyin:"N\xe1nd\xe0o nǐ b\xf9 zhīd\xe0o ma?\nWǒ nǎlǐ zhīd\xe0o a!\nNǐ h\xe9b\xec zh\xe8me zh\xe1oj\xed ne?",example_en:"Don't you know?\nHow would I know!\nWhy are you in such a hurry?",usage_notes:"反问句：用疑问形式表达肯定或否定，加强语气",category:"句型"},{id:"grammar-6-37",hsk_level:6,pattern:"疑问代词的各种非疑问用法",title:"疑问代词的非疑问用法（全面）",explanation_zh:"疑问代词的任指、虚指、反问等用法。",explanation_en:"Non-interrogative usages of interrogative pronouns: arbitrary reference, indefinite reference, rhetorical question, etc.",example_zh:"谁想去谁去。\n我好像在哪儿见过他。\n谁知道他去哪儿了！",example_pinyin:"Sh\xe9i xiǎng q\xf9 sh\xe9i q\xf9.\nWǒ hǎoxi\xe0ng z\xe0i nǎr ji\xe0nguo tā.\nSh\xe9i zhīd\xe0o tā q\xf9 nǎr le!",example_en:"Whoever wants to go can go.\nI seem to have seen him somewhere.\nWho knows where he went!",usage_notes:"任指：任何；虚指：不确定；反问：加强否定",category:"代词"},{id:"grammar-6-38",hsk_level:6,pattern:"指示代词（每/各/某/另/该/本/其/别）",title:"指示代词（高级）",explanation_zh:"各种指示代词的用法。",explanation_en:"Usages of various demonstrative pronouns.",example_zh:"每个人都要努力。\n各班都有自己的特点。\n某天，他来到了北京。",example_pinyin:"Měi ge r\xe9n dōu y\xe0o nǔl\xec.\nG\xe8 bān dōu yǒu z\xecjǐ de t\xe8diǎn.\nMǒu tiān, tā l\xe1i d\xe0o le běijīng.",example_en:"Everyone must work hard.\nEach class has its own characteristics.\nOne day, he came to Beijing.",usage_notes:"每：任何一个都一样；各：每个不同；某：不确定；另：另外的",category:"代词"},{id:"grammar-6-39",hsk_level:6,pattern:"人称代词的敬称、谦称、泛指",title:"人称代词（扩展）",explanation_zh:"人称代词的各种用法，包括敬称、谦称、泛指等。",explanation_en:"Various usages of personal pronouns, including honorifics, humble forms, generic reference, etc.",example_zh:"您请坐。\n我们公司很有名。\n你要努力啊！",example_pinyin:"N\xedn qǐng zu\xf2.\nWǒmen gōngsī hěn yǒum\xedng.\nNǐ y\xe0o nǔl\xec a!",example_en:"Please sit down (honorific).\nOur company is very famous.\nYou need to work hard!",usage_notes:'您：敬称；我们：可指"我"（谦虚）；你：泛指任何人',category:"代词"},{id:"grammar-6-40",hsk_level:6,pattern:'结构助词"的/地/得"（全面辨析）',title:"结构助词辨析（全面）",explanation_zh:"三个结构助词的详细用法和区别。",explanation_en:"Detailed usages and differences of the three structural particles.",example_zh:"他是一个聪明的学生。\n他认真地学习。\n他学习学得很认真。",example_pinyin:"Tā sh\xec y\xed ge cōngm\xedng de xu\xe9shēng.\nTā r\xe8nzhēn de xu\xe9x\xed.\nTā xu\xe9x\xed xu\xe9 de hěn r\xe8nzhēn.",example_en:"He is a smart student.\nHe studies conscientiously.\nHe studies very conscientiously.",usage_notes:"的：定语标志；地：状语标志；得：补语标志",category:"助词"},{id:"grammar-6-41",hsk_level:6,pattern:'动态助词"了/着/过"（全面辨析）',title:"动态助词辨析（全面）",explanation_zh:"三个动态助词的详细用法和区别。",explanation_en:"Detailed usages and differences of the three aspect particles.",example_zh:"我吃了饭了。\n他看着书呢。\n我去过北京。",example_pinyin:"Wǒ chī le f\xe0n le.\nTā k\xe0nzhe shū ne.\nWǒ q\xf9gu\xf2 běijīng.",example_en:"I have eaten.\nHe is reading a book.\nI have been to Beijing.",usage_notes:"了：完成、实现；着：进行、持续；过：经历、经验",category:"助词"},{id:"grammar-6-42",hsk_level:6,pattern:"语气助词（啊/呢/吧/嘛/呗/罢了/而已）",title:"语气助词（高级）",explanation_zh:"各种语气助词的用法。",explanation_en:"Usages of various modal particles.",example_zh:"你好啊！\n他还没来呢。\n我只是说说而已。",example_pinyin:"Nǐ hǎo a!\nTā h\xe1i m\xe9i l\xe1i ne.\nWǒ zhǐsh\xec shuōshuō \xe9ryǐ.",example_en:"Hello!\nHe has not come yet.\nI am just saying.",usage_notes:"啊：感叹、舒缓；呢：持续、疑问；吧：商量、推测；而已/罢了：仅此而已",category:"助词"},{id:"grammar-6-43",hsk_level:6,pattern:"比况助词（似的/一样/般/那样）",title:"比况助词",explanation_zh:"表示比喻或比较的助词。",explanation_en:"Particles expressing metaphor or comparison.",example_zh:"他像孩子似的。\n他飞一样地跑了。\n珍珠般的眼睛。",example_pinyin:"Tā xi\xe0ng h\xe1izi sh\xec de.\nTā fēi y\xedy\xe0ng de pǎo le.\nZhēnzhū bān de yǎnjing.",example_en:"He is like a child.\nHe ran like flying.\nPearl-like eyes.",usage_notes:"似的/一样/般：表示比喻、比较",category:"助词"},{id:"grammar-6-44",hsk_level:6,pattern:"其他助词（所/等/之类/云云/的话）",title:"其他助词",explanation_zh:"其他各类助词的用法。",explanation_en:"Usages of various other particles.",example_zh:"这是我所说的。\n书、本子等。\n如果有时间的话，请来玩。",example_pinyin:"Zh\xe8 sh\xec wǒ suǒ shuō de.\nShū、běnzi děng.\nR\xfaguǒ yǒu sh\xedjiān dehu\xe0, qǐng l\xe1i w\xe1n.",example_en:"This is what I said.\nBooks, notebooks, etc.\nIf you have time, please come visit.",usage_notes:"所：书面语；等：列举；的话：假设语气",category:"助词"},{id:"grammar-6-45",hsk_level:6,pattern:"处所/方向介词（在/从/向/往/朝/沿/顺/由/打）",title:"处所/方向介词（扩展）",explanation_zh:"各种表示处所和方向的介词。",explanation_en:"Various prepositions indicating location and direction.",example_zh:"我在学校学习。\n他从中国来。\n由这里往前走。",example_pinyin:"Wǒ z\xe0i xu\xe9xi\xe0o xu\xe9x\xed.\nTā c\xf3ng zhōnggu\xf3 l\xe1i.\nY\xf3u zh\xe8lǐ wǎng qi\xe1n zǒu.",example_en:"I study at school.\nHe comes from China.\nWalk forward from here.",usage_notes:"在：位置；从：起点；向/往/朝：方向；沿/顺：顺着；由/打：起点（口语）",category:"介词"},{id:"grammar-6-46",hsk_level:6,pattern:"时间介词（从/自从/到/在/当/趁/临/赶）",title:"时间介词（扩展）",explanation_zh:"各种表示时间的介词。",explanation_en:"Various prepositions indicating time.",example_zh:"我从八点开始学习。\n当他来的时候，我已经走了。\n趁年轻，要多学习。",example_pinyin:"Wǒ c\xf3ng bā diǎn kāishǐ xu\xe9x\xed.\nDāng tā l\xe1i de sh\xedhou, wǒ yǐjīng zǒu le.\nCh\xe8n ni\xe1nqīng, y\xe0o duō xu\xe9x\xed.",example_en:"I start studying from eight o'clock.\nWhen he came, I had already left.\nWhile young, we should study more.",usage_notes:"从/自从：起点；到：终点；当：时候；趁：利用机会；临：将要",category:"介词"},{id:"grammar-6-47",hsk_level:6,pattern:"对象/范围介词（对/对于/关于/至于/就/论）",title:"对象/范围介词（扩展）",explanation_zh:"表示动作的对象或涉及的范围。",explanation_en:"Indicates the object or scope of an action.",example_zh:"他对我很好。\n对于这个问题，我有不同看法。\n就能力而言，他很强。",example_pinyin:"Tā du\xec wǒ hěn hǎo.\nDu\xecy\xfa zh\xe8ge w\xe8nt\xed, wǒ yǒu b\xf9t\xf3ng k\xe0nfǎ.\nJi\xf9 n\xe9ngl\xec \xe9r y\xe1n, tā hěn qi\xe1ng.",example_en:"He is very good to me.\nRegarding this issue, I have different views.\nIn terms of ability, he is very strong.",usage_notes:"对：对象；对于：引进对象；关于：范围；至于：另提；就/论：从某方面说",category:"介词"},{id:"grammar-6-48",hsk_level:6,pattern:"目的/原因介词（为/为了/由于/因/因为）",title:"目的/原因介词（扩展）",explanation_zh:"表示动作的目的或原因。",explanation_en:"Indicates the purpose or cause of an action.",example_zh:"为人民服务。\n为了健康，他每天锻炼。\n由于天气不好，飞机晚点了。",example_pinyin:"W\xe8i r\xe9nm\xedn f\xfaw\xf9.\nW\xe8ile ji\xe0nkāng, tā měitiān du\xe0nli\xe0n.\nY\xf3uy\xfa tiānq\xec b\xf9 hǎo, fēijī wǎndiǎn le.",example_en:"Serve the people.\nFor health, he exercises every day.\nDue to bad weather, the plane was late.",usage_notes:"为/为了：目的；由于/因/因为：原因",category:"介词"},{id:"grammar-6-49",hsk_level:6,pattern:"依据/方式介词（按照/根据/凭/靠/用/以/通过）",title:"依据/方式介词（扩展）",explanation_zh:"表示动作的依据、方式或手段。",explanation_en:"Indicates the basis, method, or means of an action.",example_zh:"请按照规定做。\n他凭自己的努力成功了。\n通过学习，我进步很大。",example_pinyin:"Qǐng \xe0nzh\xe0o guīd\xecng zu\xf2.\nTā p\xedng z\xecjǐ de nǔl\xec ch\xe9nggōng le.\nTōnggu\xf2 xu\xe9x\xed, wǒ j\xecnb\xf9 hěn d\xe0.",example_en:"Please do it according to the rules.\nHe succeeded by his own efforts.\nThrough studying, I have made great progress.",usage_notes:"按照/根据：依据；凭/靠：凭借；用/以：工具方式；通过：媒介",category:"介词"},{id:"grammar-6-50",hsk_level:6,pattern:"施事/受事介词（被/叫/让/给/把/将）",title:"施事/受事介词",explanation_zh:"引出动作的施事或受事。",explanation_en:"Introduces the agent or patient of an action.",example_zh:"杯子被他打破了。\n他把作业做完了。\n将书放在桌子上。",example_pinyin:"Bēizi b\xe8i tā dǎp\xf2 le.\nTā bǎ zu\xf2y\xe8 zu\xf2w\xe1n le.\nJiāng shū f\xe0ng z\xe0i zhuōzi sh\xe0ng.",example_en:"The cup was broken by him.\nHe finished the homework.\nPlace the book on the table.",usage_notes:"被/叫/让/给：引出施事（被动）；把/将：引出受事（处置）",category:"介词"},{id:"grammar-6-51",hsk_level:6,pattern:"程度副词（很/太/非常/十分/极其/格外/分外/尤其）",title:"程度副词（高级）",explanation_zh:"表示动作或性质的程度，各种细微差别。",explanation_en:"Indicates the degree of an action or quality, with various subtle differences.",example_zh:"他很高。\n今天太热了。\n他尤其喜欢音乐。",example_pinyin:"Tā hěn gāo.\nJīntiān t\xe0i r\xe8 le.\nTā y\xf3uq\xed xǐhuan yīnyu\xe8.",example_en:"He is very tall.\nToday is too hot.\nHe especially likes music.",usage_notes:"很：一般；太：过头；非常/十分/极其：程度高；格外/分外：超出平常；尤其：突出",category:"副词"},{id:"grammar-6-52",hsk_level:6,pattern:"范围副词（都/全/皆/统统/一概/总共/一共/仅仅/只/唯独）",title:"范围副词（高级）",explanation_zh:"表示动作或事物的范围。",explanation_en:"Indicates the scope of an action or thing.",example_zh:"我们都去。\n统统拿走。\n只有他没来。",example_pinyin:"Wǒmen dōu q\xf9.\nTǒngtǒng n\xe1zǒu.\nZhǐyǒu tā m\xe9i l\xe1i.",example_en:"We are all going.\nTake all of them.\nOnly he did not come.",usage_notes:"都/全/皆/统统/一概：总括；总共/一共：总计；仅仅/只/唯独：限定",category:"副词"},{id:"grammar-6-53",hsk_level:6,pattern:"时间副词（已经/曾经/刚刚/正/在/正在/将要/即将/终于/终究）",title:"时间副词（高级）",explanation_zh:"表示动作发生的时间和时态。",explanation_en:"Indicates the time and tense of an action.",example_zh:"他已经来了。\n我曾经去过北京。\n他终于成功了。",example_pinyin:"Tā yǐjīng l\xe1i le.\nWǒ c\xe9ngjīng q\xf9gu\xf2 běijīng.\nTā zhōngy\xfa ch\xe9nggōng le.",example_en:"He has already come.\nI have been to Beijing before.\nHe finally succeeded.",usage_notes:"已经/曾经/刚刚：过去；正/在/正在：进行；将要/即将：将来；终于/终究：最终",category:"副词"},{id:"grammar-6-54",hsk_level:6,pattern:"频率副词（再/又/还/也/常常/往往/总是/始终/一向/向来/偶尔）",title:"频率副词（高级）",explanation_zh:"表示动作发生的频率。",explanation_en:"Indicates the frequency of an action.",example_zh:"请再说一遍。\n他常常来。\n他一向很努力。",example_pinyin:"Qǐng z\xe0i shuō y\xed bi\xe0n.\nTā ch\xe1ngch\xe1ng l\xe1i.\nTā y\xedxi\xe0ng hěn nǔl\xec.",example_en:"Please say it again.\nHe often comes.\nHe has always been very hardworking.",usage_notes:"常常/往往：经常；总是/始终/一向/向来：一直；偶尔：间或",category:"副词"},{id:"grammar-6-55",hsk_level:6,pattern:"语气副词（难道/究竟/到底/偏偏/明明/果然/居然/竟然/反倒）",title:"语气副词（高级）",explanation_zh:"表示各种语气，加强或减弱语气。",explanation_en:"Expresses various moods, strengthening or weakening tone.",example_zh:"难道你不知道吗？\n你究竟去不去？\n他偏偏不来。",example_pinyin:"N\xe1nd\xe0o nǐ b\xf9 zhīd\xe0o ma?\nNǐ jiūj\xecng q\xf9 bu q\xf9?\nTā piānpiān b\xf9 l\xe1i.",example_en:"Don't you know?\nAre you going or not?\nHe just refuses to come.",usage_notes:"难道：反问；究竟/到底：追究；偏偏：故意相反；明明：显然；果然/居然/竟然：出乎意料",category:"副词"},{id:"grammar-6-56",hsk_level:6,pattern:"肯定否定副词（必/必须/一定/必定/未必/不必/不曾/未尝）",title:"肯定否定副词（高级）",explanation_zh:"表示肯定或否定的语气。",explanation_en:"Expresses affirmative or negative mood.",example_zh:"你必须来。\n他一定去。\n这未必是真的。",example_pinyin:"Nǐ b\xecxū l\xe1i.\nTā y\xedd\xecng q\xf9.\nZh\xe8 w\xe8ib\xec sh\xec zhēn de.",example_en:"You must come.\nHe will definitely go.\nThis may not necessarily be true.",usage_notes:"必/必须/一定/必定：肯定；未必：不一定；不必/不曾/未尝：否定",category:"副词"},{id:"grammar-6-57",hsk_level:6,pattern:"情态动词（能/会/可以/可能/应该/应当/必须/要/得/愿意/肯）",title:"能愿动词（高级）",explanation_zh:"表示能力、可能性、必要性、意愿等。",explanation_en:"Expresses ability, possibility, necessity, willingness, etc.",example_zh:"我会说汉语。\n你应该努力。\n他愿意帮忙。",example_pinyin:"Wǒ hu\xec shuō h\xe0nyǔ.\nNǐ yīnggāi nǔl\xec.\nTā yu\xe0ny\xec bāngm\xe1ng.",example_en:"I can speak Chinese.\nYou should work hard.\nHe is willing to help.",usage_notes:"能/会/可以：能力、可能；应该/应当/必须：必要；要/得/愿意/肯：意愿",category:"动词"},{id:"grammar-6-58",hsk_level:6,pattern:"离合动词（全面）",title:"离合动词（全面）",explanation_zh:"可以拆开使用的双音节动词，中间可以插入各种成分。",explanation_en:"Disyllabic verbs that can be used separately, with various elements inserted in between.",example_zh:"我每天睡觉睡八个小时。\n他帮了我很大的忙。\n我们见过几次面。",example_pinyin:"Wǒ měitiān shu\xecji\xe0o shu\xec bā ge xiǎosh\xed.\nTā bāng le wǒ hěn d\xe0 de m\xe1ng.\nWǒmen ji\xe0n gu\xf2 jǐ c\xec mi\xe0n.",example_en:"I sleep eight hours every day.\nHe helped me a great deal.\nWe have met several times.",usage_notes:"离合词：睡觉、帮忙、见面、结婚、洗澡、散步、吵架、鼓掌、道歉等",category:"动词"},{id:"grammar-6-59",hsk_level:6,pattern:"动词重叠（AA/ABAB/AABB/一A一A）",title:"动词重叠（高级）",explanation_zh:"动词的各种重叠形式及其用法。",explanation_en:"Various reduplication forms of verbs and their usages.",example_zh:"你看看这本书。\n我们讨论讨论。\n他一跳一跳地走了。",example_pinyin:"Nǐ k\xe0nkan zh\xe8 běn shū.\nWǒmen tǎol\xf9n tǎol\xf9n.\nTā y\xed ti\xe0o y\xed ti\xe0o de zǒu le.",example_en:"Take a look at this book.\nLet's discuss it.\nHe left hopping along.",usage_notes:"AA：单音节；ABAB：双音节；AABB：反复；一A一A：逐次",category:"动词"},{id:"grammar-6-60",hsk_level:6,pattern:"形容词重叠（AA/AABB/ABAB/ABB）",title:"形容词重叠（高级）",explanation_zh:"形容词的各种重叠形式及其用法。",explanation_en:"Various reduplication forms of adjectives and their usages.",example_zh:"大大的眼睛。\n干干净净的房间。\n绿油油的麦苗。",example_pinyin:"D\xe0d\xe0 de yǎnjing.\nGāngānj\xecngj\xecng de f\xe1ngjiān.\nLǜy\xf3uy\xf3u de m\xe0imi\xe1o.",example_en:"Big eyes.\nA clean room.\nGreen and lush wheat seedlings.",usage_notes:"AA：单音节；AABB：双音节；ABAB：状态形容词；ABB：状态词",category:"形容词"},{id:"grammar-6-61",hsk_level:6,pattern:"量词（名量词/动量词/时量词/复合量词/度量词）",title:"量词（全面）",explanation_zh:"各种类型的量词及其用法。",explanation_en:"Various types of measure words and their usages.",example_zh:"三个人、两本书。\n去一趟、看一遍。\n三年、五分钟。",example_pinyin:"Sān g\xe8 r\xe9n、liǎng běn shū.\nQ\xf9 y\xed t\xe0ng、k\xe0n y\xed bi\xe0n.\nSān ni\xe1n、wǔ fēnzhōng.",example_en:"Three people, two books.\nMake a trip, read once.\nThree years, five minutes.",usage_notes:"名量词：事物单位；动量词：动作单位；时量词：时间单位；复合量词：人次、架次等",category:"量词"},{id:"grammar-6-62",hsk_level:6,pattern:"数量短语的句法功能",title:"数量短语的用法（全面）",explanation_zh:"数量短语在句子中的各种语法功能。",explanation_en:"Various grammatical functions of quantity phrases in sentences.",example_zh:"三本书都很好。\n他一次买了三本。\n他跑了三趟。",example_pinyin:"Sān běn shū dōu hěn hǎo.\nTā y\xed c\xec mǎi le sān běn.\nTā pǎo le sān t\xe0ng.",example_en:"All three books are very good.\nHe bought three at once.\nHe ran three trips.",usage_notes:"数量短语可作主语、定语、宾语、补语、状语、谓语等",category:"量词"},{id:"grammar-6-63",hsk_level:6,pattern:"一……就…… / 越……越…… / 又……又……",title:"固定格式（副词）",explanation_zh:"一些常用的副词固定格式。",explanation_en:"Some common fixed adverbial patterns.",example_zh:"我一到就给你打电话。\n我越学越喜欢汉语。\n他又聪明又努力。",example_pinyin:"Wǒ y\xed d\xe0o ji\xf9 gěi nǐ dǎ di\xe0nhu\xe0.\nWǒ yu\xe8 xu\xe9 yu\xe8 xǐhuan h\xe0nyǔ.\nTā y\xf2u cōngm\xedng y\xf2u nǔl\xec.",example_en:"I will call you as soon as I arrive.\nThe more I study, the more I like Chinese.\nHe is both smart and hardworking.",usage_notes:"一……就……：紧接；越……越……：递增；又……又……：并列",category:"副词"},{id:"grammar-6-64",hsk_level:6,pattern:"就/才/都/也/还/又/再",title:"常用副词辨析（全面）",explanation_zh:"一些最常用副词的详细辨析。",explanation_en:"Detailed analysis of some of the most commonly used adverbs.",example_zh:"他八点就来了。\n他十点才来。\n我也要去。",example_pinyin:"Tā bā diǎn ji\xf9 l\xe1i le.\nTā sh\xed diǎn c\xe1i l\xe1i.\nWǒ yě y\xe0o q\xf9.",example_en:"He came as early as eight o'clock.\nHe came as late as ten o'clock.\nI am also going.",usage_notes:"就：早、快、多；才：晚、慢、少；也：同样；都：全部；还：仍然；又：再一次（已发生）；再：再一次（未发生）",category:"副词"},{id:"grammar-6-65",hsk_level:6,pattern:"再/又/还/也",title:'"再/又/还/也"辨析',explanation_zh:"都表示动作重复或继续，但含义和用法不同。",explanation_en:"All indicate repetition or continuation of action, but with different meanings and usages.",example_zh:"请再说一遍。\n他昨天又来了。\n他还没来。\n我也要去。",example_pinyin:"Qǐng z\xe0i shuō y\xed bi\xe0n.\nTā zu\xf3tiān y\xf2u l\xe1i le.\nTā h\xe1i m\xe9i l\xe1i.\nWǒ yě y\xe0o q\xf9.",example_en:"Please say it again.\nHe came again yesterday.\nHe has not come yet.\nI am also going.",usage_notes:"再：未发生的重复；又：已发生的重复；还：持续、仍然；也：同样、并列",category:"副词"},{id:"grammar-6-66",hsk_level:6,pattern:"就/才",title:'"就/才"辨析（全面）',explanation_zh:'"就"和"才"的各种用法及其区别。',explanation_en:'Various usages and differences of "jiu" and "cai".',example_zh:"他八点就来了。\n他十点才来。\n我就要了三个。\n我才有三个。",example_pinyin:"Tā bā diǎn ji\xf9 l\xe1i le.\nTā sh\xed diǎn c\xe1i l\xe1i.\nWǒ ji\xf9 y\xe0o le sān g\xe8.\nWǒ c\xe1i yǒu sān g\xe8.",example_en:"He came as early as eight o'clock.\nHe came as late as ten o'clock.\nI only asked for three.\nI only have three.",usage_notes:"就：早、快、多、容易；才：晚、慢、少、难",category:"副词"},{id:"grammar-6-67",hsk_level:6,pattern:"又……又…… / 既……又…… / 一边……一边…… / 一面……一面……",title:"并列结构辨析",explanation_zh:"各种并列结构的用法区别。",explanation_en:"Differences in usage of various parallel structures.",example_zh:"他又聪明又努力。\n他既聪明又努力。\n他一边吃饭一边看电视。",example_pinyin:"Tā y\xf2u cōngm\xedng y\xf2u nǔl\xec.\nTā j\xec cōngm\xedng y\xf2u nǔl\xec.\nTā y\xecbiān chī f\xe0n y\xecbiān k\xe0n di\xe0nsh\xec.",example_en:"He is both smart and hardworking.\nHe is both smart and hardworking.\nHe eats while watching TV.",usage_notes:"又……又……：两种性质；既……又……：两方面；一边/一面……：同时动作",category:"连词"},{id:"grammar-6-68",hsk_level:6,pattern:"因为/由于/既然",title:"原因连词辨析（全面）",explanation_zh:"表示原因的各种连词的区别。",explanation_en:"Differences between various conjunctions expressing cause.",example_zh:"因为下雨，所以我不去了。\n由于下雨，比赛取消了。\n既然下雨了，就别走了。",example_pinyin:"Yīnw\xe8i xi\xe0 yǔ, suǒyǐ wǒ b\xfa q\xf9 le.\nY\xf3uy\xfa xi\xe0 yǔ, bǐs\xe0i qǔxiāo le.\nJ\xecr\xe1n xi\xe0 yǔ le, ji\xf9 bi\xe9 zǒu le.",example_en:"Because it is raining, I am not going.\nDue to rain, the game was canceled.\nSince it is raining, don't leave.",usage_notes:"因为：说明原因，最常用；由于：较正式；既然：推论因果",category:"连词"},{id:"grammar-6-69",hsk_level:6,pattern:"虽然/尽管/固然",title:"转折连词辨析（全面）",explanation_zh:"表示转折的各种连词的区别。",explanation_en:"Differences between various conjunctions expressing转折.",example_zh:"虽然他很累，但是还在工作。\n尽管困难重重，我们也要坚持。\n这个办法固然好，但是太麻烦。",example_pinyin:"Suīr\xe1n tā hěn l\xe8i, d\xe0nsh\xec h\xe1i z\xe0i gōngzu\xf2.\nJǐnguǎn k\xf9nn\xe1n ch\xf3ngch\xf3ng, wǒmen yě y\xe0o jiānch\xed.\nZh\xe8ge b\xe0nfǎ g\xf9r\xe1n hǎo, d\xe0nsh\xec t\xe0i m\xe1fan.",example_en:"Although he is very tired, he is still working.\nDespite many difficulties, we must persevere.\nThis method is certainly good, but too troublesome.",usage_notes:"虽然：一般转折；尽管：让步语气更重；固然：先承认后转折",category:"连词"},{id:"grammar-6-70",hsk_level:6,pattern:"如果/要是/假如/倘若/万一/一旦",title:"假设连词辨析（全面）",explanation_zh:"表示假设的各种连词的区别。",explanation_en:"Differences between various conjunctions expressing hypothesis.",example_zh:"如果明天下雨，我就不去了。\n要是你有空，请来玩。\n一旦决定了，就不能改变。",example_pinyin:"R\xfaguǒ m\xedngtiān xi\xe0 yǔ, wǒ ji\xf9 b\xfa q\xf9 le.\nY\xe0oshi nǐ yǒu k\xf2ng, qǐng l\xe1i w\xe1n.\nYīd\xe0n ju\xe9d\xecng le, ji\xf9 b\xf9 n\xe9ng gǎibi\xe0n.",example_en:"If it rains tomorrow, I will not go.\nIf you have time, please come visit.\nOnce decided, it cannot be changed.",usage_notes:"如果：最常用；要是：口语化；假如/倘若：书面；万一：可能性小；一旦：强调突然性",category:"连词"},{id:"grammar-6-71",hsk_level:6,pattern:"只要/只有/除非",title:"条件连词辨析（全面）",explanation_zh:"表示条件的各种连词的区别。",explanation_en:"Differences between various conjunctions expressing condition.",example_zh:"只要努力，就能成功。\n只有努力，才能成功。\n除非努力，否则不会成功。",example_pinyin:"Zhǐy\xe0o nǔl\xec, ji\xf9 n\xe9ng ch\xe9nggōng.\nZhǐyǒu nǔl\xec, c\xe1i n\xe9ng ch\xe9nggōng.\nCh\xfafēi nǔl\xec, fǒuz\xe9 b\xfa hu\xec ch\xe9nggōng.",example_en:"As long as you work hard, you can succeed.\nOnly by working hard can you succeed.\nUnless you work hard, you will not succeed.",usage_notes:"只要：充足条件；只有：必要条件；除非：唯一条件",category:"连词"},{id:"grammar-6-72",hsk_level:6,pattern:"不但/不仅/不光/不只……而且/并且/还/也……",title:"递进连词辨析（全面）",explanation_zh:"表示递进关系的各种连词的区别。",explanation_en:"Differences between various conjunctions expressing progressive relationship.",example_zh:"他不但会说英语，而且会说法语。\n不仅我去，大家都去。\n不光是我，他也去。",example_pinyin:"Tā b\xf9d\xe0n hu\xec shuō yīngyǔ, \xe9rqiě hu\xec shuō fǎyǔ.\nB\xf9jǐn wǒ q\xf9, d\xe0jiā dōu q\xf9.\nB\xf9guāng sh\xec wǒ, tā yě q\xf9.",example_en:"He can not only speak English, but also French.\nNot only I am going, everyone is going.\nNot just me, he is also going.",usage_notes:"不但：最常用；不仅：书面；不光/不只：口语化；而且/并且/还/也：呼应",category:"连词"},{id:"grammar-6-73",hsk_level:6,pattern:"无论/不论/不管/任凭……都/也……",title:"无条件连词辨析（全面）",explanation_zh:"表示无条件的各种连词的区别。",explanation_en:"Differences between various conjunctions expressing unconditional.",example_zh:"无论多困难，都要坚持。\n不论是谁，都要遵守规定。\n任凭他怎么说，我都不信。",example_pinyin:"W\xfal\xf9n duō k\xf9nn\xe1n, dōu y\xe0o jiānch\xed.\nB\xf9l\xf9n sh\xec shu\xed, dōu y\xe0o zūnshǒu guīd\xecng.\nR\xe8np\xedng tā zěnme shuō, wǒ dōu b\xf9 x\xecn.",example_en:"No matter how difficult, we must persevere.\nNo matter who it is, they must follow the rules.\nNo matter what he says, I don't believe it.",usage_notes:"无论/不论：较正式；不管：口语化；任凭：书面语，语气最重",category:"连词"},{id:"grammar-6-74",hsk_level:6,pattern:"因为……所以…… / 之所以……是因为…… / 既然……就……",title:"因果复句类型",explanation_zh:"各种类型的因果复句。",explanation_en:"Various types of causal complex sentences.",example_zh:"因为他努力，所以成绩很好。\n他之所以成功，是因为他努力。\n既然他努力，就一定会成功。",example_pinyin:"Yīnw\xe8i tā nǔl\xec, suǒyǐ ch\xe9ngj\xec hěn hǎo.\nTā zhī suǒyǐ ch\xe9nggōng, sh\xec yīnw\xe8i tā nǔl\xec.\nJ\xecr\xe1n tā nǔl\xec, ji\xf9 y\xedd\xecng hu\xec ch\xe9nggōng.",example_en:"Because he works hard, his grades are very good.\nThe reason he succeeded is because he works hard.\nSince he works hard, he will definitely succeed.",usage_notes:"因为……所以……：说明因果；之所以……是因为……：倒装因果；既然……就……：推论因果",category:"连词"},{id:"grammar-6-75",hsk_level:6,pattern:"虽然……但是…… / 即使……也…… / 宁可……也不……",title:"转折/让步复句类型",explanation_zh:"各种类型的转折和让步复句。",explanation_en:"Various types of转折 and concessive complex sentences.",example_zh:"虽然他很累，但是还在工作。\n即使下雨，我也去。\n我宁可不做，也不做错。",example_pinyin:"Suīr\xe1n tā hěn l\xe8i, d\xe0nsh\xec h\xe1i z\xe0i gōngzu\xf2.\nJ\xedshǐ xi\xe0 yǔ, wǒ yě q\xf9.\nWǒ n\xecngkě b\xf9 zu\xf2, yě b\xf9 zu\xf2 cu\xf2.",example_en:"Although he is very tired, he is still working.\nEven if it rains, I will go.\nI would rather not do it than do it wrong.",usage_notes:"虽然……但是……：事实转折；即使……也……：假设让步；宁可……也不……：选择让步",category:"连词"},{id:"grammar-6-76",hsk_level:6,pattern:"定语的位置和多层定语",title:"多层定语",explanation_zh:"多个定语修饰一个名词时的顺序。",explanation_en:"The order when multiple attributives modify a noun.",example_zh:"一件漂亮的红色丝绸衣服。\n我的一个好朋友。\n去年买的那本汉语书。",example_pinyin:"Y\xed ji\xe0n pi\xe0oliang de h\xf3ngs\xe8 sīch\xf3u yīfu.\nWǒ de y\xed ge hǎo p\xe9ngyou.\nQ\xf9ni\xe1n mǎi de n\xe0 běn h\xe0nyǔ shū.",example_en:"A beautiful red silk dress.\nA good friend of mine.\nThat Chinese book bought last year.",usage_notes:"定语顺序：领属+数量+性状+质料+名词",category:"句型"},{id:"grammar-6-77",hsk_level:6,pattern:"状语的位置和多层状语",title:"多层状语",explanation_zh:"多个状语修饰一个动词时的顺序。",explanation_en:"The order when multiple adverbials modify a verb.",example_zh:"他昨天在教室里认真地学习了一天。\n我非常愿意和你一起去。\n他马上就来。",example_pinyin:"Tā zu\xf3tiān z\xe0i ji\xe0osh\xec lǐ r\xe8nzhēn de xu\xe9x\xed le y\xec tiān.\nWǒ fēich\xe1ng yu\xe0ny\xec h\xe9 nǐ y\xecqǐ q\xf9.\nTā mǎsh\xe0ng ji\xf9 l\xe1i.",example_en:"He studied seriously in the classroom all day yesterday.\nI am very willing to go with you.\nHe will come right away.",usage_notes:"状语顺序：时间+处所+范围+情态+对象+动词",category:"句型"},{id:"grammar-6-78",hsk_level:6,pattern:"补语的类型和用法（结果/趋向/情态/可能/数量/程度）",title:"补语系统（全面）",explanation_zh:"汉语中各种类型的补语。",explanation_en:"Various types of complements in Chinese.",example_zh:"他做完了作业。\n他走进来了。\n他跑得很快。\n我吃得完。\n我学了三年。",example_pinyin:"Tā zu\xf2w\xe1n le zu\xf2y\xe8.\nTā zǒu j\xecnl\xe1i le.\nTā pǎo de hěn ku\xe0i.\nWǒ chī de w\xe1n.\nWǒ xu\xe9 le sān ni\xe1n.",example_en:"He finished the homework.\nHe walked in.\nHe runs very fast.\nI can finish eating.\nI studied for three years.",usage_notes:"补语类型：结果补语、趋向补语、情态补语、可能补语、数量补语、程度补语",category:"补语"},{id:"grammar-6-79",hsk_level:6,pattern:"复句的类型和关联词",title:"复句系统（全面）",explanation_zh:"汉语中各种类型的复句及其关联词语。",explanation_en:"Various types of complex sentences and their correlative words in Chinese.",example_zh:"因为他努力，所以成绩很好。\n虽然他很累，但是还在工作。\n如果明天下雨，我就不去了。",example_pinyin:"Yīnw\xe8i tā nǔl\xec, suǒyǐ ch\xe9ngj\xec hěn hǎo.\nSuīr\xe1n tā hěn l\xe8i, d\xe0nsh\xec h\xe1i z\xe0i gōngzu\xf2.\nR\xfaguǒ m\xedngtiān xi\xe0 yǔ, wǒ ji\xf9 b\xfa q\xf9 le.",example_en:"Because he works hard, his grades are very good.\nAlthough he is very tired, he is still working.\nIf it rains tomorrow, I will not go.",usage_notes:"复句类型：并列、承接、递进、选择、转折、因果、假设、条件、目的等",category:"连词"},{id:"grammar-6-80",hsk_level:6,pattern:"多重复句和句群",title:"多重复句",explanation_zh:"包含两个或以上层次的复句。",explanation_en:"Complex sentences containing two or more levels.",example_zh:"虽然他很努力，但是因为方法不对，所以成绩不好。\n只要你认真学，并且坚持下去，就一定能学好汉语。",example_pinyin:"Suīr\xe1n tā hěn nǔl\xec, d\xe0nsh\xec yīnw\xe8i fāngfǎ b\xfa du\xec, suǒyǐ ch\xe9ngj\xec b\xf9 hǎo.\nZhǐy\xe0o nǐ r\xe8nzhēn xu\xe9, b\xecngqiě jiānch\xed xi\xe0q\xf9, ji\xf9 y\xedd\xecng n\xe9ng xu\xe9hǎo h\xe0nyǔ.",example_en:"Although he works very hard, because his method is wrong, his grades are not good.\nAs long as you study seriously and persist, you will definitely learn Chinese well.",usage_notes:"多重复句：包含两个或以上层次的复句，需要分析层次关系",category:"连词"}]}}]);